CREATE OR REPLACE PYTHON3 SCALAR SCRIPT PREPROC_RT.CONFD_QUERY_V1(connection_name VARCHAR(128), job_name VARCHAR(128), params_json VARCHAR(2000000)) EMITS (field VARCHAR(256), value_text VARCHAR(2000000)) AS
# =============================================================================
# CONFD_QUERY_V1  (PREPROC_RT.CONFD_QUERY_V1)  — Python3 SCALAR EMITS UDF body
# =============================================================================
# Inline-capable variant of CONFD_JOB_V1 for READ commands. Where CONFD_JOB_V1
# is a SCALAR ... RETURNS VARCHAR that must be wrapped by the Lua admin script
# PREPROC.ADMIN_CONFD_JOB (which flattens the JSON envelope into a table and
# re-raises errors), this UDF does BOTH jobs itself:
#
#   * calls the ConfD job over XML-RPC (the network role), and
#   * EMITS one (FIELD, VALUE_TEXT) row per leaf value of result_output (the
#     presentation role the Lua flatten() used to own), and
#   * RAISES on any failure instead of returning an 'ERR:' sentinel (the loud
#     error role the Lua error() call used to own).
#
# Because it is a UDF expression rather than an EXECUTE SCRIPT statement, a
# CONTROL command that rewrites into a call to this UDF can be EMBEDDED inside a
# larger SQL statement:
#
#     INSERT INTO t SELECT * FROM (
#         SELECT PREPROC_RT.CONFD_QUERY_V1('CONFD_CONNECTION','db_info','{"db_name":""}')
#         FROM (SELECT 1))
#
# whereas EXECUTE SCRIPT can only ever stand alone. Eliminating the Lua middle
# layer for read commands is what makes inline use possible.
#
# Contract change vs CONFD_JOB_V1
#   No ERR: sentinel. run() RAISES. A failed ConfD job (transport error, missing
#   CONNECTION, non-zero envelope result_code) aborts the surrounding statement
#   with a visible SQL error — exactly what ADMIN_CONFD_JOB's error() achieved,
#   but now with no Lua layer in the path.
#
# This file is BOTH an importable module (unit-tested via tests/test_confd_query.py)
# and the verbatim body embedded into the CREATE PYTHON3 SCALAR SCRIPT by build.py.
# The `exa` runtime object and ctx.emit are only touched inside run(); every piece
# of logic is dependency-injected so the tests need no database.
# =============================================================================
import json
import ssl
import xmlrpc.client
from urllib.parse import quote as _urlquote


def _build_endpoint(address, user, password):
    """Build the XML-RPC URL 'scheme://user:password@host:port'. Identical to
    CONFD_JOB_V1._build_endpoint (kept self-contained: UDF bodies are embedded
    verbatim and cannot import a sibling)."""
    addr = address or ""
    if "://" in addr:
        scheme, rest = addr.split("://", 1)
    else:
        scheme, rest = "https", addr
    if "@" in rest:
        rest = rest.split("@", 1)[1]
    return "{}://{}:{}@{}".format(
        scheme,
        _urlquote(user or "", safe=""),
        _urlquote(password or "", safe=""),
        rest,
    )


def _prepare_params(params_json, default_db_name):
    """Parse the JSON params and fill an opted-in (empty-string) db_name. Same
    opt-in inference as CONFD_JOB_V1: the current database is substituted only
    when the caller passes db_name as an empty string."""
    params = {}
    if params_json is not None and str(params_json).strip() != "":
        params = json.loads(params_json)
    if not isinstance(params, dict):
        raise ValueError("params_json must be a JSON object")
    if "db_name" in params and not params["db_name"]:
        params["db_name"] = default_db_name
    return params


def _call_confd(connection, default_db_name, job_name, params_json, proxy_factory=None):
    """Prepare params, build the endpoint, run the ConfD job, and return the
    decoded envelope (a dict). Raises on transport failure."""
    params = _prepare_params(params_json, default_db_name)
    endpoint = _build_endpoint(connection.address, connection.user, connection.password)
    if proxy_factory is None:
        sslctx = ssl._create_unverified_context()

        def proxy_factory(url):
            return xmlrpc.client.ServerProxy(url, context=sslctx, allow_none=True)

    server = proxy_factory(endpoint)
    return server.job_exec(job_name, {"params": params})


def _check_envelope(envelope, job_name):
    """Raise if the ConfD envelope reports a non-zero result_code. This replaces
    the result_code check that ADMIN_CONFD_JOB did in Lua."""
    if isinstance(envelope, dict):
        code = envelope.get("result_code")
        if isinstance(code, int) and code != 0:
            desc = envelope.get("result_desc") or envelope.get("result_name") or ""
            raise RuntimeError(
                "ConfD job '{}' failed (code {}): {}".format(job_name, code, desc)
            )


def _scalar_text(value):
    """Render a JSON leaf the way the Lua flatten() did: booleans as
    true/false, integral floats without a trailing .0, everything else str()."""
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value)


def _flatten(prefix, value, rows):
    """Flatten an arbitrarily-nested decoded value into (field, value_text)
    tuples. Mirrors admin_confd_job.lua flatten(): object keys are sorted and
    joined with '.', array elements use a 1-based [i] suffix, JSON null and empty
    containers get explicit leaf markers."""
    label = prefix if prefix != "" else "value"
    if value is None:
        rows.append((label, "null"))
        return
    if isinstance(value, dict):
        if not value:
            rows.append((label, "(empty)"))
            return
        for k in sorted(value.keys(), key=str):
            child = str(k) if prefix == "" else prefix + "." + str(k)
            _flatten(child, value[k], rows)
        return
    if isinstance(value, list):
        if not value:
            rows.append((label, "(empty)"))
            return
        for i, item in enumerate(value, start=1):
            _flatten(prefix + "[" + str(i) + "]", item, rows)
        return
    rows.append((label, _scalar_text(value)))


def _rows_for(envelope):
    """Turn a decoded ConfD envelope into the FIELD/VALUE_TEXT rows to emit.

    A dict envelope surfaces only result_output (the operator-relevant payload):
    when result_output is present and non-null the value is flattened leaf by
    leaf (an empty container renders as a single "(empty)" marker); when
    result_output is null or absent the job succeeded with no output, so a single
    `status | <result_name or OK>` row confirms success — never an empty result
    set and never the flattened envelope. A non-dict envelope is flattened
    directly."""
    if isinstance(envelope, dict):
        output = envelope.get("result_output")
        if output is None:
            return [("status", str(envelope.get("result_name") or "OK"))]
        rows = []
        _flatten("", output, rows)
        return rows
    rows = []
    _flatten("", envelope, rows)
    return rows


def run(ctx):
    # No ERR: sentinel and no try/except: a failure MUST raise so it surfaces as
    # a visible SQL error and aborts the surrounding statement.
    connection = exa.get_connection(ctx.connection_name)  # noqa: F821 (exa: runtime)
    envelope = _call_confd(
        connection,
        exa.meta.database_name,  # noqa: F821
        ctx.job_name,
        ctx.params_json,
    )
    _check_envelope(envelope, ctx.job_name)
    for field, value_text in _rows_for(envelope):
        ctx.emit(field, value_text)
