CREATE OR REPLACE PYTHON3 SCALAR SCRIPT PREPROC_RT.VIRTUAL_RESTORE_V1(connection_name VARCHAR(128), vr_action VARCHAR(32), params_json VARCHAR(2000000)) RETURNS VARCHAR(2000000) AS
# =============================================================================
# VIRTUAL_RESTORE_V1  (PREPROC_RT.VIRTUAL_RESTORE_V1)  — Python3 SCALAR UDF body
# =============================================================================
# Orchestrator UDF for the CONTROL DATABASE … VIRTUAL RESTORE command family.
# Given a ConfD CONNECTION object name, an action ('start' or 'stop'), and a
# JSON parameter object, it drives the full lifecycle of an Exasol "Virtual
# Access on Backup" instance via ConfD XML-RPC and BucketFS HTTP.
#
# This file is BOTH:
#   * a normal importable Python module (so the logic is unit-testable without
#     a database — see tests/test_virtual_restore.py), and
#   * the verbatim body embedded into the CREATE PYTHON3 SCALAR SCRIPT by
#     build.py. The `exa` runtime object is only referenced inside run(), so
#     the module imports cleanly outside Exasol; the testable logic lives in
#     the dependency-injected helper _execute().
#
# UDF signature (declared in the CREATE script header by build.py):
#   PREPROC_RT.VIRTUAL_RESTORE_V1(connection_name VARCHAR, vr_action VARCHAR,
#                                  params_json     VARCHAR)
#   RETURNS VARCHAR(2000000)
#   The parameter is vr_action, not action — ACTION is a reserved keyword in
#   Exasol and cannot be used as an identifier.
#
# Return contract — the ERR: sentinel
#   run() NEVER raises. On success it returns a JSON step-report document. On
#   ANY failure it returns 'ERR:<message>'. The calling Lua admin script
#   (PREPROC.ADMIN_VIRTUAL_RESTORE) checks for the ERR: prefix and re-raises
#   it as a loud script error, ensuring failures are never silently swallowed.
#
# Credentials / endpoint
#   Read from the named CONNECTION object via exa.get_connection(). Expected shape:
#     CREATE CONNECTION CONFD_CONNECTION
#         TO 'https://<host>:20003'
#         USER '<confd_user>' IDENTIFIED BY '<password>';
#   .address supplies scheme+host+port (scheme defaults to https if omitted),
#   .user / .password supply XML-RPC basic-auth credentials.
#
# Dependency injection
#   _execute() accepts optional proxy_factory, http, sleep, and monotonic
#   parameters. Tests pass fake implementations; run() wires in live stdlib.
#   This keeps network, clock, and HTTP state entirely outside the module.
#
# TLS
#   ConfD ships a self-signed certificate; an unverified SSL context is used.
#   BucketFS HTTP (port 2580) is plain HTTP and needs no SSL context.
#
# Self-contained
#   build.py embeds this file verbatim as a UDF body, so it MUST NOT import
#   anything outside the Python stdlib and MUST NOT produce side effects at
#   import time.
# =============================================================================
import base64
import json
import re
import ssl
import time as _time_module
import xmlrpc.client
from urllib.parse import quote as _urlquote
from urllib.request import Request as _Request, urlopen as _urlopen


# ---------------------------------------------------------------------------
# Module constants
# ---------------------------------------------------------------------------

_POLL_INTERVAL_SECS = 5
_BUCKETFS_HTTP_PORT = 2580
_DEFAULT_ADAPTER_JAR_DIR = "/buckets/bfsdefault/default/"


# ---------------------------------------------------------------------------
# Internal helpers (copied from confd_job_v1.py — file must stay self-contained)
# ---------------------------------------------------------------------------

def _build_endpoint(address, user, password):
    """Build the XML-RPC URL 'scheme://user:password@host:port' from a
    CONNECTION's address plus credentials.

    The address may or may not carry a scheme and may already embed credentials
    (which are stripped and replaced). ConfD speaks HTTPS; a bare host:port
    is assumed to be https.
    """
    addr = address or ""
    if "://" in addr:
        scheme, rest = addr.split("://", 1)
    else:
        scheme, rest = "https", addr
    if "@" in rest:
        rest = rest.split("@", 1)[1]
    return "{}://{}:{}@{}".format(
        scheme,
        _urlquote(user or "", safe=""),
        _urlquote(password or "", safe=""),
        rest,
    )


def _host_from_address(address):
    """Extract the bare hostname (no scheme, no port, no credentials) from a
    CONNECTION address string. Used to construct BucketFS HTTP URLs.
    """
    addr = address or ""
    if "://" in addr:
        rest = addr.split("://", 1)[1]
    else:
        rest = addr
    if "@" in rest:
        rest = rest.split("@", 1)[1]
    host = rest.split(":")[0]
    return host


def _identifier_ok(name):
    """Return True if name matches ^[A-Za-z][A-Za-z0-9_]*$."""
    return bool(re.match(r'^[A-Za-z][A-Za-z0-9_]*$', name))


def _redact(text):
    """Remove secrets from URLs embedded in exception/error messages.

    Strips both basic-auth credentials (user:pass@) and URL query strings
    (?...). xmlrpc.client.ProtocolError renders the ConfD endpoint without a
    scheme (user:pass@host:port), so the credential pattern is matched with or
    without a leading scheme://; presigned source URLs carry their signature
    in the query string. Both are secrets that must never appear in ERR:
    strings.
    """
    s = re.sub(r'[^/@\s:]+:[^/@\s]+@', '<redacted>@', str(text))
    s = re.sub(r'\?[^\s"\']*', '?<redacted>', s)
    return s


# ---------------------------------------------------------------------------
# ConfD call helpers
# ---------------------------------------------------------------------------

def _confd_call(server, job, params):
    """Call server.job_exec(job, {"params": params}) and return the result dict.

    Raises RuntimeError if result_code is non-zero.
    """
    result = server.job_exec(job, {"params": params})
    code = result.get("result_code", 0) if isinstance(result, dict) else 0
    if code != 0:
        desc = ""
        if isinstance(result, dict):
            desc = result.get("result_desc") or result.get("result_name") or ""
        raise RuntimeError(
            "ConfD job '{}' failed (code {}): {}".format(job, code, desc)
        )
    return result


def _default_proxy_factory(url):
    """Build a live XML-RPC ServerProxy with an unverified SSL context."""
    sslctx = ssl._create_unverified_context()
    return xmlrpc.client.ServerProxy(url, context=sslctx, allow_none=True)


# ---------------------------------------------------------------------------
# Default HTTP callable
# ---------------------------------------------------------------------------

def _default_http(method, url, auth=None, data=None):
    """Minimal HTTP client backed by urllib. Returns (status_code, body_bytes).

    auth: (user, password) tuple for HTTP Basic auth, or None.
    data: bytes body for PUT/POST, or None.
    Ignores SSL certificate errors (BucketFS may serve a self-signed cert).
    """
    req = _Request(url, data=data, method=method)
    if auth is not None:
        raw = "{}:{}".format(auth[0], auth[1]).encode("utf-8")
        req.add_header("Authorization", "Basic " + base64.b64encode(raw).decode())
    ctx = ssl._create_unverified_context()
    try:
        with _urlopen(req, context=ctx, timeout=60) as resp:
            return resp.status, resp.read()
    except Exception as exc:
        code = getattr(getattr(exc, "reason", None), "errno", None) or 0
        return (getattr(exc, "code", 0) or code or -1, str(exc).encode())


# ---------------------------------------------------------------------------
# Step report helpers
# ---------------------------------------------------------------------------

def _step(name, status, detail=""):
    """Build a single step-report entry dict."""
    return {"step": name, "status": status, "detail": detail}


# ---------------------------------------------------------------------------
# Rollback helper
# ---------------------------------------------------------------------------

def _delete_data_volumes(server, volume_name, issues):
    """Delete every EXAStorage volume carrying `volume_name`.

    Volume "names" are labels, so duplicates can exist (e.g. after a partial
    rollback); delete repeatedly until no volume with that name remains.
    Returns the number of volumes deleted; failure notes go to `issues`.
    """
    deleted = 0
    for _ in range(8):
        try:
            listing = _confd_call(server, "st_volume_list", {})
            entries = listing.get("result_output") or []
            if not any(
                isinstance(v, dict) and v.get("name") == volume_name for v in entries
            ):
                break
            _confd_call(server, "st_volume_delete", {"vname": volume_name})
            deleted += 1
        except Exception as exc:
            issues.append("st_volume_delete: " + _redact(exc))
            break
    return deleted


def _rollback(server, vdb_name, created_db, created_volume, issues):
    """Best-effort reverse-order teardown of resources that were created.

    Appends human-readable failure notes to `issues` (a list) but never
    raises. created_db implies we should attempt db_stop then db_delete;
    created_volume implies st_volume_delete. All calls go through
    _confd_call so a ConfD-level failure (non-zero result_code) is recorded
    rather than silently treated as success.
    """
    if created_db:
        try:
            _confd_call(server, "db_stop", {"db_name": vdb_name})
        except Exception as exc:
            issues.append("db_stop: " + _redact(exc))
        try:
            _confd_call(server, "db_delete", {"db_name": vdb_name})
        except Exception as exc:
            issues.append("db_delete: " + _redact(exc))
    if created_volume:
        _delete_data_volumes(server, vdb_name + "_DATA", issues)


# ---------------------------------------------------------------------------
# Adapter JAR helpers
# ---------------------------------------------------------------------------

def _parse_bucketfs_path(adapter_jar_path):
    """Parse '/buckets/<bfsname>/<bucket>/...' into (bfsname, bucket, path_suffix).

    path_suffix is everything after '/buckets/<bfsname>/<bucket>/' and is used
    as the BucketFS HTTP URL path component. Returns None on parse failure.
    """
    p = adapter_jar_path.lstrip("/")
    parts = p.split("/", 3)
    if len(parts) < 3 or parts[0] != "buckets":
        return None
    bfsname = parts[1]
    bucket = parts[2]
    suffix = parts[3] if len(parts) == 4 else ""
    return bfsname, bucket, suffix


def _ensure_adapter_jar(
    server, confd_host, adapter_jar_path, http, steps, issues
):
    """Ensure the adapter JAR exists in BucketFS.

    Strategy:
      1. Resolve the latest exasol-virtual-schema release via GitHub API,
         download the virtual-schema-dist-*.jar asset, PUT it to BucketFS.
      2. If download fails AND a concrete jar filename is resolvable, HEAD the
         target BucketFS path. If the file exists, add a 'skipped' step and
         return the jar path.
      3. If neither works, append to issues and return None (caller must
         rollback and ERR).

    When no jar filename is resolvable (no suffix, or suffix ends in '/'),
    the existence check is skipped — a BucketFS directory listing would
    return 200 and falsely appear as a found jar.

    Returns the resolved adapter_jar_path on success, or None on hard failure.
    """
    parsed = _parse_bucketfs_path(adapter_jar_path)
    if parsed is None:
        issues.append(
            "adapter jar: could not parse BucketFS path '{}'".format(adapter_jar_path)
        )
        return None

    bfsname, bucket, suffix = parsed
    jar_name = suffix.split("/")[-1] if suffix else ""

    # Discover the BucketFS endpoint and bucket credentials in one call:
    # deployments may disable plain HTTP (http_port 0) and serve HTTPS only,
    # and the bucket passwords sit base64-encoded in the nested buckets map
    # (fields read_passwd/write_passwd). There is no separate bucket_info job.
    base_url = "http://{}:{}".format(confd_host, _BUCKETFS_HTTP_PORT)
    write_password = None
    read_password = None
    try:
        fi = _confd_call(server, "bucketfs_info", {"bucketfs_name": bfsname})
        fs_out = fi.get("result_output", {}) if isinstance(fi.get("result_output"), dict) else {}
        http_port = int(fs_out.get("http_port") or 0)
        https_port = int(fs_out.get("https_port") or 0)
        if http_port:
            base_url = "http://{}:{}".format(confd_host, http_port)
        elif https_port:
            base_url = "https://{}:{}".format(confd_host, https_port)
        buckets = fs_out.get("buckets") if isinstance(fs_out.get("buckets"), dict) else {}
        binfo = buckets.get(bucket) if isinstance(buckets.get(bucket), dict) else {}
        raw_w = binfo.get("write_passwd") or binfo.get("write_password") or ""
        raw_r = binfo.get("read_passwd") or binfo.get("read_password") or ""
        if raw_w:
            write_password = base64.b64decode(raw_w).decode("utf-8")
        if raw_r:
            read_password = base64.b64decode(raw_r).decode("utf-8")
    except Exception as exc:
        issues.append("bucketfs_info: " + _redact(exc))
    if write_password is None:
        issues.append(
            "bucket '{}/{}': no write password available — cannot upload".format(
                bfsname, bucket
            )
        )

    github_api = "https://api.github.com/repos/exasol/exasol-virtual-schema/releases/latest"
    download_ok = False
    asset_name = None
    jar_bytes = None
    try:
        status, body = http("GET", github_api)
        if status != 200:
            issues.append("github release lookup: HTTP {}".format(status))
        else:
            release = json.loads(body)
            assets = release.get("assets", [])
            for asset in assets:
                name = asset.get("name", "")
                if re.match(r"virtual-schema-dist-.*\.jar$", name):
                    asset_name = name
                    asset_url = asset.get("browser_download_url", "")
                    dl_status, dl_body = http("GET", asset_url)
                    if dl_status == 200:
                        jar_bytes = dl_body
                        if not jar_name:
                            jar_name = asset_name
                    else:
                        issues.append(
                            "jar download '{}': HTTP {}".format(name, dl_status)
                        )
                    break
            if asset_name is None:
                issues.append("github release has no virtual-schema-dist-*.jar asset")
    except Exception as exc:
        issues.append("jar download: " + _redact(exc))

    if jar_bytes is not None:
        if write_password is not None:
            # BucketFS URL path is /<bucket>/<file> — the service (bfsname) is
            # selected by the port, not by a path component.
            bfs_url = "{}/{}/{}".format(base_url, bucket, jar_name)
            try:
                put_status, _ = http("PUT", bfs_url, auth=("w", write_password), data=jar_bytes)
                if put_status in (200, 201, 204):
                    download_ok = True
                    steps.append(_step(
                        "adapter_jar_upload",
                        "ok",
                        "uploaded {} to {}".format(jar_name, bfs_url),
                    ))
                else:
                    issues.append("BucketFS PUT: HTTP {}".format(put_status))
            except Exception as exc:
                issues.append("BucketFS PUT: " + _redact(exc))

    if download_ok:
        return "/buckets/{}/{}/{}".format(bfsname, bucket, jar_name)

    # Fallback existence check only makes sense for a concrete file path.
    # An empty jar_name means the configured path is a directory; BucketFS
    # returns 200 for directory listings, which would be a false positive.
    if not jar_name:
        issues.append(
            "adapter jar not found: download failed and no jar filename in '{}'; "
            "upload the adapter jar manually".format(adapter_jar_path)
        )
        return None

    bfs_read_url = "{}/{}/{}".format(base_url, bucket, jar_name)
    read_auth = ("r", read_password) if read_password else None
    try:
        check_status, _ = http("GET", bfs_read_url, auth=read_auth)
        if check_status == 200:
            steps.append(_step(
                "adapter_jar_upload",
                "skipped",
                "download failed; using existing jar at {}".format(adapter_jar_path),
            ))
            return adapter_jar_path
    except Exception:
        pass

    issues.append(
        "adapter jar not found: download failed and no existing jar at '{}'; "
        "upload the adapter jar manually".format(adapter_jar_path)
    )
    return None


# ---------------------------------------------------------------------------
# action = 'start'
# ---------------------------------------------------------------------------

def _run_start(params, server, issuing_db_name, confd_host, http, sleep, monotonic):
    """Orchestrate START VIRTUAL RESTORE. Returns (report_dict, err_string).

    On success: (report_dict, None).
    On failure: (partial_report, "ERR:<message>").
    """
    steps = []
    created_volume = False
    created_db = False

    vdb_name = params["vdb_name"]
    backup_id = params["backup_id"]
    schemas = params["schemas"]
    jdbc_connection = params["jdbc_connection"]
    exa_connection = params.get("exa_connection")
    port = int(params["port"])
    mem_size = params["mem_size"]
    volume_size = params["volume_size"]
    timeout = int(params["timeout"])
    adapter_jar_override = params.get("adapter_jar")

    try:
        bl = _confd_call(server, "db_backup_list", {"db_name": issuing_db_name})
    except Exception as exc:
        return None, "ERR:preflight: db_backup_list failed: " + _redact(exc)

    backup_list = bl.get("result_output", {})
    if isinstance(backup_list, dict):
        backup_list = backup_list.get("backups", [])
    if not isinstance(backup_list, list):
        backup_list = []

    backup_entry = None
    for entry in backup_list:
        if isinstance(entry, dict):
            eid = entry.get("id") or entry.get("backup_id") or entry.get("name") or ""
            if str(eid) == backup_id:
                backup_entry = entry
                break

    if backup_entry is None:
        return None, "ERR:preflight: backup '{}' not found in db_backup_list".format(backup_id)

    expiry = backup_entry.get("expire") or backup_entry.get("expiration")
    if expiry not in (None, "", "None"):
        return (
            None,
            "ERR:preflight: backup '{}' has an expiry date "
            "— virtual access requires no expiry".format(backup_id),
        )

    vol_id = backup_id.split()[0] if backup_id.strip() else ""
    if not vol_id:
        return None, "ERR:preflight: cannot determine archive volume from backup_id '{}'".format(backup_id)

    # The backup id's first token is the EXAStorage volume ID (numeric) for
    # local archive volumes; remote volumes carry non-numeric ids (e.g. r0001)
    # and are not valid virtual-access sources.
    if not vol_id.isdigit():
        return (
            None,
            "ERR:preflight: backup volume '{}' is not a LOCAL archive volume "
            "— virtual access requires LOCAL".format(vol_id),
        )

    try:
        vi = _confd_call(server, "st_volume_info", {"vid": int(vol_id)})
    except Exception as exc:
        return (
            None,
            "ERR:preflight: st_volume_info failed for volume '{}': {}".format(
                vol_id, _redact(exc)
            ),
        )

    vol_info = vi.get("result_output", {}) if isinstance(vi.get("result_output"), dict) else {}
    # st_volume_info's `type` field is the EXAStorage segment role (MASTER),
    # NOT the volume class; archive volumes are identified by their labels
    # (e.g. ["#Name#arc_vol", "sdfs", "sdfs:archive"]). A URL only appears on
    # remote storage, which is not a valid virtual-access source.
    vol_url = str(vol_info.get("url", "") or vol_info.get("path", "") or "")
    if "://" in vol_url:
        return (
            None,
            "ERR:preflight: backup volume '{}' is not a LOCAL archive volume "
            "— virtual access requires LOCAL".format(vol_id),
        )
    labels = vol_info.get("labels") or []
    label_text = " ".join(str(label) for label in labels).lower()
    if labels and "archive" not in label_text and "sdfs" not in label_text:
        return (
            None,
            "ERR:preflight: backup volume '{}' is not a LOCAL archive volume "
            "— virtual access requires LOCAL".format(vol_id),
        )

    disk = vol_info.get("disk") or vol_info.get("hdd_type") or vol_info.get("disk_id") or "default"
    num_master_nodes = vol_info.get("num_master_nodes") or vol_info.get("master_nodes", 1)
    nodes = vol_info.get("nodes") or []
    if not isinstance(nodes, list):
        nodes = list(nodes) if nodes else []

    try:
        di = _confd_call(server, "db_info", {"db_name": issuing_db_name})
    except Exception as exc:
        return None, "ERR:preflight: db_info failed: " + _redact(exc)

    db_info_out = di.get("result_output", {}) if isinstance(di.get("result_output"), dict) else {}
    # The database version lives in the nested config object
    # (result_output.config.version); older field names are kept as fallbacks.
    db_config = db_info_out.get("config") if isinstance(db_info_out.get("config"), dict) else {}
    version = str(
        db_config.get("version")
        or db_info_out.get("version")
        or db_info_out.get("db_version")
        or ""
    )
    if not version:
        return None, "ERR:preflight: cannot determine database version from db_info"

    steps.append(_step("preflight", "ok", "backup found; volume is LOCAL archive"))

    rollback_issues = []
    data_volume_name = vdb_name + "_DATA"
    try:
        _confd_call(server, "st_volume_create", {
            "name": data_volume_name,
            "type": "data",
            "size": volume_size,
            "redundancy": 1,
            "owner": [500, 500],
            "disk": disk,
            "num_master_nodes": num_master_nodes,
            "nodes": nodes,
        })
        created_volume = True
        steps.append(_step("st_volume_create", "ok", "created {}".format(data_volume_name)))
    except Exception as exc:
        err = "ERR:st_volume_create: " + _redact(exc)
        _rollback(server, vdb_name, created_db, created_volume, rollback_issues)
        if rollback_issues:
            err += "; rollback issues: " + "; ".join(rollback_issues)
        return None, err

    db_create_params = {
        "db_name": vdb_name,
        "data_volume_name": data_volume_name,
        "mem_size": mem_size,
        "port": port,
        "owner": [500, 500],
        "num_active_nodes": len(nodes) if nodes else num_master_nodes,
        "nodes": nodes,
    }
    if version:
        db_create_params["version"] = version
    try:
        _confd_call(server, "db_create", db_create_params)
        created_db = True
        steps.append(_step("db_create", "ok", "created {}".format(vdb_name)))
    except Exception as exc:
        err = "ERR:db_create: " + _redact(exc)
        _rollback(server, vdb_name, created_db, created_volume, rollback_issues)
        if rollback_issues:
            err += "; rollback issues: " + "; ".join(rollback_issues)
        return None, err

    try:
        _confd_call(server, "db_restore", {
            "db_name": vdb_name,
            "backup_id": backup_id,
            "restore_type": "virtual access",
        })
        steps.append(_step("db_restore", "ok", "restore initiated"))
    except Exception as exc:
        err = "ERR:db_restore: " + _redact(exc)
        _rollback(server, vdb_name, created_db, created_volume, rollback_issues)
        if rollback_issues:
            err += "; rollback issues: " + "; ".join(rollback_issues)
        return None, err

    deadline = monotonic() + timeout
    db_state_val = None
    while True:
        try:
            ds = _confd_call(server, "db_state", {"db_name": vdb_name})
            # db_state's result_output is the bare state string (e.g.
            # "running"); older/other shapes nest it in a dict.
            ro = ds.get("result_output")
            if isinstance(ro, dict):
                db_state_val = str(ro.get("state") or ro.get("db_state") or "").lower()
            else:
                db_state_val = str(ro or "").lower()
        except Exception:
            db_state_val = ""

        # state == running is necessary but not sufficient: the instance
        # accepts SQL connections only once db_info reports connectible, and
        # the virtual-schema adapter connects immediately after this poll.
        if db_state_val == "running":
            try:
                vi = _confd_call(server, "db_info", {"db_name": vdb_name})
                vout = vi.get("result_output")
                connectible = ""
                if isinstance(vout, dict):
                    connectible = str(vout.get("connectible") or "").lower()
                if connectible == "yes":
                    break
            except Exception:
                pass

        if monotonic() >= deadline:
            err = "ERR:timeout: virtual DB '{}' did not reach state running within {}s".format(
                vdb_name, timeout
            )
            _rollback(server, vdb_name, created_db, created_volume, rollback_issues)
            if rollback_issues:
                err += "; rollback issues: " + "; ".join(rollback_issues)
            return None, err

        sleep(_POLL_INTERVAL_SECS)

    steps.append(_step("poll_db_state", "ok", "state=running"))

    if adapter_jar_override:
        adapter_jar_path = adapter_jar_override
    else:
        adapter_jar_path = _DEFAULT_ADAPTER_JAR_DIR

    jar_issues = []
    resolved_jar_path = _ensure_adapter_jar(
        server, confd_host, adapter_jar_path, http, steps, jar_issues
    )

    if resolved_jar_path is None:
        err = "ERR:" + "; ".join(jar_issues) if jar_issues else "ERR:adapter jar not found"
        _rollback(server, vdb_name, created_db, created_volume, rollback_issues)
        if rollback_issues:
            err += "; rollback issues: " + "; ".join(rollback_issues)
        return None, err

    report = {
        "steps": steps,
        "vdb_name": vdb_name,
        "port": port,
        "adapter_jar_path": resolved_jar_path,
        "connect": "{}:{}".format(confd_host, port),
    }
    return report, None


# ---------------------------------------------------------------------------
# action = 'stop'
# ---------------------------------------------------------------------------

def _run_stop(params, server):
    """Orchestrate STOP VIRTUAL RESTORE. Returns (report_dict, err_string).

    On success: (report_dict, None). Step failures DO produce ERR:.
    """
    vdb_name = params["vdb_name"]
    data_volume_name = vdb_name + "_DATA"
    steps = []
    errors = []

    def _already_gone(exc):
        msg = str(exc).lower()
        return (
            "not running" in msg
            or "not found" in msg
            or "does not exist" in msg
            or "unknown database" in msg
        )

    try:
        _confd_call(server, "db_stop", {"db_name": vdb_name})
        steps.append(_step("db_stop", "ok"))
    except Exception as exc:
        if _already_gone(exc):
            steps.append(_step("db_stop", "skipped", _redact(exc)))
        else:
            steps.append(_step("db_stop", "failed", _redact(exc)))
            errors.append("db_stop: " + _redact(exc))

    try:
        _confd_call(server, "db_delete", {"db_name": vdb_name})
        steps.append(_step("db_delete", "ok"))
    except Exception as exc:
        if _already_gone(exc):
            steps.append(_step("db_delete", "skipped", _redact(exc)))
        else:
            steps.append(_step("db_delete", "failed", _redact(exc)))
            errors.append("db_delete: " + _redact(exc))

    volume_issues = []
    deleted = _delete_data_volumes(server, data_volume_name, volume_issues)
    if volume_issues:
        steps.append(_step("st_volume_delete", "failed", "; ".join(volume_issues)))
        errors.append("st_volume_delete: " + "; ".join(volume_issues))
    elif deleted:
        steps.append(_step(
            "st_volume_delete", "ok",
            "deleted {} volume(s) named {}".format(deleted, data_volume_name),
        ))
    else:
        steps.append(_step("st_volume_delete", "skipped", "no volume named " + data_volume_name))

    if errors:
        report = {"steps": steps, "vdb_name": vdb_name}
        return report, "ERR:stop failed: " + "; ".join(errors)

    report = {"steps": steps, "vdb_name": vdb_name}
    return report, None


# ---------------------------------------------------------------------------
# Public entry points
# ---------------------------------------------------------------------------

def _execute(
    connection,
    action,
    params_json,
    issuing_db_name="",
    proxy_factory=None,
    http=None,
    sleep=None,
    monotonic=None,
):
    """Pure, dependency-injected core. Tests drive this directly with fake
    connection objects, proxy factories, HTTP callables, and clocks.

    connection  — object with .address, .user, .password attributes
    action      — 'start' or 'stop'
    params_json — JSON string of virtual-restore parameters
    issuing_db_name — name of the SQL session's database (filled by run())
    proxy_factory   — callable(url) -> XML-RPC proxy; default uses live SSL
    http            — callable(method, url, auth=None, data=None) -> (status, bytes)
    sleep           — callable(seconds); default time.sleep
    monotonic       — callable() -> float seconds; default time.monotonic
    """
    params = json.loads(params_json) if params_json and params_json.strip() else {}
    if not isinstance(params, dict):
        raise ValueError("params_json must be a JSON object")

    if proxy_factory is None:
        proxy_factory = _default_proxy_factory
    if http is None:
        http = _default_http
    if sleep is None:
        sleep = _time_module.sleep
    if monotonic is None:
        monotonic = _time_module.monotonic

    endpoint = _build_endpoint(connection.address, connection.user, connection.password)
    server = proxy_factory(endpoint)
    confd_host = _host_from_address(connection.address)

    vdb_name = params.get("vdb_name", "VR1")
    if not _identifier_ok(vdb_name):
        return "ERR:invalid vdb_name '{}': must match ^[A-Za-z][A-Za-z0-9_]*$".format(vdb_name)

    if action == "start":
        report, err = _run_start(params, server, issuing_db_name, confd_host, http, sleep, monotonic)
        if err:
            return err
        return json.dumps(report, default=str)

    if action == "stop":
        report, err = _run_stop(params, server)
        if err:
            return err
        return json.dumps(report, default=str)

    return "ERR:unknown action '{}'".format(action)


def run(ctx):
    try:
        connection = exa.get_connection(ctx.connection_name)  # noqa: F821
        return _execute(
            connection,
            ctx.vr_action,
            ctx.params_json,
            issuing_db_name=exa.meta.database_name,  # noqa: F821
        )
    except Exception as e:
        return "ERR:" + str(e)
/

--/
CREATE OR REPLACE PYTHON3 SCALAR SCRIPT PREPROC_RT.BUCKETFS_FILE_V1(connection_name VARCHAR(128), bf_action VARCHAR(32), params_json VARCHAR(2000000)) RETURNS VARCHAR(2000000) AS
# =============================================================================
# BUCKETFS_FILE_V1  (PREPROC_RT.BUCKETFS_FILE_V1)  — Python3 SCALAR UDF body
# =============================================================================
# Orchestrator UDF for the CONTROL BUCKETFS file-access command family
# (UPLOAD / DELETE / LIST / SHOW). Given a ConfD CONNECTION object name, an
# action ('upload', 'delete', 'list', or 'show'), and a JSON parameter object,
# it discovers the BucketFS service endpoint + bucket credentials via ConfD
# XML-RPC (bucketfs_info) and then drives the file operation over the BucketFS
# service's own HTTP(S) interface (GET / PUT / DELETE).
#
# This file is BOTH:
#   * a normal importable Python module (so the logic is unit-testable without
#     a database — see tests/test_bucketfs_file.py), and
#   * the verbatim body embedded into the CREATE PYTHON3 SCALAR SCRIPT by
#     build.py. The `exa` runtime object is only referenced inside run(), so
#     the module imports cleanly outside Exasol; the testable logic lives in
#     the dependency-injected helper _execute().
#
# UDF signature (declared in the CREATE script header by build.py):
#   PREPROC_RT.BUCKETFS_FILE_V1(connection_name VARCHAR(128),
#                               bf_action       VARCHAR(32),
#                               params_json     VARCHAR(2000000))
#   RETURNS VARCHAR(2000000)
#   The parameter is bf_action, not action — ACTION is a reserved keyword in
#   Exasol and cannot be used as an identifier.
#
# Return contract — the ERR: sentinel
#   run() NEVER raises. On success it returns a JSON step-report document. On
#   ANY failure it returns 'ERR:<message>'. The calling Lua admin script
#   (PREPROC.ADMIN_BUCKETFS_FILE) checks for the ERR: prefix and re-raises it
#   as a loud script error, ensuring failures are never silently swallowed.
#
# Credentials / endpoint
#   ConfD credentials + address are read from the named CONNECTION object via
#   exa.get_connection(). BucketFS endpoint (host:port, http vs https) and the
#   per-bucket read/write passwords are discovered from one bucketfs_info call;
#   there is no separate bucket_info ConfD job.
#
# TLS
#   ConfD ships a self-signed certificate; an unverified SSL context is used.
#   BucketFS HTTPS likewise uses an unverified context (matches the existing
#   treatment of ConfD's self-signed cert).
#
# Secrets
#   _redact strips both basic-auth credentials AND URL query strings from any
#   text embedded in ERR: messages, so presigned-URL signatures never leak.
#
# Self-contained
#   build.py embeds this file verbatim as a UDF body, so it MUST NOT import
#   anything outside the Python stdlib and MUST NOT produce side effects at
#   import time. The vetted helpers below are duplicated from
#   virtual_restore_v1.py because importing across UDF bodies is impossible.
# =============================================================================
import base64
import json
import re
import ssl
import xmlrpc.client
from urllib.parse import quote as _urlquote
from urllib.request import Request as _Request, urlopen as _urlopen


# ---------------------------------------------------------------------------
# Module constants
# ---------------------------------------------------------------------------

_SHOW_MAX_BYTES = 1_000_000  # 1 MB — fits inside VARCHAR(2000000)


# ---------------------------------------------------------------------------
# Internal helpers (duplicated from virtual_restore_v1.py — file must stay
# self-contained; UDF bodies cannot import across each other)
# ---------------------------------------------------------------------------

def _build_endpoint(address, user, password):
    """Build the XML-RPC URL 'scheme://user:password@host:port' from a
    CONNECTION's address plus credentials.

    The address may or may not carry a scheme and may already embed credentials
    (which are stripped and replaced). ConfD speaks HTTPS; a bare host:port
    is assumed to be https.
    """
    addr = address or ""
    if "://" in addr:
        scheme, rest = addr.split("://", 1)
    else:
        scheme, rest = "https", addr
    if "@" in rest:
        rest = rest.split("@", 1)[1]
    return "{}://{}:{}@{}".format(
        scheme,
        _urlquote(user or "", safe=""),
        _urlquote(password or "", safe=""),
        rest,
    )


def _host_from_address(address):
    """Extract the bare hostname (no scheme, no port, no credentials) from a
    CONNECTION address string. Used to construct BucketFS HTTP URLs.
    """
    addr = address or ""
    if "://" in addr:
        rest = addr.split("://", 1)[1]
    else:
        rest = addr
    if "@" in rest:
        rest = rest.split("@", 1)[1]
    host = rest.split(":")[0]
    return host


def _redact(text):
    """Remove secrets from URLs embedded in exception/error messages.

    Strips both basic-auth credentials (user:pass@) and URL query strings
    (?...). xmlrpc.client.ProtocolError renders the ConfD endpoint without a
    scheme (user:pass@host:port), so the credential pattern is matched with or
    without a leading scheme://; presigned source URLs carry their signature
    in the query string. Both are secrets that must never appear in ERR:
    strings.
    """
    s = re.sub(r'[^/@\s:]+:[^/@\s]+@', '<redacted>@', str(text))
    s = re.sub(r'\?[^\s"\']*', '?<redacted>', s)
    return s


# ---------------------------------------------------------------------------
# ConfD call helpers
# ---------------------------------------------------------------------------

def _confd_call(server, job, params):
    """Call server.job_exec(job, {"params": params}) and return the result dict.

    Raises RuntimeError if result_code is non-zero.
    """
    result = server.job_exec(job, {"params": params})
    code = result.get("result_code", 0) if isinstance(result, dict) else 0
    if code != 0:
        desc = ""
        if isinstance(result, dict):
            desc = result.get("result_desc") or result.get("result_name") or ""
        raise RuntimeError(
            "ConfD job '{}' failed (code {}): {}".format(job, code, desc)
        )
    return result


def _default_proxy_factory(url):
    """Build a live XML-RPC ServerProxy with an unverified SSL context."""
    sslctx = ssl._create_unverified_context()
    return xmlrpc.client.ServerProxy(url, context=sslctx, allow_none=True)


# ---------------------------------------------------------------------------
# Default HTTP callable
# ---------------------------------------------------------------------------

def _default_http(method, url, auth=None, data=None):
    """Minimal HTTP client backed by urllib. Returns (status_code, body_bytes).

    auth: (user, password) tuple for HTTP Basic auth, or None.
    data: bytes body for PUT/POST, or None.
    Ignores SSL certificate errors (BucketFS may serve a self-signed cert).
    """
    req = _Request(url, data=data, method=method)
    if auth is not None:
        raw = "{}:{}".format(auth[0], auth[1]).encode("utf-8")
        req.add_header("Authorization", "Basic " + base64.b64encode(raw).decode())
    ctx = ssl._create_unverified_context()
    try:
        with _urlopen(req, context=ctx, timeout=60) as resp:
            return resp.status, resp.read()
    except Exception as exc:
        code = getattr(getattr(exc, "reason", None), "errno", None) or 0
        return (getattr(exc, "code", 0) or code or -1, str(exc).encode())


# ---------------------------------------------------------------------------
# Step report helpers
# ---------------------------------------------------------------------------

def _step(name, status, detail=""):
    """Build a single step-report entry dict."""
    return {"step": name, "status": status, "detail": detail}


# ---------------------------------------------------------------------------
# Endpoint + credential discovery
# ---------------------------------------------------------------------------

def _discover(server, confd_host, service, bucket):
    """Call bucketfs_info and return (base_url, write_password, read_password).

    write_password / read_password are None if not set. Raises RuntimeError on
    service/bucket not found or when both ports are zero.
    """
    fi = _confd_call(server, "bucketfs_info", {"bucketfs_name": service})
    fs_out = fi.get("result_output", {}) if isinstance(fi.get("result_output"), dict) else {}

    http_port = int(fs_out.get("http_port") or 0)
    https_port = int(fs_out.get("https_port") or 0)
    if http_port:
        base_url = "http://{}:{}".format(confd_host, http_port)
    elif https_port:
        base_url = "https://{}:{}".format(confd_host, https_port)
    else:
        raise RuntimeError(
            "service '{}': both http_port and https_port are zero".format(service)
        )

    buckets = fs_out.get("buckets") if isinstance(fs_out.get("buckets"), dict) else {}
    if bucket not in buckets:
        raise RuntimeError(
            "service '{}' bucket '{}' not found".format(service, bucket)
        )
    binfo = buckets.get(bucket) if isinstance(buckets.get(bucket), dict) else {}

    raw_w = binfo.get("write_passwd") or binfo.get("write_password") or ""
    raw_r = binfo.get("read_passwd") or binfo.get("read_password") or ""
    write_password = base64.b64decode(raw_w).decode("utf-8") if raw_w else None
    read_password = base64.b64decode(raw_r).decode("utf-8") if raw_r else None

    return base_url, write_password, read_password


# ---------------------------------------------------------------------------
# action = 'upload'
# ---------------------------------------------------------------------------

def _upload(server, confd_host, params, http):
    """Fetch bytes from a cluster-reachable source URL and PUT them into the
    bucket. Returns a list of step dicts on success or an 'ERR:...' string.
    """
    source_url = params.get("source_url", "")
    bucket = params.get("bucket", "")
    service = params.get("service", "")
    path = params.get("path", "")

    if re.search(r'://[^@]*:[^@]*@', source_url):
        return "ERR:source URL must not contain inline credentials"

    try:
        base_url, write_password, _ = _discover(server, confd_host, service, bucket)
    except Exception as exc:
        return "ERR:" + _redact(exc)

    if write_password is None:
        return "ERR:bucket '{}/{}': no write password available".format(service, bucket)

    status, body_bytes = http("GET", source_url)
    if status != 200:
        return "ERR:source URL returned HTTP {}".format(status)

    target_url = "{}/{}/{}".format(base_url, bucket, path)
    put_status, _ = http("PUT", target_url, auth=("w", write_password), data=body_bytes)
    if put_status not in (200, 201, 204):
        return "ERR:BucketFS PUT returned HTTP {}".format(put_status)

    return [_step(
        "upload",
        "ok",
        "uploaded {} bytes to {}/{}/{}".format(len(body_bytes), base_url, bucket, path),
    )]


# ---------------------------------------------------------------------------
# action = 'delete'
# ---------------------------------------------------------------------------

def _delete(server, confd_host, params, http):
    """Issue an authenticated DELETE against the bucket file. Returns a list of
    step dicts on success or an 'ERR:...' string.
    """
    bucket = params.get("bucket", "")
    service = params.get("service", "")
    path = params.get("path", "")

    try:
        base_url, write_password, _ = _discover(server, confd_host, service, bucket)
    except Exception as exc:
        return "ERR:" + _redact(exc)

    if write_password is None:
        return "ERR:bucket '{}/{}': no write password available".format(service, bucket)

    target_url = "{}/{}/{}".format(base_url, bucket, path)
    status, _ = http("DELETE", target_url, auth=("w", write_password))
    if status == 404:
        return "ERR:file not found: {}".format(path)
    if status not in (200, 201, 204):
        return "ERR:BucketFS DELETE returned HTTP {}".format(status)

    return [_step("delete", "ok", "deleted {}/{}/{}".format(base_url, bucket, path))]


# ---------------------------------------------------------------------------
# action = 'list'
# ---------------------------------------------------------------------------

def _list(server, confd_host, params, http):
    """GET the bucket root and split the newline-separated body into one step
    per file. Returns a list of step dicts (possibly empty) or an 'ERR:...'
    string.
    """
    bucket = params.get("bucket", "")
    service = params.get("service", "")

    try:
        base_url, _, read_password = _discover(server, confd_host, service, bucket)
    except Exception as exc:
        return "ERR:" + _redact(exc)

    read_auth = ("r", read_password) if read_password else None
    target_url = "{}/{}/".format(base_url, bucket)
    status, body_bytes = http("GET", target_url, auth=read_auth)
    if status != 200:
        return "ERR:BucketFS LIST returned HTTP {}".format(status)

    text = body_bytes.decode("utf-8", errors="replace")
    names = [line for line in text.splitlines() if line]
    return [_step("file", "ok", name) for name in names]


# ---------------------------------------------------------------------------
# action = 'show'
# ---------------------------------------------------------------------------

def _show(server, confd_host, params, http):
    """GET a bucket file, enforce the size cap, and return its content in a
    single step. Returns a list of step dicts on success or an 'ERR:...' string.
    """
    bucket = params.get("bucket", "")
    service = params.get("service", "")
    path = params.get("path", "")

    try:
        base_url, _, read_password = _discover(server, confd_host, service, bucket)
    except Exception as exc:
        return "ERR:" + _redact(exc)

    read_auth = ("r", read_password) if read_password else None
    target_url = "{}/{}/{}".format(base_url, bucket, path)
    status, body_bytes = http("GET", target_url, auth=read_auth)
    if status == 404:
        return "ERR:file not found: {}".format(path)
    if status != 200:
        return "ERR:BucketFS SHOW returned HTTP {}".format(status)

    if len(body_bytes) > _SHOW_MAX_BYTES:
        return "ERR:file '{}' exceeds size cap of {} bytes".format(path, _SHOW_MAX_BYTES)

    return [_step("show", "ok", body_bytes.decode("utf-8", errors="replace"))]


# ---------------------------------------------------------------------------
# Public entry points
# ---------------------------------------------------------------------------

def _execute(connection, bf_action, params_json, proxy_factory=None, http=None):
    """Pure, dependency-injected core. Tests drive this directly.

    connection    — object with .address, .user, .password attributes
    bf_action     — 'upload', 'delete', 'list', or 'show'
    params_json   — JSON string of action parameters
    proxy_factory — callable(url) -> XML-RPC proxy; default uses live SSL
    http          — callable(method, url, auth=None, data=None) -> (status, bytes)
    """
    params = json.loads(params_json) if params_json and params_json.strip() else {}
    if not isinstance(params, dict):
        return "ERR:params_json must be a JSON object"

    if proxy_factory is None:
        proxy_factory = _default_proxy_factory
    if http is None:
        http = _default_http

    endpoint = _build_endpoint(connection.address, connection.user, connection.password)
    server = proxy_factory(endpoint)
    confd_host = _host_from_address(connection.address)

    try:
        if bf_action == "upload":
            result = _upload(server, confd_host, params, http)
        elif bf_action == "delete":
            result = _delete(server, confd_host, params, http)
        elif bf_action == "list":
            result = _list(server, confd_host, params, http)
        elif bf_action == "show":
            result = _show(server, confd_host, params, http)
        else:
            return "ERR:unknown action '{}'".format(bf_action)
    except Exception as exc:
        return "ERR:" + _redact(exc)

    if isinstance(result, str):
        # Action returned an ERR: string
        return result

    return json.dumps({"steps": result}, default=str)


def run(ctx):
    try:
        connection = exa.get_connection(ctx.connection_name)  # noqa: F821
        return _execute(connection, ctx.bf_action, ctx.params_json)
    except Exception as e:
        return "ERR:" + str(e)
/

