CREATE OR REPLACE PYTHON3 SCALAR SCRIPT PREPROC_RT.LICENSE_INSTALL_V1(connection_name VARCHAR(128), lic_action VARCHAR(32), params_json VARCHAR(2000000)) RETURNS VARCHAR(2000000) AS
# =============================================================================
# LICENSE_INSTALL_V1  (PREPROC_RT.LICENSE_INSTALL_V1)  — Python3 SCALAR UDF body
# =============================================================================
# Orchestrator UDF for the CONTROL DATABASE INSTALL LICENSE command. Given a
# ConfD CONNECTION object name, an action ('install'), and a JSON parameter
# object carrying a `mode`, it resolves the raw license-file content from one of
# three input modes and then runs the `license_upload` ConfD job.
#
# Input modes (the JSON `mode` field):
#   url       — {"mode":"url","source_url":"<url>"}
#               HTTP(S) GET the license file from a cluster-reachable URL
#               server-side. Inline credentials (scheme://user:pass@host) are
#               rejected before any fetch.
#   content   — {"mode":"content","license":"<blob>"}
#               The inline blob IS the license content; no fetch is performed.
#   bucketfs  — {"mode":"bucketfs","path":"<p>","bucket":"<b>","service":"<s>"}
#               Discover the BucketFS endpoint + read credential via the
#               bucketfs_info ConfD job, then GET the file over the BucketFS
#               HTTP(S) interface authenticating as user 'r'. Mirrors
#               BUCKETFS_FILE_V1 SHOW.
#
# This file is BOTH:
#   * a normal importable Python module (so the logic is unit-testable without
#     a database — see tests/test_license_install.py), and
#   * the verbatim body embedded into the CREATE PYTHON3 SCALAR SCRIPT by
#     build.py. The `exa` runtime object is only referenced inside run(), so
#     the module imports cleanly outside Exasol; the testable logic lives in
#     the dependency-injected helper _execute().
#
# UDF signature (declared in the CREATE script header by build.py):
#   PREPROC_RT.LICENSE_INSTALL_V1(connection_name VARCHAR(128),
#                                 lic_action       VARCHAR(32),
#                                 params_json      VARCHAR(2000000))
#   RETURNS VARCHAR(2000000)
#   The parameter is lic_action, not action — ACTION is a reserved keyword in
#   Exasol and cannot be used as an identifier.
#
# Return contract — the ERR: sentinel
#   run() NEVER raises. On success it returns the installed license fields as a
#   JSON object (the parsed result_output of license_upload — same shape as
#   license_info: nested Contract / Limits / … objects). On ANY failure it
#   returns 'ERR:<message>'. The calling Lua admin script (PREPROC.ADMIN_LICENSE)
#   flattens the fields into FIELD/VALUE_TEXT rows, and re-raises the ERR: prefix
#   as a loud script error so failures are never silently swallowed.
#
# Atomic reject
#   ConfD verifies the license's S/MIME signature before replacing it, so an
#   unsigned or malformed license is rejected with a non-zero result_code and
#   the previously installed license remains in effect. _confd_call turns that
#   non-zero code into a RuntimeError, which _execute converts to an ERR:
#   sentinel — no fetch or upload leaves the cluster without a valid license.
#
# Credentials / endpoint
#   ConfD credentials + address are read from the named CONNECTION object via
#   exa.get_connection(). For bucketfs mode the BucketFS endpoint (host:port,
#   http vs https) and the per-bucket read password are discovered from one
#   bucketfs_info call.
#
# TLS
#   ConfD ships a self-signed certificate; an unverified SSL context is used.
#   BucketFS HTTPS likewise uses an unverified context.
#
# Secrets
#   _redact strips both basic-auth credentials AND URL query strings from any
#   text embedded in ERR: messages, so presigned-URL signatures never leak.
#
# Self-contained
#   build.py embeds this file verbatim as a UDF body, so it MUST NOT import
#   anything outside the Python stdlib and MUST NOT produce side effects at
#   import time. The vetted helpers below are duplicated from
#   bucketfs_file_v1.py because importing across UDF bodies is impossible.
# =============================================================================
import base64
import json
import re
import ssl
import xmlrpc.client
from urllib.parse import quote as _urlquote
from urllib.request import Request as _Request, urlopen as _urlopen


# ---------------------------------------------------------------------------
# Internal helpers (duplicated VERBATIM from bucketfs_file_v1.py — file must
# stay self-contained; UDF bodies cannot import across each other)
# ---------------------------------------------------------------------------

def _build_endpoint(address, user, password):
    """Build the XML-RPC URL 'scheme://user:password@host:port' from a
    CONNECTION's address plus credentials.

    The address may or may not carry a scheme and may already embed credentials
    (which are stripped and replaced). ConfD speaks HTTPS; a bare host:port
    is assumed to be https.
    """
    addr = address or ""
    if "://" in addr:
        scheme, rest = addr.split("://", 1)
    else:
        scheme, rest = "https", addr
    if "@" in rest:
        rest = rest.split("@", 1)[1]
    return "{}://{}:{}@{}".format(
        scheme,
        _urlquote(user or "", safe=""),
        _urlquote(password or "", safe=""),
        rest,
    )


def _host_from_address(address):
    """Extract the bare hostname (no scheme, no port, no credentials) from a
    CONNECTION address string. Used to construct BucketFS HTTP URLs.
    """
    addr = address or ""
    if "://" in addr:
        rest = addr.split("://", 1)[1]
    else:
        rest = addr
    if "@" in rest:
        rest = rest.split("@", 1)[1]
    host = rest.split(":")[0]
    return host


def _redact(text):
    """Remove secrets from URLs embedded in exception/error messages.

    Strips both basic-auth credentials (user:pass@) and URL query strings
    (?...). xmlrpc.client.ProtocolError renders the ConfD endpoint without a
    scheme (user:pass@host:port), so the credential pattern is matched with or
    without a leading scheme://; presigned source URLs carry their signature
    in the query string. Both are secrets that must never appear in ERR:
    strings.
    """
    s = re.sub(r'[^/@\s:]+:[^/@\s]+@', '<redacted>@', str(text))
    s = re.sub(r'\?[^\s"\']*', '?<redacted>', s)
    return s


# ---------------------------------------------------------------------------
# ConfD call helpers
# ---------------------------------------------------------------------------

def _confd_call(server, job, params):
    """Call server.job_exec(job, {"params": params}) and return the result dict.

    Raises RuntimeError if result_code is non-zero.
    """
    result = server.job_exec(job, {"params": params})
    code = result.get("result_code", 0) if isinstance(result, dict) else 0
    if code != 0:
        desc = ""
        if isinstance(result, dict):
            desc = result.get("result_desc") or result.get("result_name") or ""
        raise RuntimeError(
            "ConfD job '{}' failed (code {}): {}".format(job, code, desc)
        )
    return result


def _default_proxy_factory(url):
    """Build a live XML-RPC ServerProxy with an unverified SSL context."""
    sslctx = ssl._create_unverified_context()
    return xmlrpc.client.ServerProxy(url, context=sslctx, allow_none=True)


# ---------------------------------------------------------------------------
# Default HTTP callable
# ---------------------------------------------------------------------------

def _default_http(method, url, auth=None, data=None):
    """Minimal HTTP client backed by urllib. Returns (status_code, body_bytes).

    auth: (user, password) tuple for HTTP Basic auth, or None.
    data: bytes body for PUT/POST, or None.
    Ignores SSL certificate errors (BucketFS may serve a self-signed cert).
    """
    req = _Request(url, data=data, method=method)
    if auth is not None:
        raw = "{}:{}".format(auth[0], auth[1]).encode("utf-8")
        req.add_header("Authorization", "Basic " + base64.b64encode(raw).decode())
    ctx = ssl._create_unverified_context()
    try:
        with _urlopen(req, context=ctx, timeout=60) as resp:
            return resp.status, resp.read()
    except Exception as exc:
        code = getattr(getattr(exc, "reason", None), "errno", None) or 0
        return (getattr(exc, "code", 0) or code or -1, str(exc).encode())


# ---------------------------------------------------------------------------
# Endpoint + credential discovery (duplicated VERBATIM from bucketfs_file_v1.py)
# ---------------------------------------------------------------------------

def _discover(server, confd_host, service, bucket):
    """Call bucketfs_info and return (base_url, write_password, read_password).

    write_password / read_password are None if not set. Raises RuntimeError on
    service/bucket not found or when both ports are zero.
    """
    fi = _confd_call(server, "bucketfs_info", {"bucketfs_name": service})
    fs_out = fi.get("result_output", {}) if isinstance(fi.get("result_output"), dict) else {}

    http_port = int(fs_out.get("http_port") or 0)
    https_port = int(fs_out.get("https_port") or 0)
    if http_port:
        base_url = "http://{}:{}".format(confd_host, http_port)
    elif https_port:
        base_url = "https://{}:{}".format(confd_host, https_port)
    else:
        raise RuntimeError(
            "service '{}': both http_port and https_port are zero".format(service)
        )

    buckets = fs_out.get("buckets") if isinstance(fs_out.get("buckets"), dict) else {}
    if bucket not in buckets:
        raise RuntimeError(
            "service '{}' bucket '{}' not found".format(service, bucket)
        )
    binfo = buckets.get(bucket) if isinstance(buckets.get(bucket), dict) else {}

    raw_w = binfo.get("write_passwd") or binfo.get("write_password") or ""
    raw_r = binfo.get("read_passwd") or binfo.get("read_password") or ""
    write_password = base64.b64decode(raw_w).decode("utf-8") if raw_w else None
    read_password = base64.b64decode(raw_r).decode("utf-8") if raw_r else None

    return base_url, write_password, read_password


# ---------------------------------------------------------------------------
# License-content resolution (the three input modes)
# ---------------------------------------------------------------------------

def _resolve_license_content(mode, server, confd_host, params, http):
    """Resolve the raw license-file content for the given mode.

    Returns (content_str, None) on success or (None, "ERR:...") on failure.
    NO fetch happens for a rejected URL (inline credentials) or an unknown mode
    — validation precedes any HTTP or ConfD call. The returned value is always a
    str: license_upload consumes the license as a string (matching the string
    that license_download emits), so fetched bytes are decoded before use.
    """
    if mode == "content":
        return params.get("license", ""), None

    if mode == "url":
        source_url = params.get("source_url", "")
        if re.search(r'://[^@]*:[^@]*@', source_url):
            return None, "ERR:source URL must not contain inline credentials"
        status, body_bytes = http("GET", source_url)
        if status != 200:
            return None, "ERR:source URL returned HTTP {}".format(status)
        return body_bytes.decode("utf-8", errors="replace"), None

    if mode == "bucketfs":
        bucket = params.get("bucket", "")
        service = params.get("service", "")
        path = params.get("path", "")
        try:
            base_url, _, read_password = _discover(server, confd_host, service, bucket)
        except Exception as exc:
            return None, "ERR:" + _redact(exc)
        read_auth = ("r", read_password) if read_password else None
        target_url = "{}/{}/{}".format(base_url, bucket, path)
        status, body_bytes = http("GET", target_url, auth=read_auth)
        if status == 404:
            return None, "ERR:file not found: {}".format(path)
        if status != 200:
            return None, "ERR:BucketFS GET returned HTTP {}".format(status)
        return body_bytes.decode("utf-8", errors="replace"), None

    return None, "ERR:unknown or missing install mode '{}'".format(mode)


# ---------------------------------------------------------------------------
# action = 'install'
# ---------------------------------------------------------------------------

def _install(server, confd_host, params, http):
    """Resolve the license content per mode, then run license_upload.

    Returns the installed-license fields dict on success or an 'ERR:...' string.
    Raising is left to _confd_call (non-zero result_code = atomic reject); the
    caller's try/except converts it to a redacted ERR: sentinel.
    """
    mode = params.get("mode", "")
    content, err = _resolve_license_content(mode, server, confd_host, params, http)
    if err:
        return err

    result = _confd_call(server, "license_upload", {"license": content})

    fields = result.get("result_output") if isinstance(result, dict) else None
    if not isinstance(fields, dict):
        fields = {"status": "installed"}
    return fields


# ---------------------------------------------------------------------------
# Public entry points
# ---------------------------------------------------------------------------

def _execute(connection, action, params_json, proxy_factory=None, http=None):
    """Pure, dependency-injected core. Tests drive this directly.

    connection    — object with .address, .user, .password attributes
    action        — 'install'
    params_json   — JSON string carrying `mode` plus mode-specific keys
    proxy_factory — callable(url) -> XML-RPC proxy; default uses live SSL
    http          — callable(method, url, auth=None, data=None) -> (status, bytes)
    """
    params = json.loads(params_json) if params_json and params_json.strip() else {}
    if not isinstance(params, dict):
        return "ERR:params_json must be a JSON object"

    if proxy_factory is None:
        proxy_factory = _default_proxy_factory
    if http is None:
        http = _default_http

    endpoint = _build_endpoint(connection.address, connection.user, connection.password)
    server = proxy_factory(endpoint)
    confd_host = _host_from_address(connection.address)

    try:
        if action == "install":
            result = _install(server, confd_host, params, http)
        else:
            return "ERR:unknown action '{}'".format(action)
    except Exception as exc:
        return "ERR:" + _redact(exc)

    if isinstance(result, str):
        # _install returned an ERR: string
        return result

    return json.dumps(result, default=str)


def run(ctx):
    try:
        connection = exa.get_connection(ctx.connection_name)  # noqa: F821
        return _execute(connection, ctx.lic_action, ctx.params_json)
    except Exception as e:
        return "ERR:" + str(e)
/

