CREATE OR REPLACE PYTHON3 SCALAR SCRIPT PREPROC_RT.REMOTE_VOLUME_V1(connection_name VARCHAR(128), rv_action VARCHAR(32), params_json VARCHAR(2000000)) RETURNS VARCHAR(2000000) AS
# =============================================================================
# REMOTE_VOLUME_V1  (PREPROC_RT.REMOTE_VOLUME_V1)  — Python3 SCALAR UDF body
# =============================================================================
# Orchestrator UDF for the one secret-bearing verb of the CONTROL DATABASE
# remote-volume command family that remains on this lane: ADD REMOTE VOLUME.
# Given the ConfD CONNECTION object name, the action ('add'), and a JSON
# parameter object, it drives the remote_volume_add ConfD job over XML-RPC.
#
# The credential-redacting detail read (SHOW REMOTE VOLUME '<name>') has moved
# to the dedicated inline-capable read UDF REMOTE_VOLUME_QUERY_V1 (see
# sql/remote_volume_query_v1.py) — it no longer routes through this
# orchestrator. The remaining secret-free reads and the drop route through the
# generic PREPROC.ADMIN_CONFD_JOB gateway instead (remote_volume_list_details,
# remote_volume_state, remote_volume_remove); only ADD needs this orchestrator
# because it handles credentials.
#
# This file is BOTH:
#   * a normal importable Python module (so the logic is unit-testable without
#     a database — see tests/test_remote_volume.py), and
#   * the verbatim body embedded into the CREATE PYTHON3 SCALAR SCRIPT by
#     build.py. The `exa` runtime object is only referenced inside run(), so
#     the module imports cleanly outside Exasol; the testable logic lives in
#     the dependency-injected helper _execute().
#
# UDF signature (declared in the CREATE script header by build.py):
#   PREPROC_RT.REMOTE_VOLUME_V1(connection_name VARCHAR(128),
#                               rv_action       VARCHAR(32),
#                               params_json     VARCHAR(2000000))
#   RETURNS VARCHAR(2000000)
#   The action parameter is rv_action, not action — ACTION is a reserved
#   keyword in Exasol and cannot be used as an identifier. rv_action is
#   currently always 'add'; the parameter is kept (rather than dropped) so the
#   UDF signature and _execute() dispatch shape stay stable if another
#   secret-bearing write action is added later.
#
# Return contract — the ERR: sentinel
#   run() NEVER raises. On success it returns a JSON document (a step report).
#   On ANY failure it returns 'ERR:<message>'. The calling Lua admin script
#   (PREPROC.ADMIN_REMOTE_VOLUME) checks for the ERR: prefix and re-raises it
#   as a loud script error, ensuring failures are never silently swallowed.
#
# Credentials — two connections, resolved server-side, never in SQL
#   * connection_name (the UDF's first SQL argument) names the ConfD CONNECTION
#     (CONFD_CONNECTION): .address/.user/.password build the XML-RPC endpoint.
#   * params_json.connection_name (optional) names the *credential* CONNECTION
#     (e.g. s3_creds): its .user is injected as the volume 'username' and its
#     .password as the volume 'password' of remote_volume_add. It is resolved
#     via the injected get_connection callable (exa.get_connection at runtime).
#     When params_json carries no connection_name, credentials are OMITTED
#     entirely from remote_volume_add.
#   The credential secret is never embedded in SQL and never stringified into
#   an ERR: message.
#
# Dependency injection
#   _execute() accepts optional proxy_factory and get_connection parameters.
#   Tests pass fake implementations (a fake XML-RPC proxy and a fake connection
#   resolver); run() wires in the live stdlib / `exa` objects. This keeps the
#   network and the database entirely outside the module, following the extra
#   DI hooks already used by virtual_restore_v1.py (http/sleep/monotonic) and
#   bucketfs_file_v1.py (http).
#
# TLS
#   ConfD ships a self-signed certificate; an unverified SSL context is used
#   (matches the existing treatment of ConfD's self-signed cert).
#
# Self-contained
#   build.py embeds this file verbatim as a UDF body, so it MUST NOT import
#   anything outside the Python stdlib and MUST NOT produce side effects at
#   import time. The vetted helpers below are duplicated VERBATIM from
#   virtual_restore_v1.py because importing across UDF bodies is impossible.
# =============================================================================
import json
import re
import ssl
import xmlrpc.client
from urllib.parse import quote as _urlquote


# ---------------------------------------------------------------------------
# Internal helpers (duplicated VERBATIM from virtual_restore_v1.py — file must
# stay self-contained; UDF bodies cannot import across each other)
# ---------------------------------------------------------------------------


def _build_endpoint(address, user, password):
    """Build the XML-RPC URL 'scheme://user:password@host:port' from a
    CONNECTION's address plus credentials.

    The address may or may not carry a scheme and may already embed credentials
    (which are stripped and replaced). ConfD speaks HTTPS; a bare host:port
    is assumed to be https.
    """
    addr = address or ""
    if "://" in addr:
        scheme, rest = addr.split("://", 1)
    else:
        scheme, rest = "https", addr
    if "@" in rest:
        rest = rest.split("@", 1)[1]
    return "{}://{}:{}@{}".format(
        scheme,
        _urlquote(user or "", safe=""),
        _urlquote(password or "", safe=""),
        rest,
    )


def _scrub_secret(text, secret):
    """Replace every occurrence of a resolved secret value with '<redacted>'.

    Belt-and-suspenders for _redact(): a ConfD failure result_desc can echo a
    raw credential in a form _redact's URL-shaped patterns don't recognise
    (e.g. 'invalid secret key <value>'), so the exact resolved value is
    scrubbed directly. Never scrubs an empty/falsy secret — that would strip
    nothing and risks matching unrelated text.
    """
    if not secret:
        return text
    return str(text).replace(secret, "<redacted>")


def _redact(text):
    """Remove secrets from URLs embedded in exception/error messages.

    Strips both basic-auth credentials (user:pass@) and URL query strings
    (?...). xmlrpc.client.ProtocolError renders the ConfD endpoint without a
    scheme (user:pass@host:port), so the credential pattern is matched with or
    without a leading scheme://; presigned source URLs carry their signature
    in the query string. Both are secrets that must never appear in ERR:
    strings.
    """
    s = re.sub(r"[^/@\s:]+:[^/@\s]+@", "<redacted>@", str(text))
    s = re.sub(r'\?[^\s"\']*', "?<redacted>", s)
    return s


# ---------------------------------------------------------------------------
# ConfD call helpers
# ---------------------------------------------------------------------------


def _confd_call(server, job, params):
    """Call server.job_exec(job, {"params": params}) and return the result dict.

    Raises RuntimeError if result_code is non-zero.
    """
    result = server.job_exec(job, {"params": params})
    code = result.get("result_code", 0) if isinstance(result, dict) else 0
    if code != 0:
        desc = ""
        if isinstance(result, dict):
            desc = result.get("result_desc") or result.get("result_name") or ""
        raise RuntimeError(
            "ConfD job '{}' failed (code {}): {}".format(job, code, desc)
        )
    return result


def _default_proxy_factory(url):
    """Build a live XML-RPC ServerProxy with an unverified SSL context."""
    sslctx = ssl._create_unverified_context()
    return xmlrpc.client.ServerProxy(url, context=sslctx, allow_none=True)


# ---------------------------------------------------------------------------
# Step report helpers
# ---------------------------------------------------------------------------


def _step(name, status, detail=""):
    """Build a single step-report entry dict."""
    return {"step": name, "status": status, "detail": detail}


# ---------------------------------------------------------------------------
# action = 'add'
# ---------------------------------------------------------------------------


def _add(server, params, get_connection):
    """Register a remote volume via remote_volume_add.

    Non-secret attributes (vol_type, url, remote_volume_name, owner, options,
    labels, id) are passed through inline. When params carry a connection_name,
    that credential CONNECTION is resolved and its .user/.password are injected
    as the volume username/password; otherwise credentials are omitted entirely.

    Returns a step-report dict on success or an 'ERR:...' string on a
    validation failure. Raises on a ConfD-level failure (caught by _execute).
    """
    vol_type = params.get("vol_type")
    url = params.get("url")
    if not vol_type:
        return "ERR:add requires 'vol_type'"
    if not url:
        return "ERR:add requires 'url'"

    add_params = {"vol_type": vol_type, "url": url}

    name = params.get("remote_volume_name")
    if name is not None:
        add_params["remote_volume_name"] = name
    owner = params.get("owner")
    if owner is not None:
        add_params["owner"] = owner
    options = params.get("options")
    if options is not None:
        add_params["options"] = options
    labels = params.get("labels")
    if labels is not None:
        add_params["labels"] = labels
    volume_id = params.get("remote_volume_id")
    if volume_id is not None:
        add_params["remote_volume_id"] = volume_id

    connection_name = params.get("connection_name")
    resolved_username = None
    resolved_password = None
    if connection_name:
        if get_connection is None:
            return "ERR:credential connection '{}' requested but no connection resolver is available".format(
                connection_name
            )
        credential = get_connection(connection_name)
        resolved_username = getattr(credential, "user", None)
        resolved_password = getattr(credential, "password", None)
        add_params["username"] = resolved_username
        add_params["password"] = resolved_password

    try:
        _confd_call(server, "remote_volume_add", add_params)
    except Exception as exc:
        # Belt-and-suspenders: scrub the just-resolved secret value(s) directly,
        # in addition to the generic _redact() applied by _execute, in case
        # ConfD's result_desc echoes the raw credential in a form _redact's
        # URL-shaped patterns don't catch.
        message = _scrub_secret(str(exc), resolved_password)
        message = _scrub_secret(message, resolved_username)
        raise RuntimeError(message) from exc

    display_name = name if name else "(auto-generated)"
    return {
        "steps": [
            _step(
                "remote_volume_add",
                "ok",
                "created remote volume {} (type {})".format(display_name, vol_type),
            )
        ]
    }


# ---------------------------------------------------------------------------
# Public entry points
# ---------------------------------------------------------------------------


def _execute(connection, action, params_json, proxy_factory=None, get_connection=None):
    """Pure, dependency-injected core. Tests drive this directly with a fake
    connection object, a fake XML-RPC proxy factory, and a fake connection
    resolver.

    connection    — ConfD CONNECTION object (.address/.user/.password); builds
                    the XML-RPC endpoint
    action        — 'add' (the only action this UDF still serves; the detail
                    read moved to REMOTE_VOLUME_QUERY_V1)
    params_json   — JSON string of action parameters:
                      add : {"remote_volume_name", "vol_type", "url",
                             "connection_name"?, "owner"?, "options"?,
                             "id"?, "labels"?}
    proxy_factory — callable(url) -> XML-RPC proxy; default uses live SSL
    get_connection — callable(name) -> credential CONNECTION object with
                    .user/.password; default None (run() passes exa.get_connection)
    """
    params = json.loads(params_json) if params_json and params_json.strip() else {}
    if not isinstance(params, dict):
        return "ERR:params_json must be a JSON object"

    if proxy_factory is None:
        proxy_factory = _default_proxy_factory

    endpoint = _build_endpoint(connection.address, connection.user, connection.password)
    server = proxy_factory(endpoint)

    try:
        if action == "add":
            result = _add(server, params, get_connection)
        else:
            return "ERR:unknown action '{}'".format(action)
    except Exception as exc:
        return "ERR:" + _redact(exc)

    if isinstance(result, str):
        # Action returned an ERR: string (validation failure).
        return result

    return json.dumps(result, default=str)


def run(ctx):
    try:
        connection = exa.get_connection(ctx.connection_name)  # noqa: F821
        return _execute(
            connection,
            ctx.rv_action,
            ctx.params_json,
            get_connection=exa.get_connection,  # noqa: F821
        )
    except Exception as e:
        return "ERR:" + str(e)
