CREATE OR REPLACE PYTHON3 SCALAR SCRIPT PREPROC_RT.SESSION_LOG_V1(connection_name VARCHAR(128), params_json VARCHAR(2000000), session_id VARCHAR(64), collected_at TIMESTAMP) EMITS (session_id DECIMAL(20,0), node INT, line_no INT, log_text VARCHAR(2000000), collected_at TIMESTAMP) AS
# =============================================================================
# SESSION_LOG_V1  (PREPROC_RT.SESSION_LOG_V1)  — Python3 SCALAR EMITS UDF body
# =============================================================================
# Inline-capable orchestrator UDF for CONTROL DATABASE SHOW SESSION LOG. Given a
# ConfD CONNECTION object name, a JSON parameter object, a numeric session id and
# a single caller-evaluated timestamp, it EMITS the session's SQL log directly as
# five self-describing columns and RAISES on any failure (no admin layer, no
# ERR: sentinel). It:
#   1. validates the session id is a plain numeric string (injection guard),
#      BEFORE creating any bucket, running debug_collect, or touching BucketFS;
#   2. discovers the target bucket via one bucketfs_info call and REFUSES a
#      public bucket BEFORE writing anything (a session-scoped debug_collect
#      still yields the full ~683-member secret-bearing support archive);
#   3. runs the ConfD debug_collect job with its outfile directed into the
#      bucket's served upload folder;
#   4. fetches the resulting archive over the BucketFS HTTP interface, opens it
#      in memory, and extracts the '*_SqlSession_<id>.<N>' members for the
#      requested logical node(s), selecting each by its '.N' suffix (the
#      authoritative logical node number) rather than by hostname sort order;
#   5. GUARANTEES deletion of the temporary archive AND (default path) the
#      ephemeral bucket in finally blocks even on error — since failures RAISE,
#      the finally blocks run and then the exception propagates;
#   6. emits one row per log line per node, ordered by node then line.
#
# This file is BOTH a normal importable Python module (so the logic is
# unit-testable without a database — see tests/test_session_log.py) and the
# verbatim body embedded into the CREATE PYTHON3 SCALAR SCRIPT by build.py. The
# `exa` runtime object and ctx.emit are only referenced inside run(), so the
# module imports cleanly outside Exasol; the testable logic lives in the
# dependency-injected helper _execute().
#
# UDF signature (declared in the CREATE script header by build.py):
#   PREPROC_RT.SESSION_LOG_V1(connection_name VARCHAR(128),
#                             params_json     VARCHAR(2000000),
#                             session_id      VARCHAR(64),
#                             collected_at    TIMESTAMP)
#   EMITS (SESSION_ID DECIMAL(20,0), NODE INT, LINE_NO INT,
#          LOG_TEXT VARCHAR(2000000), COLLECTED_AT TIMESTAMP)
#
# The session id and timestamp are caller-evaluated SQL ARGUMENTS, not JSON keys:
# a UDF on a worker node cannot see the caller's CURRENT_SESSION or clock, so the
# preprocessor emits them as SQL expressions (a numeric literal or
# TO_CHAR(CURRENT_SESSION), and CURRENT_TIMESTAMP). Every emitted row carries the
# SAME collected_at value (verbatim, never synthesised per node/row), and the
# session id is emitted as a Python int so digits above 2^53 survive the DECIMAL.
#
# Input JSON contract (params_json)
#   {
#     "bucket":     "<name>",     OPTIONAL. When ABSENT the UDF creates and
#                                 deletes its own ephemeral PRIVATE bucket. When
#                                 present, targets that caller-owned pre-existing
#                                 bucket (never created/deleted; refused if public).
#     "service":    "<name>",     OPTIONAL. BucketFS service. Default 'bfsdefault'.
#     "db_name":    "<name>",     OPTIONAL. db_name-inference fallback used only
#                                 when ConfD db_list yields nothing. run() injects
#                                 exa.meta.database_name here.
#     "nodes":      ["<n>", ...], OPTIONAL. Logical node numbers (numeric strings)
#                                 to retrieve. Absent → default logical node 0.
#                                 Each N is mapped to the hostname active[N] from
#                                 ConfD db_info and passed to debug_collect.
#     "all_nodes":  true          OPTIONAL. Retrieve every node the session ran
#                                 on; the debug_collect 'nodes' param is omitted
#                                 and all member suffixes are extracted. Mutually
#                                 exclusive with "nodes"; takes precedence.
#   }
#   The params JSON NO LONGER carries a session id (the retired 'session' /
#   'session_id' keys): the id is a dedicated SQL argument. The retired
#   'active_sessions' / 'caller_session' keys are gone too — the orphan sweep is
#   age-based now (see below) and needs neither.
#
# Failure contract — RAISE, never a sentinel
#   run() RAISES on any failure so the error surfaces as a visible SQL error and
#   aborts the surrounding statement (no ERR: sentinel, no Lua admin layer to
#   translate one). Messages are redacted (_redact) so credentials and presigned
#   URLs never leak. Validation failures raise ValueError; operational failures
#   raise RuntimeError.
#
# Security posture
#   The archive is secret-bearing (a session-scoped debug_collect still yields
#   the full ~683-member support bundle). By default the UDF creates its OWN
#   ephemeral PRIVATE bucket with random credentials, so the archive is never
#   readable by anyone else, and deletes both the archive and the bucket in a
#   finally block even on error. When a caller-owned bucket is supplied instead,
#   the UDF refuses it if public (bucketfs_info `public` flag → loud raise before
#   any debug_collect or write) and refuses one with no write password (cleanup
#   could not be guaranteed). A unique session-id + nonce filename means
#   concurrent calls never collide, and ONLY the '*_SqlSession_<id>.<N>' members
#   for the requested logical node(s) are ever read (Exasol already censors the
#   login password in them) — never any other archive member.
#
# Orphan-bucket self-healing sweep — age-based
#   A hard query abort (SIGKILL) bypasses the finally-block cleanup, orphaning an
#   ephemeral bucket. Each ephemeral bucket is therefore named
#   '<prefix>_<stamp>_<session>_<uuid>' with the CREATING invocation's
#   caller-evaluated timestamp, and every invocation deletes any ephemeral bucket
#   more than _ORPHAN_MAX_AGE_SECONDS (30 min) older than its own timestamp.
#   Since a collection takes 15-45s, no live run's bucket can be that old, so
#   this invocation's own bucket and any concurrent run's are excluded by age
#   alone — no live-session enumeration, which a worker-node UDF cannot do. A
#   bucket without a parseable stamp is never swept (unknown age). The trade-off:
#   a collection that legitimately exceeds 30 min may have its bucket removed by
#   a concurrent invocation and fail; nothing else is affected. Ordinary
#   finally-block cleanup still runs on every non-killed invocation.
#
# TLS
#   ConfD ships a self-signed certificate; an unverified SSL context is used.
#   BucketFS HTTPS likewise uses an unverified context.
#
# Self-contained
#   build.py embeds this file verbatim as a UDF body, so it MUST NOT import
#   anything outside the Python stdlib and MUST NOT produce side effects at
#   import time. The vetted helpers below are duplicated from bucketfs_file_v1.py
#   because importing across UDF bodies is impossible.
#   It also MUST NOT bind the global name `datetime` to anything but the stdlib
#   module: the runtime marshals a TIMESTAMP column by resolving
#   `datetime.datetime` in this script's globals, so `from datetime import
#   datetime` breaks reading ctx.collected_at at runtime while every unit test
#   still passes (live-found 2026-07-27). Hence `import datetime as _dt`.
#   tests/test_deploy_bundle.py enforces this across all UDF bodies.
#
# Deployment assumption
#   The outfile base path is /exa/data/bucketfs/<service>/<bucket>/, the BucketFS
#   default. Flag this alongside the add-on's other environment assumptions.
# =============================================================================
import base64
# NEVER `from datetime import datetime` in a UDF body: reading a TIMESTAMP column
# (ctx.collected_at) makes the Exasol PYTHON3 runtime resolve `datetime.datetime`
# in THIS script's global namespace, so binding that name to the class breaks the
# conversion with "type object 'datetime.datetime' has no attribute 'datetime'"
# — a live-only failure no unit test sees. Import the module under an alias.
import datetime as _dt
import fnmatch
import json
import re
import ssl
import tarfile
import time
import uuid
import xmlrpc.client
from io import BytesIO
from urllib.parse import quote as _urlquote
from urllib.request import Request as _Request, urlopen as _urlopen


# ---------------------------------------------------------------------------
# Module constants
# ---------------------------------------------------------------------------

_DEFAULT_SERVICE = "bfsdefault"
_BUCKETFS_BASE_PATH = "/exa/data/bucketfs"
_DEBUG_COLLECT_TIMEOUT = 300
_EPHEMERAL_BUCKET_PREFIX = "confd_sesslog"
# An ephemeral bucket carries its creation time in its name (see _stamp_of). Any
# ephemeral bucket older than this is an orphan from a killed invocation and is
# reclaimed by the next run: a normal collection takes 15-45s, so 30 minutes is
# ~40x headroom. The threshold is the ONLY thing protecting an in-flight run's
# bucket, so it must stay far above the worst realistic collection time.
_ORPHAN_MAX_AGE_SECONDS = 30 * 60
_STAMP_FORMAT = "%Y%m%d%H%M%S"
_STAMP_DIGITS = 14
# A just-created bucket's HTTP endpoint returns 400 for ~1-2s until ready; retry
# the priming PUT across a few short intervals before giving up.
_PRIME_MAX_ATTEMPTS = 10
_PRIME_RETRY_SECONDS = 0.5


# ---------------------------------------------------------------------------
# Internal helpers (duplicated from bucketfs_file_v1.py — file must stay
# self-contained; UDF bodies cannot import across each other)
# ---------------------------------------------------------------------------


def _build_endpoint(address, user, password):
    """Build the XML-RPC URL 'scheme://user:password@host:port' from a
    CONNECTION's address plus credentials.

    The address may or may not carry a scheme and may already embed credentials
    (which are stripped and replaced). ConfD speaks HTTPS; a bare host:port
    is assumed to be https.
    """
    addr = address or ""
    if "://" in addr:
        scheme, rest = addr.split("://", 1)
    else:
        scheme, rest = "https", addr
    if "@" in rest:
        rest = rest.split("@", 1)[1]
    return "{}://{}:{}@{}".format(
        scheme, _urlquote(user or "", safe=""), _urlquote(password or "", safe=""), rest
    )


def _host_from_address(address):
    """Extract the bare hostname (no scheme, no port, no credentials) from a
    CONNECTION address string. Used to construct BucketFS HTTP URLs.
    """
    addr = address or ""
    if "://" in addr:
        rest = addr.split("://", 1)[1]
    else:
        rest = addr
    if "@" in rest:
        rest = rest.split("@", 1)[1]
    host = rest.split(":")[0]
    return host


def _redact(text):
    """Remove secrets from URLs embedded in exception/error messages.

    Strips both basic-auth credentials (user:pass@) and URL query strings
    (?...). xmlrpc.client.ProtocolError renders the ConfD endpoint without a
    scheme (user:pass@host:port), so the credential pattern is matched with or
    without a leading scheme://; presigned source URLs carry their signature
    in the query string. Both are secrets that must never appear in ERR:
    strings.
    """
    s = re.sub(r"[^/@\s:]+:[^/@\s]+@", "<redacted>@", str(text))
    s = re.sub(r'\?[^\s"\']*', "?<redacted>", s)
    return s


# ---------------------------------------------------------------------------
# ConfD call helpers
# ---------------------------------------------------------------------------


def _confd_call(server, job, params):
    """Call server.job_exec(job, {"params": params}) and return the result dict.

    Raises RuntimeError if result_code is non-zero.
    """
    result = server.job_exec(job, {"params": params})
    code = result.get("result_code", 0) if isinstance(result, dict) else 0
    if code != 0:
        desc = ""
        if isinstance(result, dict):
            desc = result.get("result_desc") or result.get("result_name") or ""
        raise RuntimeError(
            "ConfD job '{}' failed (code {}): {}".format(job, code, desc)
        )
    return result


def _default_proxy_factory(url):
    """Build a live XML-RPC ServerProxy with an unverified SSL context."""
    sslctx = ssl._create_unverified_context()
    return xmlrpc.client.ServerProxy(url, context=sslctx, allow_none=True)


# ---------------------------------------------------------------------------
# Default HTTP callable
# ---------------------------------------------------------------------------


def _default_http(method, url, auth=None, data=None):
    """Minimal HTTP client backed by urllib. Returns (status_code, body_bytes).

    auth: (user, password) tuple for HTTP Basic auth, or None.
    data: bytes body for PUT/POST, or None.
    Ignores SSL certificate errors (BucketFS may serve a self-signed cert).
    """
    req = _Request(url, data=data, method=method)
    if auth is not None:
        raw = "{}:{}".format(auth[0], auth[1]).encode("utf-8")
        req.add_header("Authorization", "Basic " + base64.b64encode(raw).decode())
    ctx = ssl._create_unverified_context()
    try:
        with _urlopen(req, context=ctx, timeout=60) as resp:
            return resp.status, resp.read()
    except Exception as exc:
        code = getattr(getattr(exc, "reason", None), "errno", None) or 0
        return (getattr(exc, "code", 0) or code or -1, str(exc).encode())


# ---------------------------------------------------------------------------
# Session id validation (injection guard)
# ---------------------------------------------------------------------------


def _is_numeric_session_id(session_id):
    """Return True only for a non-empty string of ASCII digits.

    Strict ASCII-only (re, not str.isdigit which accepts unicode digits): the id
    is substituted into the outfile path and the tar member glob, so a
    non-numeric id could inject path traversal or glob metacharacters.
    """
    return bool(session_id) and re.fullmatch(r"[0-9]+", session_id) is not None


# ---------------------------------------------------------------------------
# Database name resolution
# ---------------------------------------------------------------------------


def _db_names_from_output(out):
    """Normalise the varied ConfD db_list result_output shapes to a name list."""
    if isinstance(out, list):
        return [n for n in out if n]
    if isinstance(out, dict):
        for key in ("db_list", "databases", "dbs"):
            inner = out.get(key)
            if isinstance(inner, list):
                return [n for n in inner if n]
        return [k for k in out.keys() if k]
    return []


def _resolve_db_name(server, params):
    """Resolve the database name to fill exasolution_logs.

    Primary: the first element of ConfD db_list. Fallback: an explicit db_name in
    params (db_name inference — run() injects exa.meta.database_name). Returns
    None when neither yields a name.
    """
    try:
        dl = _confd_call(server, "db_list", {})
        names = _db_names_from_output(dl.get("result_output"))
        if names:
            return str(names[0])
    except Exception:
        pass
    fallback = params.get("db_name")
    if fallback:
        return str(fallback)
    return None


# ---------------------------------------------------------------------------
# Logical-node → hostname mapping (ConfD db_info)
# ---------------------------------------------------------------------------


def _active_nodes_from_output(out):
    """Normalise the varied ConfD db_info result_output shapes to an ordered
    active-node hostname list where index N is the hostname of logical node N.

    Tolerates result_output.nodes.active (the live shape), a bare
    result_output.nodes list, and a top-level result_output.active list, and
    returns [] for any other shape.

    Preserves every slot's INDEX POSITION: index N in the returned list is
    always logical node N, even when ConfD reports a falsy/None entry for
    some slot. A falsy entry is kept as "" rather than dropped, because
    dropping it would shift every later index onto the wrong hostname.
    """
    if not isinstance(out, dict):
        return []
    nodes = out.get("nodes")
    active = None
    if isinstance(nodes, dict):
        active = nodes.get("active")
    elif isinstance(nodes, list):
        active = nodes
    if active is None:
        active = out.get("active")
    if isinstance(active, list):
        return [str(n) if n else "" for n in active]
    return []


def _active_node_hostnames(server, db_name):
    """Return the ordered active-node hostname list from ConfD db_info.

    db_info is a database-scoped ConfD job: it requires the database name in its
    params (an empty/missing params is rejected with "db_info: 'params' is
    missing"). run() injects exa.meta.database_name into the UDF params, so the
    caller passes it through here.

    The list order reflects the live cluster's logical node ordering (and any
    failover), so active[N] is the physical hostname currently serving logical
    node N — the authoritative logical→hostname mapping for debug_collect.
    Raises RuntimeError when db_info reports no active node.
    """
    di = _confd_call(server, "db_info", {"db_name": db_name})
    hostnames = _active_nodes_from_output(di.get("result_output"))
    if not hostnames:
        raise RuntimeError("ConfD db_info reported no active nodes")
    return hostnames


def _resolve_nodes(server, params):
    """Resolve the node selection into (debug_nodes, wanted_suffixes).

    Reads 'all_nodes' / 'nodes' / neither (default logical node 0) from params:
      * all-nodes  -> (None, None): the debug_collect 'nodes' param is OMITTED
        and every member suffix is extracted;
      * specific   -> (hostname_list, {logical numbers}): each requested logical
        number N is mapped to active[N] and passed to debug_collect, and only
        those suffixes are extracted.
    Raises ValueError (BEFORE any debug_collect or bucket creation, so nothing is
    staged) on a malformed or out-of-range logical node number, or when ConfD
    reports no hostname for a requested logical node (a hole in db_info's
    active-node list).
    """
    if params.get("all_nodes"):
        return None, None

    raw = params.get("nodes")
    if raw is None:
        logical = [0]
    else:
        logical = []
        for entry in raw:
            token = str(entry).strip()
            if not re.fullmatch(r"[0-9]+", token):
                raise ValueError(
                    "invalid logical node number '{}': must be a non-negative "
                    "integer".format(entry)
                )
            logical.append(int(token))

    active = _active_node_hostnames(server, params.get("db_name"))
    debug_nodes = []
    for n in logical:
        if n >= len(active):
            raise ValueError(
                "logical node {} is out of range; the cluster has {} active "
                "node(s), numbered 0..{}".format(n, len(active), len(active) - 1)
            )
        hostname = active[n]
        if not hostname:
            raise ValueError(
                "logical node {} has no hostname reported by ConfD db_info".format(n)
            )
        debug_nodes.append(hostname)
    return debug_nodes, set(logical)


# ---------------------------------------------------------------------------
# Self-healing sweep of ephemeral buckets orphaned by a killed invocation
# ---------------------------------------------------------------------------


def _stamp_of(collected_at):
    """Render the caller's timestamp as the sortable '%Y%m%d%H%M%S' stamp that
    tags an ephemeral bucket, or None when no timestamp is available.

    Accepts whatever the TIMESTAMP SQL argument yields (a datetime under Exasol,
    a string elsewhere) by reading the leading 14 digits of its text form, so
    '2026-07-24 10:00:00.123' and datetime(2026, 7, 24, 10, 0) agree. Returns
    None for anything that is not a real timestamp -- callers then fall back to
    an unstamped name, which the sweep never touches (unknown age).
    """
    if collected_at is None:
        return None
    digits = re.sub(r"\D", "", str(collected_at))[:_STAMP_DIGITS]
    if len(digits) != _STAMP_DIGITS:
        return None
    try:
        _dt.datetime.strptime(digits, _STAMP_FORMAT)
    except ValueError:
        return None
    return digits


def _age_seconds(stamp, now_stamp):
    """Seconds between two '%Y%m%d%H%M%S' stamps, or None if either is unusable.

    Both stamps originate from a caller-evaluated CURRENT_TIMESTAMP, so the
    comparison is between two readings of the SAME clock -- worker-node clock
    skew can never enter it.
    """
    try:
        then = _dt.datetime.strptime(stamp, _STAMP_FORMAT)
        now = _dt.datetime.strptime(now_stamp, _STAMP_FORMAT)
    except (TypeError, ValueError):
        return None
    return (now - then).total_seconds()


def _sweep_orphan_buckets(server, service, now_stamp):
    """Best-effort removal of ephemeral buckets orphaned by a prior invocation
    that was killed mid-flight.

    A hard query abort (statement timeout, cancel, node crash) terminates the
    UDF process, which bypasses the finally-block that would delete the bucket
    -- nothing in Python can guarantee teardown on SIGKILL. Each invocation
    therefore sweeps leftovers from earlier dead runs.

    Ephemeral buckets are named '<prefix>_<stamp>_<session>_<uuid>', where
    <stamp> is the creating invocation's caller-evaluated timestamp. A bucket is
    an orphan iff that stamp is more than _ORPHAN_MAX_AGE_SECONDS older than
    THIS invocation's timestamp: a live run's bucket cannot be that old, because
    the command itself takes 15-45s, so both this invocation's own bucket (age
    ~0) and any concurrent run's (younger still) are excluded automatically --
    no live-session enumeration required, which a worker-node UDF cannot do.
    A name without a parseable 14-digit stamp has an unknown age and is NEVER
    swept.

    The age threshold is therefore the only protection for an in-flight run: a
    collection that legitimately ran longer than the threshold could have its
    bucket removed by a concurrent invocation, which fails that run with an HTTP
    error (its own finally-block delete then no-ops). Nothing else is affected.

    Returns the number of buckets swept. Never raises: sweeping is opportunistic
    and must not affect the command's own result.
    """
    if not now_stamp:
        return 0
    try:
        fi = _confd_call(server, "bucketfs_info", {"bucketfs_name": service})
    except Exception:
        return 0
    fs_out = (
        fi.get("result_output", {}) if isinstance(fi.get("result_output"), dict) else {}
    )
    buckets = fs_out.get("buckets") if isinstance(fs_out.get("buckets"), dict) else {}
    prefix = _EPHEMERAL_BUCKET_PREFIX + "_"
    swept = 0
    for name in list(buckets):
        if not name.startswith(prefix):
            continue
        stamp = name[len(prefix) :].split("_", 1)[0]
        if len(stamp) != _STAMP_DIGITS or not stamp.isdigit():
            continue  # unstamped/legacy name -> age unknown -> never sweep
        age = _age_seconds(stamp, now_stamp)
        if age is None or age <= _ORPHAN_MAX_AGE_SECONDS:
            continue
        try:
            _confd_call(
                server, "bucket_delete", {"bucket_name": name, "bucketfs_name": service}
            )
            swept += 1
        except Exception:
            pass
    return swept


# ---------------------------------------------------------------------------
# Endpoint + credential + visibility discovery
# ---------------------------------------------------------------------------


def _discover(server, confd_host, service, bucket):
    """Call bucketfs_info and return (base_url, write_password, read_password,
    is_public).

    write_password / read_password are None if unset. Raises RuntimeError with
    actionable guidance when the service/ports are unusable or the bucket does
    not exist.
    """
    fi = _confd_call(server, "bucketfs_info", {"bucketfs_name": service})
    fs_out = (
        fi.get("result_output", {}) if isinstance(fi.get("result_output"), dict) else {}
    )

    http_port = int(fs_out.get("http_port") or 0)
    https_port = int(fs_out.get("https_port") or 0)
    if http_port:
        base_url = "http://{}:{}".format(confd_host, http_port)
    elif https_port:
        base_url = "https://{}:{}".format(confd_host, https_port)
    else:
        raise RuntimeError(
            "service '{}': both http_port and https_port are zero".format(service)
        )

    buckets = fs_out.get("buckets") if isinstance(fs_out.get("buckets"), dict) else {}
    if bucket not in buckets:
        raise RuntimeError(
            "bucket '{}' not found in service '{}'; create a dedicated PRIVATE "
            "bucket for diagnostic archives before using SHOW SESSION LOG".format(
                bucket, service
            )
        )
    binfo = buckets.get(bucket) if isinstance(buckets.get(bucket), dict) else {}

    raw_public = binfo.get("public")
    if isinstance(raw_public, str):
        is_public = raw_public.strip().lower() in ("1", "true", "yes")
    else:
        is_public = bool(raw_public)

    raw_w = binfo.get("write_passwd") or binfo.get("write_password") or ""
    raw_r = binfo.get("read_passwd") or binfo.get("read_password") or ""
    write_password = base64.b64decode(raw_w).decode("utf-8") if raw_w else None
    read_password = base64.b64decode(raw_r).decode("utf-8") if raw_r else None

    return base_url, write_password, read_password, is_public


# ---------------------------------------------------------------------------
# In-memory tar extraction (member isolation)
# ---------------------------------------------------------------------------


def _extract_session_log(archive_bytes, session_id, wanted_suffixes):
    """Open the gzip tar archive in memory and return a list of
    (logical_node, text) for the session's log members.

    A single session id produces ONE '*_SqlSession_<id>.<N>' member PER NODE,
    stored under the physical hostname folder but suffixed by the LOGICAL node
    number '.<N>'. Members are selected by that '.N' SUFFIX — never by hostname
    sort order — because under crash/reserve failover logical node 0 can live on
    a hostname that sorts LAST, which the previous sorted()[0] selection got
    wrong.

    wanted_suffixes is a set of logical node numbers to keep, or None to keep
    every suffix (all-nodes). The result is ordered by logical node ascending.
    Reads ONLY the members that are kept; never extracts or reads any other
    archive member. Raises RuntimeError only on TOTAL absence (no matching
    member for the session id at all); a requested node whose member is missing
    is simply omitted (partial presence returns what exists). session_id is
    guaranteed numeric by the caller, so the glob/regex carry no metacharacters
    and the required '.' after the id blocks numeric-prefix collisions.
    """
    glob = "*_SqlSession_{}.*".format(session_id)
    suffix_re = re.compile(r"_SqlSession_" + re.escape(session_id) + r"\.([0-9]+)$")
    tf = tarfile.open(fileobj=BytesIO(archive_bytes), mode="r:gz")
    try:
        present_nodes = set()
        content_by_node = {}
        for member in tf.getmembers():
            if not member.isfile() or not fnmatch.fnmatch(member.name, glob):
                continue
            match = suffix_re.search(member.name)
            if match is None:
                continue
            node = int(match.group(1))
            present_nodes.add(node)
            if wanted_suffixes is not None and node not in wanted_suffixes:
                continue
            if node in content_by_node:
                continue
            extracted = tf.extractfile(member)
            raw = extracted.read() if extracted is not None else b""
            content_by_node[node] = raw.decode("utf-8", errors="replace")
        if not present_nodes:
            raise RuntimeError(
                "no session log found in the archive for session id {}".format(
                    session_id
                )
            )
    finally:
        tf.close()
    return [(node, content_by_node[node]) for node in sorted(content_by_node)]


# ---------------------------------------------------------------------------
# Orchestration
# ---------------------------------------------------------------------------


def _service_base_url(server, confd_host, service):
    """Return the BucketFS HTTP(S) base URL for a service from its ports.

    Service-level only (no bucket dependency), so it works for a bucket that was
    just created and may not yet be echoed inside bucketfs_info.
    """
    fi = _confd_call(server, "bucketfs_info", {"bucketfs_name": service})
    fs_out = (
        fi.get("result_output", {}) if isinstance(fi.get("result_output"), dict) else {}
    )
    http_port = int(fs_out.get("http_port") or 0)
    https_port = int(fs_out.get("https_port") or 0)
    if http_port:
        return "http://{}:{}".format(confd_host, http_port)
    if https_port:
        return "https://{}:{}".format(confd_host, https_port)
    raise RuntimeError(
        "service '{}': both http_port and https_port are zero".format(service)
    )


def _collect_session_log(
    server, confd_host, params, session_id, collected_at, http, archive_source, sleep
):
    """Drive the full SHOW SESSION LOG flow.

    Returns a list of (logical_node, text) tuples ordered by node ascending on
    success (run() splits each node's text into lines and emits the five-column
    rows), and RAISES on any failure. The session id is a caller-supplied SQL
    argument, not a JSON key.

    Two bucket-lifecycle modes:
      * DEFAULT (no 'bucket' in params): the UDF creates a uniquely-named
        PRIVATE bucket with random credentials, stages the archive there, and
        deletes BOTH the temp archive AND the bucket in a finally block — the
        caller provisions nothing and nothing is left behind.
      * CALLER BUCKET ('bucket' given): targets a caller-owned pre-existing
        bucket, refuses it if public, and deletes ONLY the temp archive (never
        the caller's bucket).
    In both modes the id is validated first and the temp archive is ALWAYS
    deleted; only the '*_SqlSession_<id>.<N>' members for the requested logical
    node(s) are ever read.
    """
    session_id = str(session_id).strip()
    if not _is_numeric_session_id(session_id):
        # Validation runs BEFORE any ConfD call, bucket creation, or BucketFS
        # write. The invalid id is not echoed (it may carry injection payload).
        raise ValueError("invalid session id: must be a plain numeric string")

    service = params.get("service") or _DEFAULT_SERVICE
    caller_bucket = params.get("bucket")

    # The caller-evaluated timestamp doubles as the bucket's creation tag and as
    # 'now' for the age-based sweep below (see _sweep_orphan_buckets). Absent an
    # usable timestamp the bucket is named without a stamp and is never swept.
    now_stamp = _stamp_of(collected_at)

    # Best-effort: reclaim ephemeral buckets orphaned by an earlier invocation
    # that was killed mid-flight (bypassing its finally-block cleanup). Purely
    # age-based, so it needs no live-session set (a worker-node UDF cannot query
    # SYS.EXA_ALL_SESSIONS); the normal finally-block cleanup still runs on every
    # invocation and is what handles all non-killed paths.
    _sweep_orphan_buckets(server, service, now_stamp)

    db_name = _resolve_db_name(server, params)
    if not db_name:
        raise RuntimeError("could not resolve the database name for exasolution_logs")

    # Resolve the node selection (and validate/map logical numbers) BEFORE any
    # debug_collect or ephemeral bucket creation, so an out-of-range request
    # raises loudly without leaving anything staged behind (there is no bucket to
    # clean up because none was created yet).
    debug_nodes, wanted_suffixes = _resolve_nodes(server, params)

    if caller_bucket:
        return _collect_via_caller_bucket(
            server,
            confd_host,
            service,
            caller_bucket,
            session_id,
            db_name,
            http,
            archive_source,
            debug_nodes,
            wanted_suffixes,
        )
    return _collect_via_ephemeral_bucket(
        server,
        confd_host,
        service,
        session_id,
        db_name,
        http,
        archive_source,
        sleep,
        debug_nodes,
        wanted_suffixes,
        now_stamp,
    )


def _collect_via_caller_bucket(
    server,
    confd_host,
    service,
    bucket,
    session_id,
    db_name,
    http,
    archive_source,
    debug_nodes,
    wanted_suffixes,
):
    """Stage into a caller-owned bucket. Refuses a public bucket before any
    write; deletes only the temp archive, never the caller's bucket. Returns the
    extracted (node, text) list on success and RAISES on failure."""
    base_url, write_password, read_password, is_public = _discover(
        server, confd_host, service, bucket
    )

    if is_public:
        raise RuntimeError(
            "refusing to stage a secret-bearing support archive in public "
            "bucket '{}/{}'; use a dedicated PRIVATE bucket".format(service, bucket)
        )
    if write_password is None:
        raise RuntimeError(
            "bucket '{}/{}': no write password available; cannot guarantee "
            "cleanup of the temporary archive".format(service, bucket)
        )

    read_auth = ("r", read_password) if read_password else ("w", write_password)
    return _stage_fetch_extract(
        server,
        service,
        bucket,
        base_url,
        session_id,
        db_name,
        http,
        archive_source,
        write_password,
        read_auth,
        debug_nodes,
        wanted_suffixes,
    )


def _collect_via_ephemeral_bucket(
    server,
    confd_host,
    service,
    session_id,
    db_name,
    http,
    archive_source,
    sleep,
    debug_nodes,
    wanted_suffixes,
    now_stamp,
):
    """Create a uniquely-named PRIVATE bucket with random credentials, stage the
    archive, and delete BOTH the temp archive and the bucket in finally. Returns
    the extracted (node, text) list on success and RAISES on failure — the
    finally block still runs on the way out, so nothing is left behind.

    The name carries this invocation's caller-evaluated timestamp so a later run
    can age out a bucket orphaned by a killed invocation (_sweep_orphan_buckets);
    the session id follows it purely for diagnosis. Without a usable timestamp
    the stamp is omitted, which makes the bucket unsweepable (unknown age) rather
    than sweepable at an unknown time."""
    tag = "{}_{}".format(now_stamp, session_id) if now_stamp else str(session_id)
    bucket = "{}_{}_{}".format(_EPHEMERAL_BUCKET_PREFIX, tag, uuid.uuid4().hex)
    read_pw = uuid.uuid4().hex
    write_pw = uuid.uuid4().hex

    # A bucket_add failure means nothing was created, so it raises without
    # entering the try/finally below (there is no bucket to tear down).
    _confd_call(
        server,
        "bucket_add",
        {
            "bucket_name": bucket,
            "bucketfs_name": service,
            "public": False,
            "read_password": read_pw,
            "write_password": write_pw,
        },
    )

    try:
        base_url = _service_base_url(server, confd_host, service)
        # bucket_add does NOT immediately create the on-disk
        # /exa/data/bucketfs/<service>/<bucket>/ directory that debug_collect's
        # `outfile` writes to (a direct filesystem write, not an HTTP upload),
        # and a just-created bucket's HTTP endpoint returns 400 for ~1-2s until
        # it is ready. Prime the served folder with a placeholder PUT (which goes
        # THROUGH the BucketFS service and creates the directory), retrying until
        # the endpoint accepts it, so the subsequent debug_collect write never
        # races the new bucket's lazy readiness.
        prime_url = "{}/{}/{}".format(base_url, bucket, ".init")
        status = None
        for attempt in range(_PRIME_MAX_ATTEMPTS):
            status, _ = http("PUT", prime_url, auth=("w", write_pw), data=b"init")
            if status in (200, 201, 204):
                break
            sleep(_PRIME_RETRY_SECONDS)
        if status not in (200, 201, 204):
            raise RuntimeError(
                "ephemeral bucket did not become writable (last HTTP {})".format(status)
            )
        return _stage_fetch_extract(
            server,
            service,
            bucket,
            base_url,
            session_id,
            db_name,
            http,
            archive_source,
            write_pw,
            ("r", read_pw),
            debug_nodes,
            wanted_suffixes,
        )
    finally:
        # Guaranteed teardown of the ephemeral bucket (the temp archive is
        # deleted inside _stage_fetch_extract; bucket_delete removes the bucket
        # regardless of its remaining contents) — on success AND failure. Runs on
        # the way out even when the body raises, before the error propagates.
        try:
            _confd_call(
                server,
                "bucket_delete",
                {"bucket_name": bucket, "bucketfs_name": service},
            )
        except Exception:
            pass


def _stage_fetch_extract(
    server,
    service,
    bucket,
    base_url,
    session_id,
    db_name,
    http,
    archive_source,
    write_password,
    read_auth,
    debug_nodes,
    wanted_suffixes,
):
    """Shared stage→fetch→extract for both bucket modes. Runs debug_collect into
    the bucket's served folder (constraining it to the mapped hostnames unless
    debug_nodes is falsy — None for all-nodes, or an empty list, whose
    debug_collect behaviour is undefined and so is omitted like all-nodes),
    fetches the archive, extracts the requested SqlSession members by '.N'
    suffix, and ALWAYS deletes the temp archive in finally.

    Returns the extracted list of (logical_node, text) tuples ordered by node
    ascending, and RAISES on failure — the finally block deletes the temp archive
    on the way out either way, before the error propagates."""
    filename = "{}_{}.tar.gz".format(session_id, uuid.uuid4().hex)
    outfile = "{}/{}/{}/{}".format(_BUCKETFS_BASE_PATH, service, bucket, filename)
    bfs_url = "{}/{}/{}".format(base_url, bucket, filename)

    try:
        collect_params = {
            "exasolution_logs": [db_name],
            "exasolution_log_type": ["Session {}".format(session_id)],
            "timeout": _DEBUG_COLLECT_TIMEOUT,
            "outfile": outfile,
        }
        if debug_nodes:
            collect_params["nodes"] = debug_nodes
        _confd_call(server, "debug_collect", collect_params)

        if archive_source is not None:
            status, body = archive_source(bfs_url, read_auth)
        else:
            status, body = http("GET", bfs_url, auth=read_auth)
        if status != 200:
            raise RuntimeError(
                "BucketFS GET of session archive returned HTTP {}".format(status)
            )

        return _extract_session_log(body, session_id, wanted_suffixes)
    finally:
        # Guaranteed cleanup: delete the temp archive on success AND failure.
        try:
            http("DELETE", bfs_url, auth=("w", write_password))
        except Exception:
            pass


# ---------------------------------------------------------------------------
# Public entry points
# ---------------------------------------------------------------------------


def _execute(
    connection,
    params_json,
    session_id,
    collected_at=None,
    proxy_factory=None,
    http=None,
    archive_source=None,
    sleep=None,
):
    """Pure, dependency-injected core. Tests drive this directly.

    Returns the extracted list of (logical_node, text) tuples ordered by node
    ascending on success, and RAISES on any failure (no ERR: sentinel).
    Validation failures raise ValueError; operational failures raise a
    RuntimeError whose message is redacted so credentials/URLs never leak.

    connection    — object with .address, .user, .password attributes
    params_json   — JSON string with optional bucket / service / db_name /
                    node selection; it does NOT carry the session id
    session_id    — the caller-supplied SQL argument (a numeric string)
    collected_at  — the caller-supplied TIMESTAMP SQL argument; tags the
                    ephemeral bucket and supplies 'now' for the orphan sweep.
                    When absent/unusable the bucket is left unstamped and the
                    sweep is skipped (both are safe no-ops)
    proxy_factory — callable(url) -> XML-RPC proxy; default uses live SSL
    http          — callable(method, url, auth=None, data=None) -> (status, bytes)
    archive_source — optional callable(url, auth) -> (status, bytes) used INSTEAD
                    of http for fetching the archive bytes (tests inject a real
                    gzip tarball); when None the archive is fetched over http.
    sleep         — callable(seconds) used between ephemeral-bucket readiness
                    retries; default time.sleep (tests inject a no-op).
    """
    try:
        params = json.loads(params_json) if params_json and params_json.strip() else {}
    except Exception as exc:
        raise ValueError("params_json is not valid JSON: " + _redact(exc)) from None
    if not isinstance(params, dict):
        raise ValueError("params_json must be a JSON object")

    if proxy_factory is None:
        proxy_factory = _default_proxy_factory
    if http is None:
        http = _default_http
    if sleep is None:
        sleep = time.sleep

    try:
        endpoint = _build_endpoint(
            connection.address, connection.user, connection.password
        )
        server = proxy_factory(endpoint)
        confd_host = _host_from_address(connection.address)
        return _collect_session_log(
            server,
            confd_host,
            params,
            session_id,
            collected_at,
            http,
            archive_source,
            sleep,
        )
    except ValueError:
        # Validation errors carry no secrets and keep their type so the caller
        # can distinguish an invalid request from an operational failure.
        raise
    except Exception as exc:
        # Any operational failure (transport, BucketFS, extraction) surfaces as a
        # redacted RuntimeError. Deeper finally blocks have already run cleanup on
        # the way here, so nothing is left behind before this propagates.
        raise RuntimeError(_redact(exc)) from None


def _inject_default_db_name(params_json, default_db_name):
    """Add the running database name as a db_name-inference fallback so db
    resolution can fall back when ConfD db_list is unavailable.

    Returns params_json unchanged when it is absent/blank, not a JSON object, or
    already carries a db_name.
    """
    if params_json is None or str(params_json).strip() == "":
        return params_json
    try:
        params = json.loads(params_json)
    except Exception:
        return params_json
    if isinstance(params, dict) and not params.get("db_name"):
        params["db_name"] = default_db_name
        return json.dumps(params)
    return params_json


def run(ctx):
    # No ERR: sentinel and no broad try/except: a failure MUST raise so it
    # surfaces as a visible SQL error and aborts the surrounding statement. The
    # session id and timestamp arrive as caller-evaluated SQL arguments.
    connection = exa.get_connection(ctx.connection_name)  # noqa: F821
    params_json = _inject_default_db_name(
        ctx.params_json,
        exa.meta.database_name,  # noqa: F821
    )
    extracted = _execute(connection, params_json, ctx.session_id, ctx.collected_at)
    # The id is validated numeric by _execute; emit it as a Python int so digits
    # above 2^53 survive the DECIMAL(20,0) column. Every row carries the SAME
    # caller-supplied collected_at verbatim (never a synthesised per-row value).
    session_id = int(str(ctx.session_id).strip())
    for node, text in extracted:
        for line_no, line in enumerate(text.splitlines(), start=1):
            ctx.emit(session_id, node, line_no, line, ctx.collected_at)
/

--/
CREATE OR REPLACE PYTHON3 SCALAR SCRIPT PREPROC_RT.LOG_EVENTS_V1(connection_name VARCHAR(128), params_json VARCHAR(2000000)) EMITS (ts VARCHAR(64), node VARCHAR(128), priority VARCHAR(32), message VARCHAR(2000000)) AS
# LOG_EVENTS_V1  (PREPROC_RT.LOG_EVENTS_V1)  — Python3 SCALAR UDF body
# =============================================================================
# Inline-capable, typed-column replacement for the retired presentation admin
# script PREPROC.ADMIN_LOG_COLLECT. Where that Lua script called the generic
# gateway PREPROC_RT.CONFD_JOB_V1 with the fixed job name 'log_collect' and
# then rendered the result as a typed table, this UDF does BOTH jobs itself:
#
#   * calls the ConfD 'log_collect' job over XML-RPC directly (the network
#     role ADMIN_CONFD_JOB used to own), and
#   * EMITS one (TS, NODE, PRIORITY, MESSAGE) row per event in result_output
#     (the presentation role ADMIN_LOG_COLLECT used to own) — deliberately NOT
#     the generic FIELD/VALUE_TEXT flatten CONFD_QUERY_V1 uses, since a
#     log-event array reads far better as one row per event, and
#   * RAISES on any failure instead of returning an 'ERR:' sentinel (the loud
#     error role ADMIN_LOG_COLLECT's error() call used to own).
#
# Because it is a UDF expression rather than an EXECUTE SCRIPT statement, a
# CONTROL command that rewrites into a call to this UDF can be EMBEDDED inside
# a larger SQL statement:
#
#     INSERT INTO t SELECT * FROM (
#         SELECT PREPROC_RT.LOG_EVENTS_V1('CONFD_CONNECTION', '{"services":["ConfD"]}')
#         FROM (SELECT 1))
#
# whereas EXECUTE SCRIPT can only ever stand alone.
#
# Contract
#   No ERR: sentinel. run() RAISES. A failed ConfD job (transport error,
#   missing CONNECTION, non-zero envelope result_code) aborts the surrounding
#   statement with a visible SQL error. `log_collect` is NOT database-scoped,
#   so — unlike CONFD_QUERY_V1/CONFD_JOB_V1 — there is no db_name inference
#   here.
#
# This file is BOTH an importable module (unit-tested via
# tests/test_log_events.py) and the verbatim body embedded into the
# CREATE PYTHON3 SCALAR SCRIPT ... EMITS(...) by build.py. The `exa` runtime
# object and ctx.emit are only touched inside run(); every piece of logic is
# dependency-injected so the tests need no database. UDF bodies are embedded
# verbatim and cannot import a sibling, so this file duplicates the small
# helpers it shares with confd_query_v1.py rather than importing them.
# =============================================================================
import json
import ssl
import xmlrpc.client
from urllib.parse import quote as _urlquote

JOB_NAME = "log_collect"


def _build_endpoint(address, user, password):
    """Build the XML-RPC URL 'scheme://user:password@host:port'. Identical to
    CONFD_QUERY_V1._build_endpoint (kept self-contained: UDF bodies are
    embedded verbatim and cannot import a sibling)."""
    addr = address or ""
    if "://" in addr:
        scheme, rest = addr.split("://", 1)
    else:
        scheme, rest = "https", addr
    if "@" in rest:
        rest = rest.split("@", 1)[1]
    return "{}://{}:{}@{}".format(
        scheme,
        _urlquote(user or "", safe=""),
        _urlquote(password or "", safe=""),
        rest,
    )


def _parse_params(params_json):
    """Parse the JSON params object. Unlike CONFD_QUERY_V1, log_collect is not
    database-scoped, so no db_name inference happens here."""
    params = {}
    if params_json is not None and str(params_json).strip() != "":
        params = json.loads(params_json)
    if not isinstance(params, dict):
        raise ValueError("params_json must be a JSON object")
    return params


def _call_confd(connection, params_json, proxy_factory=None):
    """Parse params, build the endpoint, run the log_collect job, and return
    the decoded envelope (a dict). Raises on transport failure."""
    params = _parse_params(params_json)
    endpoint = _build_endpoint(connection.address, connection.user, connection.password)
    if proxy_factory is None:
        sslctx = ssl._create_unverified_context()

        def proxy_factory(url):
            return xmlrpc.client.ServerProxy(url, context=sslctx, allow_none=True)

    server = proxy_factory(endpoint)
    return server.job_exec(JOB_NAME, {"params": params})


def _check_envelope(envelope):
    """Raise if the ConfD envelope reports a non-zero result_code, carrying
    the ConfD result_desc so an unknown-service failure surfaces loudly
    instead of as an empty result set."""
    if isinstance(envelope, dict):
        code = envelope.get("result_code")
        if isinstance(code, int) and code != 0:
            desc = envelope.get("result_desc") or envelope.get("result_name") or ""
            raise RuntimeError(
                "ConfD job '{}' failed (code {}): {}".format(JOB_NAME, code, desc)
            )


def _rows_for(envelope):
    """Turn a decoded log_collect envelope into (ts, node, priority, message)
    tuples, one per event in result_output. An empty/absent event array
    yields zero rows (not an error, not a status row)."""
    events = envelope.get("result_output") if isinstance(envelope, dict) else None
    rows = []
    if isinstance(events, list):
        for event in events:
            if isinstance(event, dict):
                rows.append(
                    (
                        str(event.get("timestamp") or ""),
                        str(event.get("node") or ""),
                        str(event.get("priority") or ""),
                        str(event.get("message") or ""),
                    )
                )
    return rows


def _execute(connection, params_json, proxy_factory=None):
    """Dependency-injected core: call log_collect, raise on failure, and
    return the list of (ts, node, priority, message) tuples to emit."""
    envelope = _call_confd(connection, params_json, proxy_factory=proxy_factory)
    _check_envelope(envelope)
    return _rows_for(envelope)


def run(ctx):
    # No ERR: sentinel and no try/except: a failure MUST raise so it surfaces
    # as a visible SQL error and aborts the surrounding statement.
    connection = exa.get_connection(ctx.connection_name)  # noqa: F821 (exa: runtime)
    for ts, node, priority, message in _execute(connection, ctx.params_json):
        ctx.emit(ts, node, priority, message)
