CREATE OR REPLACE PYTHON3 SCALAR SCRIPT PREPROC_RT.REMOTE_VOLUME_QUERY_V1(connection_name VARCHAR(128), params_json VARCHAR(2000000)) EMITS (field VARCHAR(256), value_text VARCHAR(2000000)) AS
# =============================================================================
# REMOTE_VOLUME_QUERY_V1  (PREPROC_RT.REMOTE_VOLUME_QUERY_V1)  — Python3 SCALAR UDF body
# =============================================================================
# Dedicated redacting counterpart of CONFD_QUERY_V1 for the one remote-volume
# read that carries cleartext credentials in its ConfD response: the detail
# SHOW REMOTE VOLUME '<name>' read. remote_volume_info echoes the volume's
# stored username/password verbatim (verified live). remote_volume_v1.py now
# keeps only the _add action; the detail read and its credential redaction were
# moved here — a plain flatten through CONFD_QUERY_V1 would leak
# them as ordinary result rows. This UDF strips those two keys BEFORE the
# generic flatten ever sees them, then EMITS (FIELD, VALUE_TEXT) rows exactly
# like CONFD_QUERY_V1 does for every other read.
#
# Like CONFD_QUERY_V1, this UDF absorbs both the network role (call the ConfD
# job over XML-RPC) and the presentation role (flatten result_output) in one
# expression, so a CONTROL command that rewrites to a call to this UDF can be
# embedded inside a larger SQL statement rather than only ever standing alone
# as an EXECUTE SCRIPT statement.
#
# Contract
#   No ERR: sentinel. run() RAISES on transport failure or a non-zero
#   result_code, and the raised message is REDACTED (_redact, matching
#   remote_volume_v1.py's treatment) so a resolved credential never appears,
#   even though the failure path never reaches the point of stripping
#   result_output.
#
# This file is BOTH an importable module (unit-tested via
# tests/test_remote_volume_query.py) and the verbatim body embedded into the
# CREATE PYTHON3 SCALAR SCRIPT by build.py. The `exa` runtime object and
# ctx.emit are only touched inside run(); every piece of logic is
# dependency-injected so the tests need no database.
#
# UDF signature (declared in the CREATE script header by build.py):
#   PREPROC_RT.REMOTE_VOLUME_QUERY_V1(connection_name VARCHAR(128),
#                                      params_json     VARCHAR(2000000))
#   EMITS (field VARCHAR(256), value_text VARCHAR(2000000))
#
# Self-contained
#   build.py embeds this file verbatim as a UDF body, so it MUST NOT import
#   anything outside the Python stdlib and MUST NOT produce side effects at
#   import time. _build_endpoint, _confd_call, and _redact are duplicated
#   VERBATIM from remote_volume_v1.py; _flatten mirrors the flatten semantics
#   of confd_query_v1.py. Importing across UDF bodies is impossible.
# =============================================================================
import json
import re
import ssl
import xmlrpc.client
from urllib.parse import quote as _urlquote


# ---------------------------------------------------------------------------
# Module constants
# ---------------------------------------------------------------------------

# Attribute keys stripped from remote_volume_info output before it is
# flattened. Compared case-insensitively so no cased variant leaks the stored
# secret.
_CREDENTIAL_KEYS = ("username", "password")


# ---------------------------------------------------------------------------
# Internal helpers (duplicated VERBATIM from remote_volume_v1.py — file must
# stay self-contained; UDF bodies cannot import across each other)
# ---------------------------------------------------------------------------


def _build_endpoint(address, user, password):
    """Build the XML-RPC URL 'scheme://user:password@host:port' from a
    CONNECTION's address plus credentials.

    The address may or may not carry a scheme and may already embed
    credentials (which are stripped and replaced). ConfD speaks HTTPS; a bare
    host:port is assumed to be https.
    """
    addr = address or ""
    if "://" in addr:
        scheme, rest = addr.split("://", 1)
    else:
        scheme, rest = "https", addr
    if "@" in rest:
        rest = rest.split("@", 1)[1]
    return "{}://{}:{}@{}".format(
        scheme,
        _urlquote(user or "", safe=""),
        _urlquote(password or "", safe=""),
        rest,
    )


def _redact(text):
    """Remove secrets from URLs embedded in exception/error messages.

    Strips both basic-auth credentials (user:pass@) and URL query strings
    (?...). xmlrpc.client.ProtocolError renders the ConfD endpoint without a
    scheme (user:pass@host:port), so the credential pattern is matched with
    or without a leading scheme://; presigned source URLs carry their
    signature in the query string. Both are secrets that must never appear
    in a raised message.
    """
    s = re.sub(r"[^/@\s:]+:[^/@\s]+@", "<redacted>@", str(text))
    s = re.sub(r'\?[^\s"\']*', "?<redacted>", s)
    return s


def _confd_call(server, job, params):
    """Call server.job_exec(job, {"params": params}) and return the result
    dict.

    Raises RuntimeError if result_code is non-zero.
    """
    result = server.job_exec(job, {"params": params})
    code = result.get("result_code", 0) if isinstance(result, dict) else 0
    if code != 0:
        desc = ""
        if isinstance(result, dict):
            desc = result.get("result_desc") or result.get("result_name") or ""
        raise RuntimeError(
            "ConfD job '{}' failed (code {}): {}".format(job, code, desc)
        )
    return result


def _default_proxy_factory(url):
    """Build a live XML-RPC ServerProxy with an unverified SSL context."""
    sslctx = ssl._create_unverified_context()
    return xmlrpc.client.ServerProxy(url, context=sslctx, allow_none=True)


# ---------------------------------------------------------------------------
# Credential redaction
# ---------------------------------------------------------------------------


def _strip_credentials(output):
    """Return a copy of the remote_volume_info attribute object with the
    stored username/password removed.

    remote_volume_info echoes the volume's username and password in
    cleartext (verified live); they MUST NOT reach the emitted rows. Keys are
    matched case-insensitively. A non-dict output carries no attribute keys
    to strip and is normalised to an empty object so nothing un-vetted is
    surfaced.
    """
    if not isinstance(output, dict):
        return {}
    return {
        key: value
        for key, value in output.items()
        if str(key).lower() not in _CREDENTIAL_KEYS
    }


# ---------------------------------------------------------------------------
# Flatten (mirrors confd_query_v1.py's flatten semantics)
# ---------------------------------------------------------------------------


def _scalar_text(value):
    """Render a JSON leaf the way the Lua flatten() did: booleans as
    true/false, integral floats without a trailing .0, everything else
    str()."""
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value)


def _flatten(prefix, value, rows):
    """Flatten an arbitrarily-nested decoded value into (field, value_text)
    tuples. Object keys are sorted and joined with '.', array elements use a
    1-based [i] suffix, JSON null and empty containers get explicit leaf
    markers."""
    label = prefix if prefix != "" else "value"
    if value is None:
        rows.append((label, "null"))
        return
    if isinstance(value, dict):
        if not value:
            rows.append((label, "(empty)"))
            return
        for k in sorted(value.keys(), key=str):
            child = str(k) if prefix == "" else prefix + "." + str(k)
            _flatten(child, value[k], rows)
        return
    if isinstance(value, list):
        if not value:
            rows.append((label, "(empty)"))
            return
        for i, item in enumerate(value, start=1):
            _flatten(prefix + "[" + str(i) + "]", item, rows)
        return
    rows.append((label, _scalar_text(value)))


# ---------------------------------------------------------------------------
# Public entry points
# ---------------------------------------------------------------------------


def _execute(connection, params_json, proxy_factory=None):
    """Pure, dependency-injected core. Tests drive this directly with a fake
    connection object and a fake XML-RPC proxy factory.

    connection    — ConfD CONNECTION object (.address/.user/.password);
                    builds the XML-RPC endpoint
    params_json   — JSON string: {"remote_volume_name"} (or
                    {"remote_volume_id"})
    proxy_factory — callable(url) -> XML-RPC proxy; default uses live SSL

    Returns a list of (field, value_text) tuples to emit. Raises (redacted)
    on transport failure or a non-zero result_code — no ERR: sentinel.
    """
    params = json.loads(params_json) if params_json and str(params_json).strip() else {}
    if not isinstance(params, dict):
        raise ValueError("params_json must be a JSON object")

    info_params = {}
    if params.get("remote_volume_name") is not None:
        info_params["remote_volume_name"] = params["remote_volume_name"]
    if params.get("remote_volume_id") is not None:
        info_params["remote_volume_id"] = params["remote_volume_id"]

    if proxy_factory is None:
        proxy_factory = _default_proxy_factory

    try:
        endpoint = _build_endpoint(
            connection.address, connection.user, connection.password
        )
        server = proxy_factory(endpoint)
        if not info_params:
            raise ValueError("remote volume detail read requires 'remote_volume_name'")
        result = _confd_call(server, "remote_volume_info", info_params)
        output = result.get("result_output") if isinstance(result, dict) else None
        output = _strip_credentials(output)
    except Exception as exc:
        # `from None`, not `from exc`: the original exception can carry the
        # un-redacted result_desc/URL (with the resolved credential) on
        # __cause__, which would leak the secret through the cause chain even
        # though the raised message is redacted. Severing the chain matches
        # session_log_v1.py's redacting raise.
        raise RuntimeError(_redact(str(exc))) from None

    rows = []
    _flatten("", output, rows)
    return rows


def run(ctx):
    # No ERR: sentinel and no try/except: a failure MUST raise so it surfaces
    # as a visible SQL error and aborts the surrounding statement.
    connection = exa.get_connection(ctx.connection_name)  # noqa: F821 (exa: runtime)
    rows = _execute(connection, ctx.params_json)
    for field, value_text in rows:
        ctx.emit(field, value_text)
/

