CREATE OR REPLACE LUA SCRIPT PREPROC_RT.CONFD_CONTROL_V1() AS
-- ----- sql/control_database_v1.lua: fenced verbatim, so its locals stay private -----
do
-- =============================================================================
-- CONTROL_DATABASE_V1  (assembled into PREPROC_RT.CONFD_CONTROL_V1, not deployed alone)  — EXPAND-phase grammar
-- =============================================================================
-- The curated SQL surface for ConfD-backed database administration. It parses
-- the `CONTROL DATABASE <verb> <object> …` keyword grammar and rewrites each
-- recognised command into exactly one
-- `EXECUTE SCRIPT PREPROC.ADMIN_CONFD_JOB_V1(job, params)` or
-- `EXECUTE SCRIPT PREPROC.ADMIN_VIRTUAL_RESTORE_V1(action, params)` call.
-- Commands:
--
--   CONTROL DATABASE SHOW INFO                                          -> db_info
--   CONTROL DATABASE SHOW BACKUPS                                       -> db_backup_list
--   CONTROL DATABASE SHOW BACKUP PROGRESS                               -> db_backup_progress
--   CONTROL DATABASE ABORT BACKUP                                       -> db_backup_abort
--   CONTROL DATABASE DELETE UNUSABLE BACKUPS                            -> db_backup_delete_unusable
--   CONTROL DATABASE DELETE BACKUP '<id>' [, '<id>' …]                  -> db_backups_delete
--   CONTROL DATABASE START BACKUP TO VOLUME <vol>
--       [WITH LEVEL <n>] [AND EXPIRATION '<t>']                         -> db_backup_start
--   CONTROL DATABASE ADD BACKUP SCHEDULE '<name>' TO VOLUME <vol>
--       [WITH LEVEL <n>] [AT '<cron>'] [AND EXPIRATION '<t>']
--       [ENABLED|DISABLED]                                              -> db_backup_add_schedule
--   CONTROL DATABASE MODIFY BACKUP SCHEDULE '<name>'
--       [AT '<cron>'] [WITH EXPIRATION '<t>'] [ENABLED|DISABLED]        -> db_backup_modify_schedule
--   CONTROL DATABASE MODIFY BACKUP EXPIRATION ON VOLUME <vol>
--       FOR '<backup_files>' TO '<YYYY-MM-DD hh:mm:ss>'                 -> db_backup_change_expiration
--   CONTROL DATABASE START VIRTUAL RESTORE FROM BACKUP '<backup_id>'
--       FOR SCHEMA 'S1' [, 'S2' …]
--       USING CONNECTION <jdbc_conn> [AND EXA CONNECTION <exa_conn>]
--       [AS <vdb_name>] [WITH PORT <n>]
--       [AND MEM SIZE '<sz>'] [AND VOLUME SIZE '<sz>']
--       [AND ADAPTER JAR '<path>'] [AND TIMEOUT <secs>]                 -> ADMIN_VIRTUAL_RESTORE_V1 'start'
--   CONTROL DATABASE SHOW VIRTUAL RESTORE [<vdb_name>]                  -> db_state (explicit name)
--   CONTROL DATABASE STOP VIRTUAL RESTORE [<vdb_name>]                  -> ADMIN_VIRTUAL_RESTORE_V1 'stop'
--   CONTROL DATABASE SHOW LICENSE                                       -> license_info
--   CONTROL DATABASE SHOW LICENSE FILE                                  -> license_download
--   CONTROL DATABASE CHECK LICENSE                                      -> license_run_check
--   CONTROL DATABASE INSTALL LICENSE FROM '<url>'
--       | FROM CONTENT '<blob>'
--       | FROM BUCKETFS FILE '<path>' IN BUCKET '<b>' [IN SERVICE '<s>'] -> ADMIN_LICENSE_V1 'install'
--   CONTROL DATABASE SHOW LOG EVENTS FOR SERVICE '<s>' [, …]
--       [SINCE …] [UNTIL …] [WITH LEVEL …] [ON NODE …]
--       [FOR DATABASE …] [WITHIN …] [TAG …]                             -> LOG_EVENTS_V1 (read, log_collect)
--   CONTROL DATABASE COLLECT DEBUG INFO INCLUDING <cat> [, …]
--       [SINCE …] [UNTIL …] [ON NODE …] [FOR DATABASE …]
--       [WITH TIMEOUT <secs>] [TO REMOTE VOLUME <vol> AT '<path>']       -> debug_collect
--   CONTROL DATABASE SHOW SESSION LOG FOR { CURRENT_SESSION | SESSION '<id>' }
--       [ON NODE(S) … | ON ALL NODES] [USING BUCKET '<b>' IN SERVICE '<s>']  -> SESSION_LOG_V1 (read)
--
-- The license, log-event, debug-collect, and session-log jobs are cluster-global:
-- they NEVER carry the "db_name" inference marker (build_json, not db_params).
--
-- The remote-volume family (SHOW/ADD/DROP REMOTE VOLUME) used to live here and now
-- lives in CONTROL_STORAGE_V1 — a remote volume is a storage object, not a database
-- one. `CONTROL DATABASE … REMOTE VOLUME …` therefore declines here. The one
-- remaining mention is `COLLECT DEBUG INFO … TO REMOTE VOLUME <vol>`, a
-- debug_collect destination clause rather than a remote-volume command.
--
-- Conventions
--   * The database NAME is never typed. Jobs that take a db_name carry the
--     marker "db_name":"" in their params; the UDF substitutes the current
--     database. db_backup_change_expiration is NOT scoped to a database, so it
--     omits the marker (see the UDF's opt-in inference).
--   * String arguments (schedule names, backup ids, file prefixes, times, cron
--     specs, expirations) are single-quoted. Volume names are bare identifiers
--     (matching `TO VOLUME <vol>`). LEVEL defaults to 0 (full backup).
--   * <cron> is a 5-field crontab string 'min hour day month weekday'
--     (e.g. '0 2 * * 0' = 02:00 every Sunday).
--   * VIRTUAL RESTORE commands do NOT use the db_name inference marker — the
--     virtual DB name is always explicit (default VR1) and the issuing DB name
--     is irrelevant to the grammar layer.
--
-- Follows the framework's EXPAND authoring contract: return nil to decline
-- (fail-open), a single string to accept (terminal); export a top-level global
-- `control_database_expand`; no defensive pcall; capture gsub's result into one
-- local.
-- Scoped to the DBA role via the module's RULE_ENSURE-registered rule.
-- =============================================================================

-- luacheck: globals control_database_expand

local SENTINEL = "\1"

-- Replace every single-quoted '...' literal with a placeholder token
-- \1<index>\1 (padded with spaces so it tokenises cleanly), returning the
-- de-quoted text and the ordered list of literal values. This lets the rest of
-- the parser tokenise on whitespace without quoted values (which may contain
-- spaces, commas, or '=') breaking the scan.
local function extract_literals(text)
    local literals = {}
    local out = text:gsub("'([^']*)'", function(value)
        literals[#literals + 1] = value
        return " " .. SENTINEL .. #literals .. SENTINEL .. " "
    end)
    return out, literals
end

-- Tokenise on whitespace, first isolating ',' and '=' as their own tokens so
-- `key=value` and `a,b` split regardless of surrounding spaces.
local function tokenize(text)
    local spaced = text:gsub("[,=]", " %0 ")
    local tokens = {}
    for word in spaced:gmatch("%S+") do
        tokens[#tokens + 1] = word
    end
    return tokens
end

-- If token is a literal placeholder, return its value; else nil.
local function as_literal(token, literals)
    if not token then
        return nil
    end
    local idx = token:match("^" .. SENTINEL .. "(%d+)" .. SENTINEL .. "$")
    if idx then
        return literals[tonumber(idx)]
    end
    return nil
end

-- Resolve a token to its string value: the literal value if it is a placeholder,
-- otherwise the bare token text unchanged (e.g. a volume name or integer).
local function resolve(token, literals)
    local value = as_literal(token, literals)
    if value ~= nil then
        return value
    end
    return token
end

-- Uppercase a token for case-insensitive keyword comparison (nil-safe).
local function U(token)
    return token and string.upper(token) or nil
end

-- Escape a value for embedding as a SQL single-quoted string literal.
local function sql_quote(value)
    local escaped = value:gsub("'", "''")
    return "'" .. escaped .. "'"
end

-- Escape a value for embedding inside a JSON double-quoted string.
local function json_escape(value)
    local s = value:gsub("\\", "\\\\")
    s = s:gsub('"', '\\"')
    -- Escape ASCII control characters (0x01-0x1F): a raw newline/tab in a JSON
    -- string is invalid and breaks cjson.decode downstream. Needed for
    -- multi-line values such as an inlined license blob (INSTALL LICENSE FROM
    -- CONTENT). (Text carries no NUL, so 0x00 need not be handled.)
    s = s:gsub("[\1-\31]", function(c)
        local b = string.byte(c)
        if b == 8 then return "\\b"
        elseif b == 9 then return "\\t"
        elseif b == 10 then return "\\n"
        elseif b == 12 then return "\\f"
        elseif b == 13 then return "\\r"
        else return string.format("\\u%04x", b) end
    end)
    return s
end

-- Format a "key":"value" JSON string pair.
local function json_str(key, value)
    return '"' .. key .. '":"' .. json_escape(value) .. '"'
end

-- Build a JSON object from a list of preformatted "key":value parts.
local function build_json(parts)
    return "{" .. table.concat(parts, ",") .. "}"
end

-- Build a JSON object that opts in to db_name inference (UDF fills it in).
local function db_params(parts)
    local p = { '"db_name":""' }
    for _, part in ipairs(parts) do
        p[#p + 1] = part
    end
    return build_json(p)
end

-- The single emitted statement: one EXECUTE SCRIPT call. The job name is a
-- trusted constant; params_json is carried as a SQL string literal.
local function emit(job, params_json)
    return "EXECUTE SCRIPT PREPROC.ADMIN_CONFD_JOB_V1('"
        .. job .. "', " .. sql_quote(params_json) .. ")"
end

-- The ConfD CONNECTION object name (mirrors the constant in the Lua admin
-- scripts). Read commands route through the CONFD_QUERY_V1 EMITS UDF, which
-- resolves this CONNECTION itself.
local CONFD_CONNECTION = "CONFD_CONNECTION"

-- The inline-capable rewrite target for READ commands: a scalar-EMITS UDF call
-- driven by a single-row source. Unlike EXECUTE SCRIPT, this is a table
-- EXPRESSION — it can stand alone as a SELECT statement AND be embedded as a
-- subquery inside a larger statement (INSERT INTO t SELECT * FROM (<this>)).
-- The UDF flattens the ConfD envelope into (FIELD, VALUE_TEXT) rows and raises
-- on failure, so no Lua admin layer sits between the preprocessor and the UDF.
local function query_select(job, params_json)
    return "SELECT PREPROC_RT.CONFD_QUERY_V1('" .. CONFD_CONNECTION .. "', '"
        .. job .. "', " .. sql_quote(params_json) .. ") FROM (SELECT 1)"
end

-- Standalone form of a read command: a bare SELECT statement. The embedded form
-- (a subquery) is produced by the splicer, which re-parenthesises this SELECT.
local function emit_query(job, params_json)
    return query_select(job, params_json)
end

-- INSTALL LICENSE routes to the license orchestrator, which resolves the license
-- bytes server-side (URL fetch / inline blob / BucketFS GET) then uploads them.
local function emit_license(action, params_json)
    return "EXECUTE SCRIPT PREPROC.ADMIN_LICENSE_V1('"
        .. action .. "', " .. sql_quote(params_json) .. ")"
end

-- SHOW LOG EVENTS routes to a dedicated read UDF that renders one typed row per
-- event (TS, NODE, PRIORITY, MESSAGE) instead of the generic per-leaf flattening;
-- a bare, embeddable SELECT like the other reads.
local function emit_log_events(params_json)
    return "SELECT PREPROC_RT.LOG_EVENTS_V1('" .. CONFD_CONNECTION .. "', "
        .. sql_quote(params_json) .. ") FROM (SELECT 1)"
end

-- SHOW SESSION LOG routes to the session-log read UDF, which emits five
-- self-describing columns directly. session_id_expr is spliced RAW into the SQL
-- (a single-quoted numeric literal, or the caller-evaluated TO_CHAR(CURRENT_SESSION)
-- expression), never json-escaped; CURRENT_TIMESTAMP supplies one COLLECTED_AT per
-- invocation (a worker UDF cannot see the caller's session or clock).
local function emit_session_log_query(params_json, session_id_expr)
    return "SELECT PREPROC_RT.SESSION_LOG_V1('" .. CONFD_CONNECTION .. "', "
        .. sql_quote(params_json) .. ", " .. session_id_expr
        .. ", CURRENT_TIMESTAMP) FROM (SELECT 1)"
end

-- Append the 5 cron fields from a crontab string, if exactly 5 are present.
local function add_cron(parts, cron)
    if not cron then
        return
    end
    local fields = {}
    for word in cron:gmatch("%S+") do
        fields[#fields + 1] = word
    end
    if #fields == 5 then
        local names = { "minute", "hour", "day", "month", "weekday" }
        for k = 1, 5 do
            parts[#parts + 1] = json_str(names[k], fields[k])
        end
    end
end

-- A bare integer level token, or "0" (full backup) as the default.
local function level_or_default(level)
    if level and level:match("^%d+$") then
        return '"level":' .. level
    end
    return '"level":0'
end

-- Index of the first token equal (case-insensitively) to kw at/after `from`.
local function index_of(t, kw, from)
    for j = from, #t do
        if U(t[j]) == kw then
            return j
        end
    end
    return nil
end

-- "key":[ "a","b",… ] from a Lua list of string values.
local function json_str_array(key, list)
    local items = {}
    for _, v in ipairs(list) do
        items[#items + 1] = '"' .. json_escape(v) .. '"'
    end
    return '"' .. key .. '":[' .. table.concat(items, ",") .. "]"
end

-- Consume a comma-separated run of quoted literals starting at index i. Returns
-- the collected values and the index of the first non-list token.
local function collect_literal_list(t, i, literals)
    local items = {}
    while i <= #t do
        local value = as_literal(t[i], literals)
        if value ~= nil then
            items[#items + 1] = value
            i = i + 1
            if i <= #t and t[i] == "," then
                i = i + 1
            end
        else
            break
        end
    end
    return items, i
end

-- Append value to list only if not already present (order-preserving dedupe).
local function append_unique(list, value)
    for _, v in ipairs(list) do
        if v == value then
            return
        end
    end
    list[#list + 1] = value
end

-- --- per-command parsers (each returns the emit string, or nil to decline) ---

-- START BACKUP TO VOLUME <vol> [WITH LEVEL <n>] [AND EXPIRATION '<t>']
local function parse_start(t, i, literals)
    local volume, level, expire
    while i <= #t do
        local u = U(t[i])
        if u == "VOLUME" and t[i + 1] then
            volume = resolve(t[i + 1], literals)
            i = i + 2
        elseif u == "LEVEL" and t[i + 1] then
            level = resolve(t[i + 1], literals)
            i = i + 2
        elseif u == "EXPIRATION" and t[i + 1] then
            expire = as_literal(t[i + 1], literals)
            i = i + 2
        else
            i = i + 1
        end
    end
    local parts = {}
    if volume then
        parts[#parts + 1] = json_str("backup_volume_name", volume)
    end
    parts[#parts + 1] = level_or_default(level)
    if expire then
        parts[#parts + 1] = json_str("expire", expire)
    end
    return emit("db_backup_start", db_params(parts))
end

-- DELETE BACKUP '<id>' [, '<id>' …]  (each id is a quoted literal)
local function parse_delete_backups(t, i, literals)
    local ids = {}
    while i <= #t do
        local value = as_literal(t[i], literals)
        if value ~= nil then
            ids[#ids + 1] = '"' .. json_escape(value) .. '"'
        end
        i = i + 1
    end
    if #ids == 0 then
        return nil
    end
    local parts = { '"backup_list":[' .. table.concat(ids, ",") .. "]" }
    return emit("db_backups_delete", db_params(parts))
end

-- ADD BACKUP SCHEDULE '<name>' TO VOLUME <vol> [WITH LEVEL <n>] [AT '<cron>']
--     [AND EXPIRATION '<t>'] [ENABLED|DISABLED]
local function parse_add_schedule(t, i, literals)
    local name = as_literal(t[i], literals)
    if not name then
        return nil
    end
    i = i + 1
    local volume, level, cron, expire, enabled
    while i <= #t do
        local u = U(t[i])
        if u == "VOLUME" and t[i + 1] then
            volume = resolve(t[i + 1], literals)
            i = i + 2
        elseif u == "LEVEL" and t[i + 1] then
            level = resolve(t[i + 1], literals)
            i = i + 2
        elseif u == "AT" and t[i + 1] then
            cron = as_literal(t[i + 1], literals)
            i = i + 2
        elseif u == "EXPIRATION" and t[i + 1] then
            expire = as_literal(t[i + 1], literals)
            i = i + 2
        elseif u == "ENABLED" then
            enabled = true
            i = i + 1
        elseif u == "DISABLED" then
            enabled = false
            i = i + 1
        else
            i = i + 1
        end
    end
    local parts = { json_str("backup_name", name) }
    if volume then
        parts[#parts + 1] = json_str("backup_volume_name", volume)
    end
    parts[#parts + 1] = level_or_default(level)
    add_cron(parts, cron)
    if expire then
        parts[#parts + 1] = json_str("expire", expire)
    end
    if enabled ~= nil then
        parts[#parts + 1] = '"enabled":' .. tostring(enabled)
    end
    return emit("db_backup_add_schedule", db_params(parts))
end

-- MODIFY BACKUP SCHEDULE '<name>' [AT '<cron>'] [WITH EXPIRATION '<t>']
--     [ENABLED|DISABLED]
local function parse_modify_schedule(t, i, literals)
    local name = as_literal(t[i], literals)
    if not name then
        return nil
    end
    i = i + 1
    local cron, expire, enabled
    while i <= #t do
        local u = U(t[i])
        if u == "AT" and t[i + 1] then
            cron = as_literal(t[i + 1], literals)
            i = i + 2
        elseif u == "EXPIRATION" and t[i + 1] then
            expire = as_literal(t[i + 1], literals)
            i = i + 2
        elseif u == "ENABLED" then
            enabled = true
            i = i + 1
        elseif u == "DISABLED" then
            enabled = false
            i = i + 1
        else
            i = i + 1
        end
    end
    local parts = { json_str("backup_name", name) }
    add_cron(parts, cron)
    if expire then
        parts[#parts + 1] = json_str("expire", expire)
    end
    if enabled ~= nil then
        parts[#parts + 1] = '"enabled":' .. tostring(enabled)
    end
    return emit("db_backup_modify_schedule", db_params(parts))
end

-- MODIFY BACKUP EXPIRATION ON VOLUME <vol> FOR '<files>' TO '<time>'
-- NOTE: db_backup_change_expiration is NOT db-scoped — no db_name marker.
local function parse_change_expiration(t, i, literals)
    local volume, files, etime
    while i <= #t do
        local u = U(t[i])
        if u == "VOLUME" and t[i + 1] then
            volume = resolve(t[i + 1], literals)
            i = i + 2
        elseif u == "FOR" and t[i + 1] then
            files = as_literal(t[i + 1], literals)
            i = i + 2
        elseif u == "TO" and t[i + 1] then
            etime = as_literal(t[i + 1], literals)
            i = i + 2
        else
            i = i + 1
        end
    end
    if not (volume and files and etime) then
        return nil
    end
    local parts = {
        json_str("backup_volume_name", volume),
        json_str("backup_files", files),
        json_str("expire_time", etime),
    }
    return emit("db_backup_change_expiration", build_json(parts))
end

-- Emit a EXECUTE SCRIPT call targeting PREPROC.ADMIN_VIRTUAL_RESTORE_V1.
local function emit_virtual_restore(action, params_json)
    return "EXECUTE SCRIPT PREPROC.ADMIN_VIRTUAL_RESTORE_V1('"
        .. action .. "', " .. sql_quote(params_json) .. ")"
end

-- START VIRTUAL RESTORE FROM BACKUP '<backup_id>'
--     FOR SCHEMA 'S1' [, 'S2' …]
--     USING CONNECTION <jdbc_conn> [AND EXA CONNECTION <exa_conn>]
--     [AS <vdb_name>] [WITH PORT <n>]
--     [AND MEM SIZE '<sz>'] [AND VOLUME SIZE '<sz>']
--     [AND ADAPTER JAR '<path>'] [AND TIMEOUT <secs>]
--
-- Required: backup_id (quoted literal), ≥1 schema (quoted literals), jdbc
-- connection (bare identifier). Absent required fields → nil (fail-open).
-- Optional fields default: vdb_name VR1, port 9563, mem_size '4 GiB',
-- volume_size '20 GiB', timeout 600. exa_connection and adapter_jar are omitted
-- from the JSON when not supplied.
local function parse_start_virtual_restore(t, i, literals)
    local backup_id, schemas, jdbc_conn, exa_conn
    local vdb_name, port, mem_size, volume_size, adapter_jar, timeout

    while i <= #t do
        local u = U(t[i])
        local u2 = U(t[i + 1])

        if u == "FROM" and u2 == "BACKUP" and t[i + 2] then
            -- FROM BACKUP '<backup_id>'
            backup_id = as_literal(t[i + 2], literals)
            i = i + 3
        elseif u == "FOR" and u2 == "SCHEMA" then
            -- FOR SCHEMA 'S1' [, 'S2' …] — consume as many quoted literals as appear
            schemas = {}
            i = i + 2
            while i <= #t do
                local v = as_literal(t[i], literals)
                if v ~= nil then
                    schemas[#schemas + 1] = v
                    i = i + 1
                    -- skip a trailing comma token
                    if i <= #t and t[i] == "," then
                        i = i + 1
                    end
                else
                    break
                end
            end
        elseif u == "USING" and u2 == "CONNECTION" and t[i + 2] then
            -- USING CONNECTION <jdbc_conn>  (bare identifier, not a literal)
            -- Must not be mistaken for AND EXA CONNECTION
            jdbc_conn = resolve(t[i + 2], literals)
            i = i + 3
        elseif u == "AND" and u2 == "EXA" and U(t[i + 2]) == "CONNECTION" and t[i + 3] then
            exa_conn = resolve(t[i + 3], literals)
            i = i + 4
        elseif u == "AND" and u2 == "MEM" and U(t[i + 2]) == "SIZE" and t[i + 3] then
            mem_size = as_literal(t[i + 3], literals)
            i = i + 4
        elseif u == "AND" and u2 == "VOLUME" and U(t[i + 2]) == "SIZE" and t[i + 3] then
            volume_size = as_literal(t[i + 3], literals)
            i = i + 4
        elseif u == "AND" and u2 == "ADAPTER" and U(t[i + 2]) == "JAR" and t[i + 3] then
            adapter_jar = as_literal(t[i + 3], literals)
            i = i + 4
        elseif u == "AND" and u2 == "TIMEOUT" and t[i + 2] then
            timeout = t[i + 2]
            i = i + 3
        elseif u == "AS" and t[i + 1] then
            -- AS <vdb_name>  (bare identifier)
            vdb_name = resolve(t[i + 1], literals)
            i = i + 2
        elseif u == "WITH" and u2 == "PORT" and t[i + 2] then
            port = t[i + 2]
            i = i + 3
        else
            i = i + 1
        end
    end

    -- Required fields — decline if any are absent.
    if not backup_id then
        return nil
    end
    if not schemas or #schemas == 0 then
        return nil
    end
    if not jdbc_conn then
        return nil
    end

    -- Apply defaults for optional fields.
    if not vdb_name then
        vdb_name = "VR1"
    end
    if not port then
        port = "9563"
    end
    if not mem_size then
        mem_size = "4 GiB"
    end
    if not volume_size then
        volume_size = "20 GiB"
    end
    if not timeout then
        timeout = "600"
    end

    -- Build JSON. Keys in spec-mandated order; omit optional keys when absent.
    local schema_items = {}
    for _, s in ipairs(schemas) do
        schema_items[#schema_items + 1] = '"' .. json_escape(s) .. '"'
    end
    local parts = {
        json_str("vdb_name", vdb_name),
        json_str("backup_id", backup_id),
        '"schemas":[' .. table.concat(schema_items, ",") .. "]",
        json_str("jdbc_connection", jdbc_conn),
    }
    if exa_conn then
        parts[#parts + 1] = json_str("exa_connection", exa_conn)
    end
    -- port and timeout are integers in JSON (no quotes)
    parts[#parts + 1] = '"port":' .. port
    parts[#parts + 1] = json_str("mem_size", mem_size)
    parts[#parts + 1] = json_str("volume_size", volume_size)
    if adapter_jar then
        parts[#parts + 1] = json_str("adapter_jar", adapter_jar)
    end
    parts[#parts + 1] = '"timeout":' .. timeout

    return emit_virtual_restore("start", build_json(parts))
end

-- SHOW VIRTUAL RESTORE [<vdb_name>]
-- Rewrites to the inline-capable read SELECT over CONFD_QUERY_V1 ('db_state') with
-- the explicit vdb_name (default VR1). Does NOT use the empty-string inference
-- marker — that would resolve to the issuing DB.
local function parse_show_virtual_restore(t, i, literals)
    local vdb_name = "VR1"
    -- An optional bare identifier may follow; if present, use it.
    if i <= #t then
        local candidate = resolve(t[i], literals)
        -- Accept any non-keyword token as the vdb name; it is a bare identifier.
        if candidate and candidate ~= "" then
            vdb_name = candidate
        end
    end
    local params = build_json({ json_str("db_name", vdb_name) })
    return emit_query("db_state", params)
end

-- STOP VIRTUAL RESTORE [<vdb_name>]
-- Rewrites to EXECUTE SCRIPT PREPROC.ADMIN_VIRTUAL_RESTORE_V1('stop', …) with
-- the explicit vdb_name (default VR1).
local function parse_stop_virtual_restore(t, i, literals)
    local vdb_name = "VR1"
    if i <= #t then
        local candidate = resolve(t[i], literals)
        if candidate and candidate ~= "" then
            vdb_name = candidate
        end
    end
    local params = build_json({ json_str("vdb_name", vdb_name) })
    return emit_virtual_restore("stop", params)
end

-- --- license verbs ----------------------------------------------------------

-- INSTALL LICENSE FROM { '<url>' | CONTENT '<blob>'
--     | BUCKETFS FILE '<path>' IN BUCKET '<b>' [IN SERVICE '<s>'] }
-- Emits ADMIN_LICENSE_V1('install', <json>) with a `mode` discriminator. Declines
-- (nil) any incomplete form; rejects a URL carrying inline user:pass@ creds so the
-- secret never reaches the rewrite. Service defaults to bfsdefault.
local function parse_install_license(t, i, literals)
    if U(t[i]) ~= "FROM" then
        return nil
    end
    i = i + 1
    local kind = U(t[i])
    if kind == "CONTENT" then
        local blob = as_literal(t[i + 1], literals)
        if not blob then
            return nil
        end
        local parts = {
            json_str("mode", "content"),
            json_str("license", blob),
        }
        return emit_license("install", build_json(parts))
    elseif kind == "BUCKETFS" then
        if U(t[i + 1]) ~= "FILE" then
            return nil
        end
        local path = as_literal(t[i + 2], literals)
        if not path then
            return nil
        end
        local bi = index_of(t, "BUCKET", i + 3)
        if not bi then
            return nil
        end
        local bucket = as_literal(t[bi + 1], literals)
        if not bucket then
            return nil
        end
        local service = "bfsdefault"
        local si = index_of(t, "SERVICE", bi + 2)
        if si then
            local s = as_literal(t[si + 1], literals)
            if s then
                service = s
            end
        end
        local parts = {
            json_str("mode", "bucketfs"),
            json_str("path", path),
            json_str("bucket", bucket),
            json_str("service", service),
        }
        return emit_license("install", build_json(parts))
    else
        local url = as_literal(t[i], literals)
        if not url then
            return nil
        end
        -- No-secrets-in-SQL: decline a URL with inline user:pass@host credentials.
        if url:find("://[^@]*:[^@]*@") then
            return nil
        end
        local parts = {
            json_str("mode", "url"),
            json_str("source_url", url),
        }
        return emit_license("install", build_json(parts))
    end
end

-- --- log-events verb --------------------------------------------------------

-- SHOW LOG EVENTS FOR SERVICE '<s>' [, …] [SINCE '<ts>'] [UNTIL '<ts>']
--     [WITH LEVEL '<lvl>'] [ON NODE '<n>' [, …]] [FOR DATABASE '<db>' [, …]]
--     [WITHIN '<iv>'] [TAG '<t>']
-- FOR SERVICE is MANDATORY (log_collect rejects a call with no services), so the
-- module declines when it is absent. Emits the LOG_EVENTS_V1 read SELECT; no db_name.
local function parse_show_log_events(t, i, literals)
    local services, nodes, dbs
    local start_time, stop_time, error_level, interval, tag
    while i <= #t do
        local u = U(t[i])
        local u2 = U(t[i + 1])
        if u == "FOR" and u2 == "SERVICE" then
            services, i = collect_literal_list(t, i + 2, literals)
        elseif u == "FOR" and u2 == "DATABASE" then
            dbs, i = collect_literal_list(t, i + 2, literals)
        elseif u == "SINCE" and t[i + 1] then
            start_time = as_literal(t[i + 1], literals)
            i = i + 2
        elseif u == "UNTIL" and t[i + 1] then
            stop_time = as_literal(t[i + 1], literals)
            i = i + 2
        elseif u == "WITH" and u2 == "LEVEL" and t[i + 2] then
            error_level = as_literal(t[i + 2], literals)
            i = i + 3
        elseif u == "ON" and u2 == "NODE" then
            nodes, i = collect_literal_list(t, i + 2, literals)
        elseif u == "WITHIN" and t[i + 1] then
            interval = as_literal(t[i + 1], literals)
            i = i + 2
        elseif u == "TAG" and t[i + 1] then
            tag = as_literal(t[i + 1], literals)
            i = i + 2
        else
            i = i + 1
        end
    end
    if not services or #services == 0 then
        return nil
    end
    local parts = { json_str_array("services", services) }
    if start_time then
        parts[#parts + 1] = json_str("start_time", start_time)
    end
    if stop_time then
        parts[#parts + 1] = json_str("stop_time", stop_time)
    end
    if error_level then
        parts[#parts + 1] = json_str("error_level", error_level)
    end
    if nodes and #nodes > 0 then
        parts[#parts + 1] = json_str_array("nodes", nodes)
    end
    if dbs and #dbs > 0 then
        parts[#parts + 1] = json_str_array("dbs", dbs)
    end
    if interval then
        parts[#parts + 1] = json_str("default_interval", interval)
    end
    if tag then
        parts[#parts + 1] = json_str("tag", tag)
    end
    return emit_log_events(build_json(parts))
end

-- --- debug-collect verb -----------------------------------------------------

-- Whitelisted INCLUDING categories → their ConfD debug_collect entries. ConfD
-- silently ignores unknown categories, so the whitelist MUST live here: an
-- unrecognised category declines the whole statement (fail-open → syntax error).
-- SERVER/SQL BACKTRACES both map to ConfD's single combined backtrace entry.
local DEBUG_CATEGORIES = {
    ["CLUSTER LOGS"] = { kind = "debug_info", value = "EXAClusterOS logs" },
    ["STORAGE METADATA"] = { kind = "debug_info", value = "EXAStorage metadata" },
    ["COREDUMPS"] = { kind = "debug_info", value = "Coredumps" },
    ["SERVER BACKTRACES"] = { kind = "backtraces", value = "EXASolution server/SQL processes" },
    ["SQL BACKTRACES"] = { kind = "backtraces", value = "EXASolution server/SQL processes" },
    ["DATABASE LOGS"] = { kind = "exasolution_logs" },
}

-- Keywords that terminate the INCLUDING category run (start of an optional clause).
local DEBUG_CLAUSE_KEYWORDS = {
    SINCE = true, UNTIL = true, ON = true, FOR = true, WITH = true, TO = true,
}

local DEFAULT_DEBUG_TIMEOUT = "300"

-- COLLECT DEBUG INFO INCLUDING <cat> [, …] [SINCE '<d>'] [UNTIL '<d>']
--     [ON NODE '<id>' [, …]] [FOR DATABASE '<name>' [, …]] [WITH TIMEOUT <secs>]
--     [TO REMOTE VOLUME <vol> AT '<path>']
-- INCLUDING is MANDATORY and its categories are whitelisted (ConfD would accept a
-- bare/mistyped call and dump anyway); the default timeout is bounded to 300 s
-- (NOT ConfD's 1800). Thin debug_collect passthrough; no db_name.
local function parse_collect_debug_info(t, i, literals)
    if U(t[i]) ~= "INCLUDING" then
        return nil
    end
    i = i + 1

    local debug_info, backtraces = {}, {}
    local want_db_logs = false
    local words = {}
    local function flush_category()
        if #words == 0 then
            return true
        end
        local key = table.concat(words, " ")
        words = {}
        local cat = DEBUG_CATEGORIES[key]
        if not cat then
            return false
        end
        if cat.kind == "debug_info" then
            append_unique(debug_info, cat.value)
        elseif cat.kind == "backtraces" then
            append_unique(backtraces, cat.value)
        else
            want_db_logs = true
        end
        return true
    end

    while i <= #t do
        local u = U(t[i])
        if DEBUG_CLAUSE_KEYWORDS[u] then
            break
        end
        if t[i] == "," then
            if not flush_category() then
                return nil
            end
        else
            words[#words + 1] = u
        end
        i = i + 1
    end
    if not flush_category() then
        return nil
    end
    if #debug_info == 0 and #backtraces == 0 and not want_db_logs then
        return nil
    end

    local start_date, end_date, nodes, dbs, timeout, out_vol, out_path
    while i <= #t do
        local u = U(t[i])
        local u2 = U(t[i + 1])
        if u == "SINCE" and t[i + 1] then
            start_date = as_literal(t[i + 1], literals)
            i = i + 2
        elseif u == "UNTIL" and t[i + 1] then
            end_date = as_literal(t[i + 1], literals)
            i = i + 2
        elseif u == "ON" and u2 == "NODE" then
            nodes, i = collect_literal_list(t, i + 2, literals)
        elseif u == "FOR" and u2 == "DATABASE" then
            dbs, i = collect_literal_list(t, i + 2, literals)
        elseif u == "WITH" and u2 == "TIMEOUT" and t[i + 2] then
            timeout = t[i + 2]
            i = i + 3
        elseif u == "TO" and u2 == "REMOTE" and U(t[i + 2]) == "VOLUME" and t[i + 3] then
            out_vol = resolve(t[i + 3], literals)
            local ai = index_of(t, "AT", i + 4)
            if ai then
                out_path = as_literal(t[ai + 1], literals)
            end
            i = i + 4
        else
            i = i + 1
        end
    end

    local parts = {}
    if #debug_info > 0 then
        parts[#parts + 1] = json_str_array("debug_info", debug_info)
    end
    if #backtraces > 0 then
        parts[#parts + 1] = json_str_array("backtraces", backtraces)
    end
    if want_db_logs or (dbs and #dbs > 0) then
        parts[#parts + 1] = json_str_array("exasolution_logs", dbs or {})
    end
    if start_date then
        parts[#parts + 1] = json_str("start_date", start_date)
    end
    if end_date then
        parts[#parts + 1] = json_str("end_date", end_date)
    end
    if nodes and #nodes > 0 then
        parts[#parts + 1] = json_str_array("nodes", nodes)
    end
    if timeout and timeout:match("^%d+$") then
        parts[#parts + 1] = '"timeout":' .. timeout
    else
        parts[#parts + 1] = '"timeout":' .. DEFAULT_DEBUG_TIMEOUT
    end
    if out_vol and out_path then
        parts[#parts + 1] = json_str("outfile", "remote:" .. out_vol .. "," .. out_path)
    end
    return emit("debug_collect", build_json(parts))
end

-- --- session-log verb -------------------------------------------------------

-- Collect a comma-separated run of BARE non-negative integer tokens from index i.
-- Node numbers are bare tokens (not quoted literals), so collect_literal_list
-- cannot be reused. Returns the list of integer strings and an ok flag; ok is
-- false when no integer is present or a comma is not followed by another integer,
-- so the caller declines (fail-open).
local function collect_int_list(t, i)
    local items = {}
    while true do
        local tok = t[i]
        if not tok or not tok:match("^%d+$") then
            return items, false
        end
        items[#items + 1] = tok
        i = i + 1
        if t[i] == "," then
            i = i + 1
        else
            return items, true
        end
    end
end

-- SHOW SESSION LOG FOR { CURRENT_SESSION | SESSION '<id>' }
--     [ ON NODE <n> | ON NODES <n> [, <n> …] | ON ALL NODES ]
--     [USING BUCKET '<bucket>' IN SERVICE '<service>']
-- FOR is MANDATORY. The session id is emitted as a caller-evaluated SQL ARGUMENT,
-- never inside the params JSON: FOR CURRENT_SESSION emits the un-quoted expression
-- TO_CHAR(CURRENT_SESSION) (the caller's SQL engine resolves it — a worker UDF
-- cannot see the caller's session), and FOR SESSION '<id>' emits the numeric id as
-- a single-quoted SQL literal. A non-numeric explicit id is declined here
-- (re-validated in the UDF as defence in depth against member/path injection).
-- The two optional clauses are order-independent. ON emits either a nodes array of
-- numeric strings (logical node numbers, bare non-negative integers) or the
-- all_nodes marker; absent, both are omitted and the UDF defaults to node 0. An
-- invalid node number declines (nil, fail-open) so the engine raises a normal
-- syntax error. There is NO INTO TABLE clause: persisting the log is now ordinary
-- INSERT INTO t SELECT * FROM (CONTROL DATABASE SHOW SESSION LOG …). With no USING
-- BUCKET the bucket key is omitted and the UDF self-manages an ephemeral PRIVATE
-- bucket; service defaults to bfsdefault.
local function parse_show_session_log(t, i, literals)
    if U(t[i]) ~= "FOR" then
        return nil
    end
    i = i + 1
    local selector = U(t[i])
    local session_id_expr
    if selector == "CURRENT_SESSION" then
        session_id_expr = "TO_CHAR(CURRENT_SESSION)"
        i = i + 1
    elseif selector == "SESSION" then
        local id = as_literal(t[i + 1], literals)
        if not id or not id:match("^%d+$") then
            return nil
        end
        session_id_expr = sql_quote(id)
        i = i + 2
    else
        return nil
    end
    -- No USING BUCKET => omit the bucket key entirely: the UDF then creates and
    -- deletes its own ephemeral PRIVATE bucket (the caller provisions nothing).
    -- A supplied bucket targets a caller-owned pre-existing bucket instead.
    local bucket = nil
    local service = "bfsdefault"
    local bi = index_of(t, "BUCKET", i)
    if bi then
        local b = as_literal(t[bi + 1], literals)
        if b then
            bucket = b
        end
        local si = index_of(t, "SERVICE", bi + 2)
        if si then
            local s = as_literal(t[si + 1], literals)
            if s then
                service = s
            end
        end
    end
    -- Optional ON NODE(S) / ON ALL NODES clause (order-independent). Logical node
    -- numbers are BARE non-negative integers, not quoted literals; ON present but
    -- malformed declines (fail-open) so the engine raises a normal syntax error.
    local nodes = nil
    local all_nodes = false
    local oi = index_of(t, "ON", i)
    if oi then
        if U(t[oi + 1]) == "ALL" and U(t[oi + 2]) == "NODES" then
            all_nodes = true
        elseif U(t[oi + 1]) == "NODE" or U(t[oi + 1]) == "NODES" then
            local list, ok = collect_int_list(t, oi + 2)
            if not ok then
                return nil
            end
            nodes = list
        else
            return nil
        end
    end
    local parts = {}
    if all_nodes then
        parts[#parts + 1] = '"all_nodes":true'
    elseif nodes then
        parts[#parts + 1] = json_str_array("nodes", nodes)
    end
    if bucket then
        parts[#parts + 1] = json_str("bucket", bucket)
    end
    parts[#parts + 1] = json_str("service", service)
    return emit_session_log_query(build_json(parts), session_id_expr)
end

-- dispatch(rest) maps the text following `CONTROL DATABASE` to a single rewrite
-- string, or nil to decline (fail-open). It owns the literal extraction, the
-- whitespace tokenisation, and the whole verb/object keyword chain, so the
-- standalone path and the embedded splicer produce the SAME rewrite for a given
-- command wherever it appears. A read yields a bare, embeddable SELECT (prefix
-- `SELECT`); an action yields an `EXECUTE SCRIPT` statement. dispatch is agnostic
-- to that distinction — the caller discriminates on the prefix.
local function dispatch(rest)
    local literals
    rest, literals = extract_literals(rest)
    local t = tokenize(rest)
    if #t == 0 then
        return nil
    end

    local v1 = U(t[1])
    local v2 = U(t[2])

    if v1 == "SHOW" then
        if v2 == "INFO" and #t == 2 then
            -- SHOW INFO routes to the inline-capable UDF path (a bare SELECT)
            -- instead of EXECUTE SCRIPT ADMIN_CONFD_JOB_V1.
            return emit_query("db_info", db_params({}))
        elseif v2 == "BACKUPS" and #t == 2 then
            return emit_query("db_backup_list", db_params({}))
        elseif v2 == "BACKUP" and U(t[3]) == "PROGRESS" and #t == 3 then
            return emit_query("db_backup_progress", db_params({}))
        elseif v2 == "VIRTUAL" and U(t[3]) == "RESTORE" then
            return parse_show_virtual_restore(t, 4, literals)
        elseif v2 == "LICENSE" and #t == 2 then
            return emit_query("license_info", build_json({}))
        elseif v2 == "LICENSE" and U(t[3]) == "FILE" and #t == 3 then
            return emit_query("license_download", build_json({}))
        elseif v2 == "LOG" and U(t[3]) == "EVENTS" then
            return parse_show_log_events(t, 4, literals)
        elseif v2 == "SESSION" and U(t[3]) == "LOG" then
            return parse_show_session_log(t, 4, literals)
        end
        return nil
    end

    if v1 == "START" then
        if v2 == "BACKUP" then
            return parse_start(t, 3, literals)
        elseif v2 == "VIRTUAL" and U(t[3]) == "RESTORE" then
            return parse_start_virtual_restore(t, 4, literals)
        end
        return nil
    end

    if v1 == "STOP" and v2 == "VIRTUAL" and U(t[3]) == "RESTORE" then
        return parse_stop_virtual_restore(t, 4, literals)
    end

    if v1 == "ABORT" and v2 == "BACKUP" and #t == 2 then
        return emit("db_backup_abort", db_params({}))
    end

    if v1 == "DELETE" then
        if v2 == "UNUSABLE" and U(t[3]) == "BACKUPS" and #t == 3 then
            return emit("db_backup_delete_unusable", db_params({}))
        elseif v2 == "BACKUP" then
            return parse_delete_backups(t, 3, literals)
        end
        return nil
    end

    if v1 == "ADD" and v2 == "BACKUP" and U(t[3]) == "SCHEDULE" then
        return parse_add_schedule(t, 4, literals)
    end

    if v1 == "MODIFY" and v2 == "BACKUP" then
        if U(t[3]) == "SCHEDULE" then
            return parse_modify_schedule(t, 4, literals)
        elseif U(t[3]) == "EXPIRATION" then
            return parse_change_expiration(t, 4, literals)
        end
        return nil
    end

    if v1 == "CHECK" and v2 == "LICENSE" and #t == 2 then
        return emit_query("license_run_check", build_json({}))
    end

    if v1 == "INSTALL" and v2 == "LICENSE" then
        return parse_install_license(t, 3, literals)
    end

    if v1 == "COLLECT" and v2 == "DEBUG" and U(t[3]) == "INFO" then
        return parse_collect_debug_info(t, 4, literals)
    end

    -- The remote-volume verbs (SHOW/ADD/DROP REMOTE VOLUME…) are NOT handled here:
    -- they live in CONTROL_STORAGE_V1, where a remote volume belongs. They fall
    -- through and decline, so `CONTROL DATABASE … REMOTE VOLUME …` reaches the
    -- engine unrewritten and raises an ordinary syntax error. (`COLLECT DEBUG INFO
    -- … TO REMOTE VOLUME <vol>` above is a debug_collect destination clause, not a
    -- remote-volume command, and stays.)
    return nil
end

-- A dispatch result is embeddable only when it is a read: a table expression
-- beginning with SELECT. An action (EXECUTE SCRIPT …) or a decline (nil) is not.
local function is_read(rewrite)
    return type(rewrite) == "string" and rewrite:sub(1, 6) == "SELECT"
end

-- The opener of an embedded group: a `(`, optional whitespace, `CONTROL
-- DATABASE`, and the whitespace ending the keyword — matched case-insensitively
-- and anchored at the candidate `(`.
local GROUP_OPEN = "%(%s*[Cc][Oo][Nn][Tt][Rr][Oo][Ll]%s+"
    .. "[Dd][Aa][Tt][Aa][Bb][Aa][Ss][Ee]%s+"

-- Find the next top-level `(CONTROL DATABASE ` opener at/after `from`, tracking
-- single-quote literal state (a `''` run stays inside the literal) so an opener
-- that falls inside the OUTER statement's own quoted string is never matched.
-- Returns the index of the `(` and the index of the last matched (whitespace)
-- char — the inner command begins at the next index — or nil when none remains.
local function find_group_open(text, from)
    local i, n = from, #text
    local in_literal = false
    while i <= n do
        local c = text:sub(i, i)
        if in_literal then
            if c == "'" then
                if text:sub(i + 1, i + 1) == "'" then
                    i = i + 1
                else
                    in_literal = false
                end
            end
        elseif c == "'" then
            in_literal = true
        elseif c == "(" then
            local open_index, prefix_end = text:find("^" .. GROUP_OPEN, i)
            if open_index then
                return open_index, prefix_end
            end
        end
        i = i + 1
    end
    return nil
end

-- Walk from the opening `(` at `open_index` to its matching `)`, tracking
-- single-quote literal state (a `''` run stays inside the literal) and paren
-- depth, so a `)` inside a quoted literal (e.g. a volume name 'a)b') never closes
-- the group. Returns the index of the matching `)`, or nil when the parentheses
-- are unbalanced.
local function find_matching_close(text, open_index)
    local depth, in_literal = 0, false
    local i, n = open_index, #text
    while i <= n do
        local c = text:sub(i, i)
        if in_literal then
            if c == "'" then
                if text:sub(i + 1, i + 1) == "'" then
                    i = i + 1
                else
                    in_literal = false
                end
            end
        elseif c == "'" then
            in_literal = true
        elseif c == "(" then
            depth = depth + 1
        elseif c == ")" then
            depth = depth - 1
            if depth == 0 then
                return i
            end
        end
        i = i + 1
    end
    return nil
end

-- Rewrite CONTROL DATABASE read commands embedded inside a larger statement. Each
-- parenthesised `(CONTROL DATABASE <read>)` group is replaced in place by the
-- equivalent re-parenthesised UDF SELECT, so e.g.
--   INSERT INTO t SELECT * FROM (CONTROL DATABASE SHOW INFO)
-- becomes
--   INSERT INTO t SELECT * FROM (SELECT PREPROC_RT.CONFD_QUERY_V1(…) FROM (SELECT 1))
-- while the surrounding SQL — including the outer statement's own quoted string
-- literals — is preserved byte-for-byte. The inner command is routed through the
-- SAME dispatch as the standalone path, receiving the RAW inner text so dispatch
-- does its own literal extraction on the fragment alone (never on the whole
-- Any number of groups in one statement are spliced, but they must all be
-- CONTROL DATABASE groups: the framework's EXPAND phase is first-match-terminal,
-- so once this module accepts, no other module runs and a mixed-domain statement
-- (e.g. also embedding a CONTROL STORAGE read) would reach the engine with that
-- other domain's text still raw.
-- statement). Only a read (a SELECT) is splice-able: an embedded action (EXECUTE
-- SCRIPT), an unrecognised command, or unbalanced parentheses declines the WHOLE
-- statement (nil, fail-open) so the engine raises a normal error rather than
-- seeing invalid SQL. With no embedded group at all, declines (nil). Never raises.
local function expand_inline(sqltext)
    local parts = {}
    local pos = 1
    local spliced = false
    while true do
        local open_index, prefix_end = find_group_open(sqltext, pos)
        if not open_index then
            break
        end
        local close_index = find_matching_close(sqltext, open_index)
        if not close_index then
            return nil
        end
        local inner = sqltext:sub(prefix_end + 1, close_index - 1)
        local rewrite = dispatch(inner)
        if not is_read(rewrite) then
            return nil
        end
        parts[#parts + 1] = sqltext:sub(pos, open_index - 1)
        parts[#parts + 1] = "(" .. rewrite .. ")"
        pos = close_index + 1
        spliced = true
    end
    if not spliced then
        return nil
    end
    parts[#parts + 1] = sqltext:sub(pos)
    return table.concat(parts)
end

-- control_database_expand(sqltext) -> a single rewrite for a recognised CONTROL
-- DATABASE command (standalone), the larger statement with an embedded read spliced
-- in, or nil to decline (fail-open). Never raises.
function control_database_expand(sqltext)
    if type(sqltext) ~= "string" then
        return nil
    end

    local trimmed = sqltext:gsub("^%s*(.-)%s*$", "%1")
    local without_semicolon = trimmed:gsub(";%s*$", "")
    local clean = without_semicolon:gsub("^%s*(.-)%s*$", "%1")

    local rest = clean:match(
        "^[Cc][Oo][Nn][Tt][Rr][Oo][Ll]%s+[Dd][Aa][Tt][Aa][Bb][Aa][Ss][Ee]%s+(.*)$"
    )
    if not rest then
        -- Not a standalone CONTROL DATABASE statement. Try to splice a read
        -- command embedded (in parentheses) inside a larger statement. The read
        -- target is a UDF subquery (an expression), so it slots in wherever a
        -- table is expected — the whole point of dropping the Lua layer for reads.
        return expand_inline(sqltext)
    end

    return dispatch(rest)
end
end

-- ----- sql/control_bucketfs_v1.lua: fenced verbatim, so its locals stay private -----
do
-- =============================================================================
-- CONTROL_BUCKETFS_V1  (assembled into PREPROC_RT.CONFD_CONTROL_V1, not deployed alone)  — EXPAND-phase grammar
-- =============================================================================
-- The curated SQL surface for ConfD-backed BucketFS administration. It parses
-- the `CONTROL BUCKETFS <verb> <object> …` grammar and rewrites each recognised
-- command into one `EXECUTE SCRIPT PREPROC.ADMIN_CONFD_JOB_V1(job, params)` call.
--
--   CONTROL BUCKETFS SHOW SERVICES                                      -> bucketfs_list
--   CONTROL BUCKETFS SHOW SERVICE '<name>'                              -> bucketfs_info
--   CONTROL BUCKETFS DELETE SERVICE '<name>'                            -> bucketfs_delete
--   CONTROL BUCKETFS ADD SERVICE '<name>' WITH <options>                -> bucketfs_add
--   CONTROL BUCKETFS MODIFY SERVICE '<name>' WITH <options>             -> bucketfs_modify
--   CONTROL BUCKETFS ADD BUCKET '<bucket>' TO SERVICE '<svc>'
--       [PUBLIC|PRIVATE] [WITH <options>]                               -> bucket_add
--   CONTROL BUCKETFS MODIFY BUCKET '<bucket>' IN SERVICE '<svc>'
--       [PUBLIC|PRIVATE] [WITH <options>]                               -> bucket_modify
--   CONTROL BUCKETFS DELETE BUCKET '<bucket>' FROM SERVICE '<svc>'      -> bucket_delete
--
-- Options (the `WITH key = value [, …]` tail) map 1:1 to the documented ConfD
-- parameter names, so they are self-documenting against the ConfD job pages:
--   service:  http_port, https_port, owner ('user group'), sync_period,
--             sync_key, path, mode, bucketvolume
--   bucket:   read_password, write_password
-- Ports and sync_period are emitted as JSON numbers when integral; owner is
-- split on whitespace into a 2-element JSON array (ConfD wants a [user, group]
-- tuple). additional_files is intentionally not exposed in v1.
--
-- BucketFS jobs are NOT database-scoped, so params NEVER carry a db_name marker.
-- Identifiers (service/bucket names) are single-quoted; the public flag is the
-- PUBLIC|PRIVATE keyword (required by ConfD on ADD BUCKET).
--
-- Follows the framework's EXPAND authoring contract: return nil to decline
-- (fail-open), a single string to accept (terminal); export a top-level global
-- `control_bucketfs_expand`; no defensive pcall. Scoped to the DBA role via the
-- module's RULE_ENSURE-registered rule.
-- =============================================================================

-- luacheck: globals control_bucketfs_expand

local SENTINEL = "\1"

-- Replace single-quoted '...' literals with placeholder tokens (see
-- CONTROL_DATABASE_V1 for the rationale): de-quoting first lets the parser
-- tokenise on whitespace without quoted values breaking the scan.
local function extract_literals(text)
    local literals = {}
    local out = text:gsub("'([^']*)'", function(value)
        literals[#literals + 1] = value
        return " " .. SENTINEL .. #literals .. SENTINEL .. " "
    end)
    return out, literals
end

local function tokenize(text)
    local spaced = text:gsub("[,=]", " %0 ")
    local tokens = {}
    for word in spaced:gmatch("%S+") do
        tokens[#tokens + 1] = word
    end
    return tokens
end

local function as_literal(token, literals)
    if not token then
        return nil
    end
    local idx = token:match("^" .. SENTINEL .. "(%d+)" .. SENTINEL .. "$")
    if idx then
        return literals[tonumber(idx)]
    end
    return nil
end

local function resolve(token, literals)
    local value = as_literal(token, literals)
    if value ~= nil then
        return value
    end
    return token
end

local function U(token)
    return token and string.upper(token) or nil
end

local function sql_quote(value)
    local escaped = value:gsub("'", "''")
    return "'" .. escaped .. "'"
end

local function json_escape(value)
    local s = value:gsub("\\", "\\\\")
    s = s:gsub('"', '\\"')
    -- Escape ASCII control characters (0x01-0x1F) so a raw newline/tab never
    -- produces invalid JSON that breaks cjson.decode downstream.
    s = s:gsub("[\1-\31]", function(c)
        local b = string.byte(c)
        if b == 8 then return "\\b"
        elseif b == 9 then return "\\t"
        elseif b == 10 then return "\\n"
        elseif b == 12 then return "\\f"
        elseif b == 13 then return "\\r"
        else return string.format("\\u%04x", b) end
    end)
    return s
end

local function json_str(key, value)
    return '"' .. key .. '":"' .. json_escape(value) .. '"'
end

-- Emit a number when the value is an unsigned integer, else a JSON string.
local function json_num_or_str(key, value)
    if value:match("^%d+$") then
        return '"' .. key .. '":' .. value
    end
    return json_str(key, value)
end

-- Split a value on whitespace into a JSON array of strings (for owner tuples).
local function json_words_array(key, value)
    local items = {}
    for word in value:gmatch("%S+") do
        items[#items + 1] = '"' .. json_escape(word) .. '"'
    end
    return '"' .. key .. '":[' .. table.concat(items, ",") .. "]"
end

local function build_json(parts)
    return "{" .. table.concat(parts, ",") .. "}"
end

local function emit(job, params_json)
    return "EXECUTE SCRIPT PREPROC.ADMIN_CONFD_JOB_V1('"
        .. job .. "', " .. sql_quote(params_json) .. ")"
end

-- File operations are not ConfD jobs; they are driven over the BucketFS HTTP(S)
-- service by a dedicated UDF, so they route to ADMIN_BUCKETFS_FILE_V1 rather than
-- the generic ADMIN_CONFD_JOB_V1 gateway.
local function emit_file(action, params_json)
    return "EXECUTE SCRIPT PREPROC.ADMIN_BUCKETFS_FILE_V1('"
        .. action .. "', " .. sql_quote(params_json) .. ")"
end

-- Index of the first token equal (case-insensitively) to kw at/after `from`.
local function index_of(t, kw, from)
    for j = from, #t do
        if U(t[j]) == kw then
            return j
        end
    end
    return nil
end

-- Collect a `key = value [, …]` option list starting at token index i into a
-- table keyed by lowercased option name. Stops at the first malformed pair.
local function collect_options(t, i, literals)
    local opts = {}
    while i <= #t do
        if t[i] == "," then
            i = i + 1
        elseif t[i + 1] == "=" and t[i + 2] then
            opts[string.lower(t[i])] = resolve(t[i + 2], literals)
            i = i + 3
        else
            break
        end
    end
    return opts
end

-- Append known service options (bucketfs_add / bucketfs_modify) to parts.
local function append_service_opts(parts, opts)
    if opts.http_port then
        parts[#parts + 1] = json_num_or_str("http_port", opts.http_port)
    end
    if opts.https_port then
        parts[#parts + 1] = json_num_or_str("https_port", opts.https_port)
    end
    if opts.owner then
        parts[#parts + 1] = json_words_array("owner", opts.owner)
    end
    if opts.sync_period then
        parts[#parts + 1] = json_num_or_str("sync_period", opts.sync_period)
    end
    if opts.sync_key then
        parts[#parts + 1] = json_str("sync_key", opts.sync_key)
    end
    if opts.path then
        parts[#parts + 1] = json_str("path", opts.path)
    end
    if opts.mode then
        parts[#parts + 1] = json_str("mode", opts.mode)
    end
    if opts.bucketvolume then
        parts[#parts + 1] = json_str("bucketvolume", opts.bucketvolume)
    end
end

-- Append known bucket options (bucket_add / bucket_modify) to parts.
local function append_bucket_opts(parts, opts)
    if opts.read_password then
        parts[#parts + 1] = json_str("read_password", opts.read_password)
    end
    if opts.write_password then
        parts[#parts + 1] = json_str("write_password", opts.write_password)
    end
end

-- --- per-command parsers (each returns the emit string, or nil to decline) ---

-- ADD|MODIFY SERVICE '<name>' WITH <options>
local function parse_service(t, literals, job)
    local name = as_literal(t[3], literals)
    if not name then
        return nil
    end
    local parts = { json_str("bucketfs_name", name) }
    local wi = index_of(t, "WITH", 4)
    if wi then
        append_service_opts(parts, collect_options(t, wi + 1, literals))
    end
    return emit(job, build_json(parts))
end

-- ADD BUCKET '<bucket>' TO SERVICE '<svc>' [PUBLIC|PRIVATE] [WITH <options>]
-- MODIFY BUCKET '<bucket>' IN SERVICE '<svc>' [PUBLIC|PRIVATE] [WITH <options>]
local function parse_bucket(t, literals, job)
    local bucket = as_literal(t[3], literals)
    if not bucket then
        return nil
    end
    local si = index_of(t, "SERVICE", 4)
    if not si then
        return nil
    end
    local svc = as_literal(t[si + 1], literals)
    if not svc then
        return nil
    end
    local parts = {
        json_str("bucket_name", bucket),
        json_str("bucketfs_name", svc),
    }
    if index_of(t, "PUBLIC", 4) then
        parts[#parts + 1] = '"public":true'
    elseif index_of(t, "PRIVATE", 4) then
        parts[#parts + 1] = '"public":false'
    end
    local wi = index_of(t, "WITH", 4)
    if wi then
        append_bucket_opts(parts, collect_options(t, wi + 1, literals))
    end
    return emit(job, build_json(parts))
end

-- DELETE BUCKET '<bucket>' FROM SERVICE '<svc>'
local function parse_bucket_delete(t, literals)
    local bucket = as_literal(t[3], literals)
    if not bucket then
        return nil
    end
    local si = index_of(t, "SERVICE", 4)
    if not si then
        return nil
    end
    local svc = as_literal(t[si + 1], literals)
    if not svc then
        return nil
    end
    local parts = {
        json_str("bucketfs_name", svc),
        json_str("bucket_name", bucket),
    }
    return emit("bucket_delete", build_json(parts))
end

-- Resolve the bucket/service literals shared by every file verb. Returns
-- bucket, service (both strings) or nil when either is missing or unquoted.
-- `from` is the first token index to scan for the BUCKET keyword.
local function bucket_service(t, literals, from)
    local bi = index_of(t, "BUCKET", from)
    if not bi then
        return nil
    end
    local bucket = as_literal(t[bi + 1], literals)
    if not bucket then
        return nil
    end
    local si = index_of(t, "SERVICE", bi + 2)
    if not si then
        return nil
    end
    local service = as_literal(t[si + 1], literals)
    if not service then
        return nil
    end
    return bucket, service
end

-- UPLOAD FILE '<url>' TO BUCKET '<bucket>' IN SERVICE '<service>' AS '<path>'
local function parse_upload(t, literals)
    if U(t[2]) ~= "FILE" then
        return nil
    end
    local url = as_literal(t[3], literals)
    if not url then
        return nil
    end
    -- No-secrets-in-SQL: decline a source URL with inline `user:pass@host`
    -- credentials so they never reach the rewrite, the audit log, or the UDF.
    if url:find("://[^@]*:[^@]*@") then
        return nil
    end
    local bucket, service = bucket_service(t, literals, 4)
    if not bucket then
        return nil
    end
    local ai = index_of(t, "AS", 4)
    if not ai then
        return nil
    end
    local path = as_literal(t[ai + 1], literals)
    if not path then
        return nil
    end
    local parts = {
        json_str("source_url", url),
        json_str("bucket", bucket),
        json_str("service", service),
        json_str("path", path),
    }
    return emit_file("upload", build_json(parts))
end

-- DELETE FILE '<path>' FROM BUCKET '<bucket>' IN SERVICE '<service>'
-- SHOW   FILE '<path>' FROM BUCKET '<bucket>' IN SERVICE '<service>'
local function parse_file_path(t, literals, action)
    local path = as_literal(t[3], literals)
    if not path then
        return nil
    end
    local bucket, service = bucket_service(t, literals, 4)
    if not bucket then
        return nil
    end
    local parts = {
        json_str("bucket", bucket),
        json_str("service", service),
        json_str("path", path),
    }
    return emit_file(action, build_json(parts))
end

-- LIST FILES IN BUCKET '<bucket>' IN SERVICE '<service>'
local function parse_list_files(t, literals)
    local bucket, service = bucket_service(t, literals, 3)
    if not bucket then
        return nil
    end
    local parts = {
        json_str("bucket", bucket),
        json_str("service", service),
    }
    return emit_file("list", build_json(parts))
end

-- control_bucketfs_expand(sqltext) -> rewritten EXECUTE SCRIPT for a recognised
-- CONTROL BUCKETFS command, else nil.
function control_bucketfs_expand(sqltext)
    if type(sqltext) ~= "string" then
        return nil
    end

    local trimmed = sqltext:gsub("^%s*(.-)%s*$", "%1")
    local without_semicolon = trimmed:gsub(";%s*$", "")
    local clean = without_semicolon:gsub("^%s*(.-)%s*$", "%1")

    local rest = clean:match(
        "^[Cc][Oo][Nn][Tt][Rr][Oo][Ll]%s+[Bb][Uu][Cc][Kk][Ee][Tt][Ff][Ss]%s+(.*)$"
    )
    if not rest then
        return nil
    end

    local literals
    rest, literals = extract_literals(rest)
    local t = tokenize(rest)
    if #t == 0 then
        return nil
    end

    local v1 = U(t[1])
    local v2 = U(t[2])

    if v1 == "SHOW" then
        if v2 == "SERVICES" and #t == 2 then
            return emit("bucketfs_list", "{}")
        elseif v2 == "SERVICE" then
            local name = as_literal(t[3], literals)
            if name and #t == 3 then
                return emit("bucketfs_info", build_json({ json_str("bucketfs_name", name) }))
            end
        elseif v2 == "FILE" then
            return parse_file_path(t, literals, "show")
        end
        return nil
    end

    if v1 == "DELETE" then
        if v2 == "SERVICE" then
            local name = as_literal(t[3], literals)
            if name and #t == 3 then
                return emit("bucketfs_delete", build_json({ json_str("bucketfs_name", name) }))
            end
            return nil
        elseif v2 == "BUCKET" then
            return parse_bucket_delete(t, literals)
        elseif v2 == "FILE" then
            return parse_file_path(t, literals, "delete")
        end
        return nil
    end

    if v1 == "UPLOAD" then
        return parse_upload(t, literals)
    end

    if v1 == "LIST" then
        if v2 == "FILES" then
            return parse_list_files(t, literals)
        end
        return nil
    end

    if v1 == "ADD" then
        if v2 == "SERVICE" then
            return parse_service(t, literals, "bucketfs_add")
        elseif v2 == "BUCKET" then
            return parse_bucket(t, literals, "bucket_add")
        end
        return nil
    end

    if v1 == "MODIFY" then
        if v2 == "SERVICE" then
            return parse_service(t, literals, "bucketfs_modify")
        elseif v2 == "BUCKET" then
            return parse_bucket(t, literals, "bucket_modify")
        end
        return nil
    end

    return nil
end
end

-- ----- sql/control_storage_v1.lua: fenced verbatim, so its locals stay private -----
do
-- =============================================================================
-- CONTROL_STORAGE_V1  (assembled into PREPROC_RT.CONFD_CONTROL_V1, not deployed alone)  — EXPAND-phase grammar
-- =============================================================================
-- The curated SQL surface for storage administration: EXAStorage volume/node
-- inspection AND the remote-volume (archive target) family. It parses the
-- `CONTROL STORAGE <verb> <object> …` grammar and rewrites each recognised
-- command into exactly one statement.
--
--   CONTROL STORAGE SHOW VOLUMES                          -> st_volume_list (read)
--   CONTROL STORAGE SHOW VOLUME <vid>                     -> st_volume_info {"vid":<n>} (read)
--   CONTROL STORAGE SHOW VOLUME '<name>'                  -> st_volume_info {"vname":"<name>"} (read)
--   CONTROL STORAGE SHOW NODES                            -> st_node_list (read)
--   CONTROL STORAGE SHOW REMOTE VOLUMES                   -> remote_volume_list_details (read)
--   CONTROL STORAGE SHOW REMOTE VOLUME '<name>'           -> REMOTE_VOLUME_QUERY_V1 (read, redacted)
--   CONTROL STORAGE SHOW REMOTE VOLUME '<name>' STATE     -> remote_volume_state (read)
--   CONTROL STORAGE ADD REMOTE VOLUME '<name>' TYPE '<type>' URL '<url>'
--       [USING CONNECTION <conn>] [OWNER '<user group>'] [WITH <opts>]
--                                                         -> ADMIN_REMOTE_VOLUME_V1 'add'
--   CONTROL STORAGE DROP REMOTE VOLUME '<name>'           -> remote_volume_remove
--
-- The remote-volume family MOVED here from CONTROL DATABASE: a remote volume is a
-- storage object, not a database one. The rewrite targets are unchanged by the
-- move, so the UDF / admin-script layer below the grammar is untouched.
--
-- Argument convention (matches the existing "identifiers are bare, not quoted"
-- rule): a bare unsigned integer after SHOW VOLUME is the numeric volume id and
-- is emitted as a JSON number under `vid`; a single-quoted argument is a volume
-- name and is emitted as a JSON string under `vname`. Remote-volume names, types
-- and URLs are single-quoted; a CONNECTION is a bare identifier.
--
-- EVERY read in this module — EXAStorage inspection and remote volumes alike —
-- rewrites to an inline-capable EMITS UDF SELECT, so it works standalone AND
-- embedded (parenthesised) inside a larger statement:
-- `CREATE TABLE t AS SELECT * FROM (CONTROL STORAGE SHOW VOLUMES)`. Only the two
-- mutating remote-volume verbs still rewrite to `EXECUTE SCRIPT`, and an embedded
-- ACTION is never spliced (see expand_inline).
--
-- Mutating EXAStorage verbs (create/delete/enlarge/lock/suspend/device, etc.) are
-- intentionally not parsed and always decline; the only mutations this module
-- accepts are the remote-volume ADD/DROP verbs above. MODIFY REMOTE VOLUME also
-- declines: no remote_volume_modify ConfD job exists (a volume is changed by
-- DROP + re-ADD).
--
-- Credentials NEVER appear inline: ADD REMOTE VOLUME carries only a bare
-- CONNECTION identifier (resolved server-side by ADMIN_REMOTE_VOLUME_V1), and a URL
-- with inline user:pass@ credentials is declined at parse time. The detail SHOW
-- routes to a dedicated REDACTING read UDF rather than the generic query gateway,
-- because remote_volume_info echoes the stored username/password.
--
-- Storage jobs are NOT database-scoped, so params NEVER carry a db_name marker.
--
-- Follows the framework's EXPAND authoring contract: return nil to decline
-- (fail-open), a single string to accept (terminal); export a top-level global
-- `control_storage_expand`; no defensive pcall. Scoped to the DBA role via the
-- module's RULE_ENSURE-registered rule.
-- =============================================================================

-- luacheck: globals control_storage_expand

local SENTINEL = "\1"

-- Replace single-quoted '...' literals with placeholder tokens (see
-- CONTROL_DATABASE_V1 for the rationale): de-quoting first lets the parser
-- tokenise on whitespace without quoted values breaking the scan.
local function extract_literals(text)
    local literals = {}
    local out = text:gsub("'([^']*)'", function(value)
        literals[#literals + 1] = value
        return " " .. SENTINEL .. #literals .. SENTINEL .. " "
    end)
    return out, literals
end

-- Split on whitespace, first isolating `,` and `=` as their own tokens so a
-- remote-volume option list (`WITH id = 5, labels = 'a,b'`) tokenises uniformly
-- whether or not it is written with spaces around the separators.
local function tokenize(text)
    local spaced = text:gsub("[,=]", " %0 ")
    local tokens = {}
    for word in spaced:gmatch("%S+") do
        tokens[#tokens + 1] = word
    end
    return tokens
end

local function as_literal(token, literals)
    if not token then
        return nil
    end
    local idx = token:match("^" .. SENTINEL .. "(%d+)" .. SENTINEL .. "$")
    if idx then
        return literals[tonumber(idx)]
    end
    return nil
end

-- Resolve a token to its string value: the literal value if it is a placeholder,
-- otherwise the bare token text unchanged (e.g. a CONNECTION name or integer).
local function resolve(token, literals)
    local value = as_literal(token, literals)
    if value ~= nil then
        return value
    end
    return token
end

local function U(token)
    return token and string.upper(token) or nil
end

local function sql_quote(value)
    local escaped = value:gsub("'", "''")
    return "'" .. escaped .. "'"
end

local function json_escape(value)
    local s = value:gsub("\\", "\\\\")
    s = s:gsub('"', '\\"')
    -- Escape ASCII control characters (0x01-0x1F) so a raw newline/tab never
    -- produces invalid JSON that breaks cjson.decode downstream.
    s = s:gsub("[\1-\31]", function(c)
        local b = string.byte(c)
        if b == 8 then return "\\b"
        elseif b == 9 then return "\\t"
        elseif b == 10 then return "\\n"
        elseif b == 12 then return "\\f"
        elseif b == 13 then return "\\r"
        else return string.format("\\u%04x", b) end
    end)
    return s
end

local function json_str(key, value)
    return '"' .. key .. '":"' .. json_escape(value) .. '"'
end

local function json_num(key, value)
    return '"' .. key .. '":' .. value
end

-- Emit a number when the value is an unsigned integer, else a JSON string.
local function json_num_or_str(key, value)
    if value:match("^%d+$") then
        return '"' .. key .. '":' .. value
    end
    return json_str(key, value)
end

-- "key":[ … ] from a value split on whitespace (e.g. an owner 'user group' tuple).
local function json_words_array(key, value)
    local items = {}
    for word in value:gmatch("%S+") do
        items[#items + 1] = '"' .. json_escape(word) .. '"'
    end
    return '"' .. key .. '":[' .. table.concat(items, ",") .. "]"
end

-- "key":[ … ] from a comma-separated value (e.g. remote-volume options/labels).
local function json_csv_array(key, value)
    local items = {}
    for part in value:gmatch("[^,]+") do
        local trimmed = part:gsub("^%s*(.-)%s*$", "%1")
        if trimmed ~= "" then
            items[#items + 1] = '"' .. json_escape(trimmed) .. '"'
        end
    end
    return '"' .. key .. '":[' .. table.concat(items, ",") .. "]"
end

local function build_json(parts)
    return "{" .. table.concat(parts, ",") .. "}"
end

-- Index of the first token equal to keyword kw at/after `from`, else nil.
local function index_of(t, kw, from)
    for j = from, #t do
        if U(t[j]) == kw then
            return j
        end
    end
    return nil
end

-- Collect a `key = value [, …]` option list from token index i into a table
-- keyed by lowercased option name. Stops at the first malformed pair.
local function collect_options(t, i, literals)
    local opts = {}
    while i <= #t do
        if t[i] == "," then
            i = i + 1
        elseif t[i + 1] == "=" and t[i + 2] then
            opts[string.lower(t[i])] = resolve(t[i + 2], literals)
            i = i + 3
        else
            break
        end
    end
    return opts
end

-- The generic ACTION rewrite: one EXECUTE SCRIPT call through the ConfD gateway.
local function emit(job, params_json)
    return "EXECUTE SCRIPT PREPROC.ADMIN_CONFD_JOB_V1('"
        .. job .. "', " .. sql_quote(params_json) .. ")"
end

-- The ConfD CONNECTION object name (mirrors the constant in the Lua admin
-- scripts). Read commands route through the read UDFs, which resolve this
-- CONNECTION themselves.
local CONFD_CONNECTION = "CONFD_CONNECTION"

-- The inline-capable rewrite target for READ commands: a scalar-EMITS UDF call
-- driven by a single-row source. Unlike EXECUTE SCRIPT, this is a table
-- EXPRESSION — it can stand alone as a SELECT statement AND be embedded as a
-- subquery inside a larger statement (INSERT INTO t SELECT * FROM (<this>)).
-- The UDF flattens the ConfD envelope into (FIELD, VALUE_TEXT) rows and raises
-- on failure, so no Lua admin layer sits between the preprocessor and the UDF.
local function emit_query(job, params_json)
    return "SELECT PREPROC_RT.CONFD_QUERY_V1('" .. CONFD_CONNECTION .. "', '"
        .. job .. "', " .. sql_quote(params_json) .. ") FROM (SELECT 1)"
end

-- The ADD remote-volume verb routes to a dedicated orchestrator that resolves
-- CONNECTION credentials, rather than the generic gateway.
local function emit_remote_volume(action, params_json)
    return "EXECUTE SCRIPT PREPROC.ADMIN_REMOTE_VOLUME_V1('"
        .. action .. "', " .. sql_quote(params_json) .. ")"
end

-- The credential-bearing detail SHOW routes to a dedicated redacting read UDF that
-- strips username/password before emitting the FIELD/VALUE_TEXT rows — a bare,
-- embeddable SELECT. It MUST NOT use the generic CONFD_QUERY_V1, which would leak
-- those leaves.
local function emit_remote_volume_query(params_json)
    return "SELECT PREPROC_RT.REMOTE_VOLUME_QUERY_V1('" .. CONFD_CONNECTION .. "', "
        .. sql_quote(params_json) .. ") FROM (SELECT 1)"
end

-- --- per-command parsers (each returns the emit string, or nil to decline) ---

-- SHOW VOLUME <vid>|'<name>'  — bare unsigned integer is a vid (JSON number),
-- a single-quoted argument is a vname (JSON string). Anything else declines.
local function parse_volume_info(t, literals)
    if #t ~= 3 then
        return nil
    end
    local name = as_literal(t[3], literals)
    if name then
        return emit_query("st_volume_info", build_json({ json_str("vname", name) }))
    end
    if t[3]:match("^%d+$") then
        return emit_query("st_volume_info", build_json({ json_num("vid", t[3]) }))
    end
    return nil
end

-- SHOW REMOTE VOLUME '<name>' [STATE]
-- The bare detail SHOW routes to the dedicated redacting read UDF
-- (REMOTE_VOLUME_QUERY_V1, because remote_volume_info echoes the password); the
-- STATE variant is a secret-free generic read (remote_volume_state). Both are
-- bare, embeddable SELECTs.
local function parse_show_remote_volume(t, literals)
    local name = as_literal(t[4], literals)
    if not name then
        return nil
    end
    local params = build_json({ json_str("remote_volume_name", name) })
    if #t == 4 then
        return emit_remote_volume_query(params)
    elseif #t == 5 and U(t[5]) == "STATE" then
        return emit_query("remote_volume_state", params)
    end
    return nil
end

-- ADD REMOTE VOLUME '<name>' TYPE '<type>' URL '<url>'
--     [USING CONNECTION <conn>] [OWNER '<user group>'] [WITH <options>]
-- Routes to the credential-resolving orchestrator (ADMIN_REMOTE_VOLUME_V1 'add').
-- Credentials NEVER appear inline: only a bare CONNECTION identifier is carried,
-- and a URL with inline user:pass@ creds is declined at parse time. Owner is a
-- 'user group' pair → [user, group]; WITH accepts only the non-secret keys
-- id (→ remote_volume_id, number), labels, and options (comma → array).
local function parse_add_remote_volume(t, literals)
    local name = as_literal(t[4], literals)
    if not name then
        return nil
    end
    local ti = index_of(t, "TYPE", 5)
    local vol_type = ti and as_literal(t[ti + 1], literals)
    if not vol_type then
        return nil
    end
    local ui = index_of(t, "URL", 5)
    local url = ui and as_literal(t[ui + 1], literals)
    if not url then
        return nil
    end
    if url:find("://[^@]*:[^@]*@") then
        return nil
    end
    local parts = {
        json_str("remote_volume_name", name),
        json_str("vol_type", vol_type),
        json_str("url", url),
    }
    local ci = index_of(t, "CONNECTION", 5)
    if ci and t[ci + 1] then
        parts[#parts + 1] = json_str("connection_name", resolve(t[ci + 1], literals))
    end
    local oi = index_of(t, "OWNER", 5)
    if oi then
        local owner = as_literal(t[oi + 1], literals)
        if owner then
            parts[#parts + 1] = json_words_array("owner", owner)
        end
    end
    local wi = index_of(t, "WITH", 5)
    if wi then
        local opts = collect_options(t, wi + 1, literals)
        if opts.id then
            parts[#parts + 1] = json_num_or_str("remote_volume_id", opts.id)
        end
        if opts.labels then
            parts[#parts + 1] = json_csv_array("labels", opts.labels)
        end
        if opts.options then
            parts[#parts + 1] = json_csv_array("options", opts.options)
        end
    end
    return emit_remote_volume("add", build_json(parts))
end

-- dispatch(rest) maps the text following `CONTROL STORAGE` to a single rewrite
-- string, or nil to decline (fail-open). It owns the literal extraction, the
-- tokenisation, and the whole verb/object keyword chain, so the standalone path
-- and the embedded splicer produce the SAME rewrite for a given command wherever
-- it appears. A read yields a bare, embeddable SELECT (prefix `SELECT`); an
-- action yields an `EXECUTE SCRIPT` statement. dispatch is agnostic to that
-- distinction — the caller discriminates on the prefix.
local function dispatch(rest)
    local literals
    rest, literals = extract_literals(rest)
    local t = tokenize(rest)
    if #t == 0 then
        return nil
    end

    local v1 = U(t[1])
    local v2 = U(t[2])

    if v1 == "SHOW" then
        if v2 == "VOLUMES" and #t == 2 then
            return emit_query("st_volume_list", "{}")
        elseif v2 == "VOLUME" then
            return parse_volume_info(t, literals)
        elseif v2 == "NODES" and #t == 2 then
            return emit_query("st_node_list", "{}")
        elseif v2 == "REMOTE" and U(t[3]) == "VOLUMES" and #t == 3 then
            return emit_query("remote_volume_list_details", build_json({}))
        elseif v2 == "REMOTE" and U(t[3]) == "VOLUME" then
            return parse_show_remote_volume(t, literals)
        end
        return nil
    end

    if v1 == "ADD" and v2 == "REMOTE" and U(t[3]) == "VOLUME" then
        return parse_add_remote_volume(t, literals)
    end

    if v1 == "DROP" and v2 == "REMOTE" and U(t[3]) == "VOLUME" then
        local name = as_literal(t[4], literals)
        if name and #t == 4 then
            return emit("remote_volume_remove", build_json({ json_str("remote_volume_name", name) }))
        end
        return nil
    end

    -- MODIFY REMOTE VOLUME is intentionally not handled: no remote_volume_modify
    -- ConfD job exists, so it falls through here and declines (a volume is changed
    -- by DROP + re-ADD). Mutating EXAStorage verbs decline the same way.
    return nil
end

-- A dispatch result is embeddable only when it is a read: a table expression
-- beginning with SELECT. An action (EXECUTE SCRIPT …) or a decline (nil) is not.
local function is_read(rewrite)
    return type(rewrite) == "string" and rewrite:sub(1, 6) == "SELECT"
end

-- The opener of an embedded group: a `(`, optional whitespace, `CONTROL
-- STORAGE`, and the whitespace ending the keyword — matched case-insensitively
-- and anchored at the candidate `(`.
local GROUP_OPEN = "%(%s*[Cc][Oo][Nn][Tt][Rr][Oo][Ll]%s+"
    .. "[Ss][Tt][Oo][Rr][Aa][Gg][Ee]%s+"

-- Find the next top-level `(CONTROL STORAGE ` opener at/after `from`, tracking
-- single-quote literal state (a `''` run stays inside the literal) so an opener
-- that falls inside the OUTER statement's own quoted string is never matched.
-- Returns the index of the `(` and the index of the last matched (whitespace)
-- char — the inner command begins at the next index — or nil when none remains.
local function find_group_open(text, from)
    local i, n = from, #text
    local in_literal = false
    while i <= n do
        local c = text:sub(i, i)
        if in_literal then
            if c == "'" then
                if text:sub(i + 1, i + 1) == "'" then
                    i = i + 1
                else
                    in_literal = false
                end
            end
        elseif c == "'" then
            in_literal = true
        elseif c == "(" then
            local open_index, prefix_end = text:find("^" .. GROUP_OPEN, i)
            if open_index then
                return open_index, prefix_end
            end
        end
        i = i + 1
    end
    return nil
end

-- Walk from the opening `(` at `open_index` to its matching `)`, tracking
-- single-quote literal state (a `''` run stays inside the literal) and paren
-- depth, so a `)` inside a quoted literal (e.g. a volume name 'a)b') never closes
-- the group. Returns the index of the matching `)`, or nil when the parentheses
-- are unbalanced.
local function find_matching_close(text, open_index)
    local depth, in_literal = 0, false
    local i, n = open_index, #text
    while i <= n do
        local c = text:sub(i, i)
        if in_literal then
            if c == "'" then
                if text:sub(i + 1, i + 1) == "'" then
                    i = i + 1
                else
                    in_literal = false
                end
            end
        elseif c == "'" then
            in_literal = true
        elseif c == "(" then
            depth = depth + 1
        elseif c == ")" then
            depth = depth - 1
            if depth == 0 then
                return i
            end
        end
        i = i + 1
    end
    return nil
end

-- Rewrite CONTROL STORAGE read commands embedded inside a larger statement. Each
-- parenthesised `(CONTROL STORAGE <read>)` group is replaced in place by the
-- equivalent re-parenthesised UDF SELECT, so e.g.
--   INSERT INTO t SELECT * FROM (CONTROL STORAGE SHOW REMOTE VOLUMES)
-- becomes
--   INSERT INTO t SELECT * FROM (SELECT PREPROC_RT.CONFD_QUERY_V1(…) FROM (SELECT 1))
-- while the surrounding SQL — including the outer statement's own quoted string
-- literals — is preserved byte-for-byte. The inner command is routed through the
-- SAME dispatch as the standalone path, receiving the RAW inner text so dispatch
-- does its own literal extraction on the fragment alone (never on the whole
-- Any number of groups in one statement are spliced, but they must all be
-- CONTROL STORAGE groups: the framework's EXPAND phase is first-match-terminal,
-- so once this module accepts, no other module runs and a mixed-domain statement
-- (e.g. also embedding a CONTROL DATABASE read) would reach the engine with that
-- other domain's text still raw.
-- statement). Only a read (a SELECT) is splice-able: an embedded action (EXECUTE
-- SCRIPT — i.e. ADD/DROP REMOTE VOLUME), an unrecognised command, or unbalanced
-- parentheses declines the WHOLE statement (nil, fail-open) so the engine raises a
-- normal error rather than seeing invalid SQL. With no embedded group at all,
-- declines (nil). Never raises.
local function expand_inline(sqltext)
    local parts = {}
    local pos = 1
    local spliced = false
    while true do
        local open_index, prefix_end = find_group_open(sqltext, pos)
        if not open_index then
            break
        end
        local close_index = find_matching_close(sqltext, open_index)
        if not close_index then
            return nil
        end
        local inner = sqltext:sub(prefix_end + 1, close_index - 1)
        local rewrite = dispatch(inner)
        if not is_read(rewrite) then
            return nil
        end
        parts[#parts + 1] = sqltext:sub(pos, open_index - 1)
        parts[#parts + 1] = "(" .. rewrite .. ")"
        pos = close_index + 1
        spliced = true
    end
    if not spliced then
        return nil
    end
    parts[#parts + 1] = sqltext:sub(pos)
    return table.concat(parts)
end

-- control_storage_expand(sqltext) -> a single rewrite for a recognised CONTROL
-- STORAGE command (standalone), the larger statement with an embedded read spliced
-- in, or nil to decline (fail-open). Never raises.
function control_storage_expand(sqltext)
    if type(sqltext) ~= "string" then
        return nil
    end

    local trimmed = sqltext:gsub("^%s*(.-)%s*$", "%1")
    local without_semicolon = trimmed:gsub(";%s*$", "")
    local clean = without_semicolon:gsub("^%s*(.-)%s*$", "%1")

    local rest = clean:match(
        "^[Cc][Oo][Nn][Tt][Rr][Oo][Ll]%s+[Ss][Tt][Oo][Rr][Aa][Gg][Ee]%s+(.*)$"
    )
    if not rest then
        -- Not a standalone CONTROL STORAGE statement. Try to splice a read command
        -- embedded (in parentheses) inside a larger statement. The read target is a
        -- UDF subquery (an expression), so it slots in wherever a table is expected.
        return expand_inline(sqltext)
    end

    return dispatch(rest)
end
end

-- =============================================================================
-- CONFD_CONTROL_V1  (PREPROC_RT.CONFD_CONTROL_V1)  — EXPAND-phase module entry
-- =============================================================================
-- The single entry script of the `confd_control` module: one script, one rule,
-- one object inventory for all three ConfD-backed command surfaces.
--
--   CONTROL DATABASE …  -> control_database_expand
--   CONTROL BUCKETFS …  -> control_bucketfs_expand
--   CONTROL STORAGE  …  -> control_storage_expand
--
-- This source file is only the dispatcher tail. build.py merges the three
-- grammar sources into this script's body ahead of it, each fenced in its own
-- `do … end` block so their identically named local helpers stay private.
-- Delegating at run time is not an option: an import works only at top-level
-- script scope and never from inside a function of a script MASTER itself
-- imported, so importing a grammar here would fail-open every CONTROL command.
--
-- Dispatch is ordered fallthrough — database, then bucketfs, then storage, first
-- non-nil result wins — reproducing exactly what MASTER did with three separate
-- EXPAND rules scanned in rule_id-ascending order under first-match-terminal
-- semantics. It is deliberately NOT a switch on the statement's second keyword:
-- an inline-embedded read arrives as a SELECT / CREATE TABLE / INSERT statement
-- with the CONTROL command parenthesised inside it, which such a switch would
-- decline. Each grammar receives the statement text verbatim and applies its own
-- trimming, so a merged rewrite is byte-identical to the pre-merge one.
--
-- Follows the framework's EXPAND authoring contract: return nil to decline
-- (fail-open), a single string to accept (terminal); export a top-level global
-- `confd_control`. Nothing here traps a grammar error — MASTER's dispatch-level
-- pcall stays the only error boundary, so a broken grammar surfaces there loudly
-- instead of being swallowed. Scoped to the DBA role via the registered rule.
-- =============================================================================

-- luacheck: globals confd_control
-- luacheck: read globals control_database_expand control_bucketfs_expand control_storage_expand

-- confd_control(sqltext) -> the rewrite from the first grammar that recognises
-- the statement, or nil to decline (fail-open). Never raises on its own input.
function confd_control(sqltext)
    if type(sqltext) ~= "string" then
        return nil
    end

    local rewrite = control_database_expand(sqltext)
    if rewrite ~= nil then
        return rewrite
    end

    rewrite = control_bucketfs_expand(sqltext)
    if rewrite ~= nil then
        return rewrite
    end

    rewrite = control_storage_expand(sqltext)
    if rewrite ~= nil then
        return rewrite
    end

    return nil
end
/

--/
CREATE OR REPLACE LUA SCRIPT PREPROC.ADMIN_CONFD_JOB_V1(job_name, params_json) RETURNS TABLE AS
-- =============================================================================
-- ADMIN_CONFD_JOB  (PREPROC.ADMIN_CONFD_JOB)  — Lua admin script body
-- =============================================================================
-- The single internal entry point through which every CONTROL command reaches
-- ConfD. The CONTROL_DATABASE_V1 EXPAND module rewrites each recognised
-- `CONTROL DATABASE …` statement into exactly one
-- `EXECUTE SCRIPT PREPROC.ADMIN_CONFD_JOB(job, params)` call against this
-- script. This script:
--   1. resolves the ConfD CONNECTION object name (a constant — see below),
--   2. calls the generic UDF PREPROC_RT.CONFD_JOB_V1(connection, job, params),
--   3. converts the UDF's ERR: sentinel into a loud script error,
--   4. raises if the ConfD envelope reports a non-zero result_code, and
--   5. breaks the job's result_output down into a readable two-column table
--      (FIELD, VALUE_TEXT) — one row per leaf value — instead of returning one
--      long JSON blob. Nested objects/arrays become dotted/indexed paths
--      (e.g. nodes.active[1], usage_persistent[1].size), keys are sorted for
--      stable output, and empty containers show as "(empty)".
--
-- Output shape
--   Every job returns the same two columns, so a generic SHOW/inspect command is
--   readable row-by-row in any SQL client. ConfD wraps each job in an envelope
--   ({result_code, result_name, result_output, …}); we surface only the
--   result_output payload on success (the part the operator cares about). The
--   columns are FIELD / VALUE_TEXT — never RESULT or VALUE, both reserved
--   keywords that would make the table description string invalid.
--
-- Why a generic admin script (not one per job)
--   ConfD has dozens of jobs and a uniform call shape. Keeping ONE admin script
--   that takes (job_name, params_json) means new commands are added purely in
--   the grammar — no new database object per job. The curated SQL surface
--   (CONTROL DATABASE …) is enforced by the EXPAND module, not here.
--
-- Why raising here is correct (unlike a dispatched module)
--   A preprocessor MODULE must never raise (MASTER's pcall would silently skip
--   it). This is NOT a module — it is an EXECUTE SCRIPT target invoked after the
--   statement has already been rewritten. A failed ConfD job MUST surface as a
--   visible error to the operator, so this script re-raises the UDF's ERR:
--   sentinel via error().
--
-- Parameters (declared in the CREATE OR REPLACE LUA SCRIPT header by build.py)
--   job_name     the ConfD job to run, e.g. 'db_backup_start'
--   params_json  JSON object of job parameters, e.g. '{"backup_volume_name":"v","level":0}'
--                NULL is normalised to '{}'. db_name is injected by the UDF when
--                absent, so the curated commands pass only the job-specific args.
-- =============================================================================

-- luacheck: read globals job_name params_json

-- The CONNECTION object the DBA must create as a prerequisite (see docs). To
-- point at a different ConfD endpoint, change this constant and redeploy.
local CONFD_CONNECTION = "CONFD_CONNECTION"

-- Normalise a NULL/absent params object to an empty JSON object so the UDF's
-- json.loads path is exercised uniformly.
local pj = params_json
if pj == null or pj == nil then
    pj = "{}"
end

-- Invoke the generic ConfD gateway UDF. Named binding keeps the values out of
-- the SQL text.
-- The column alias must NOT be RESULT: it is a reserved keyword in Exasol and
-- would make this SELECT a syntax error. The value is read positionally below.
local ok, res = pquery(
    "SELECT PREPROC_RT.CONFD_JOB_V1(:c, :j, :p) AS confd_result",
    { c = CONFD_CONNECTION, j = job_name, p = pj }
)
if not ok then
    error("PREPROC.ADMIN_CONFD_JOB: UDF call failed: " .. tostring(res.error_message))
end

local result = res[1][1]
if result == null or result == nil then
    error(
        "PREPROC.ADMIN_CONFD_JOB: ConfD job '" .. tostring(job_name)
            .. "' returned no value"
    )
end

-- The UDF never raises; a failure arrives as the ERR:<message> sentinel. Re-raise
-- it here so the operator sees a clear error rather than an ERR: string in a
-- result column.
local result_str = tostring(result)
if string.sub(result_str, 1, 4) == "ERR:" then
    error(
        "PREPROC.ADMIN_CONFD_JOB: ConfD job '" .. tostring(job_name)
            .. "' failed: " .. string.sub(result_str, 5)
    )
end

-- Success path: break the JSON result down into a readable two-column table.
-- Column names are FIELD / VALUE_TEXT, never RESULT or VALUE — both reserved
-- keywords that Exasol rejects in the table description string.
local COLS = "field VARCHAR(256), value_text VARCHAR(2000000)"

-- cjson is available to Exasol Lua scripts via require (no global `json`).
local cjson = require("cjson")
local ok_decode, envelope = pcall(cjson.decode, result_str)
if not ok_decode or type(envelope) ~= "table" then
    -- Not JSON we can break down (shouldn't happen for a ConfD job) — surface
    -- the raw text verbatim rather than failing the operator's command.
    exit({ { "result", result_str } }, COLS)
end

-- ConfD wraps every job in an envelope; a non-zero result_code is a failure.
-- Raise it loudly (same contract as the ERR: sentinel above) so a failed job is
-- never mistaken for an empty result set.
local code = envelope.result_code
if type(code) == "number" and code ~= 0 then
    error(
        "PREPROC.ADMIN_CONFD_JOB: ConfD job '" .. tostring(job_name)
            .. "' failed (code " .. tostring(code) .. "): "
            .. tostring(envelope.result_desc or envelope.result_name or "")
    )
end

-- Flatten an arbitrarily-nested decoded value into FIELD/VALUE_TEXT rows. Object
-- keys are sorted for stable output and joined with '.'; array elements use a
-- [i] suffix; JSON null and empty containers get explicit leaf markers so the
-- operator never sees a blank where a value was expected.
local JNULL = cjson.null
local rows = {}

local function flatten(prefix, value)
    local label = (prefix ~= "" and prefix) or "value"
    if value == JNULL then
        rows[#rows + 1] = { label, "null" }
        return
    end
    if type(value) ~= "table" then
        rows[#rows + 1] = { label, tostring(value) }
        return
    end
    local count = 0
    for _ in pairs(value) do
        count = count + 1
    end
    if count == 0 then
        rows[#rows + 1] = { label, "(empty)" }
    elseif count == #value then
        for i = 1, #value do
            flatten(prefix .. "[" .. i .. "]", value[i])
        end
    else
        local keys = {}
        for k in pairs(value) do
            keys[#keys + 1] = tostring(k)
        end
        table.sort(keys)
        for _, k in ipairs(keys) do
            local child = (prefix == "") and k or (prefix .. "." .. k)
            flatten(child, value[k])
        end
    end
end

-- We are mostly interested in result_output; if a job ever omits it, fall back
-- to flattening the whole envelope so nothing is silently lost.
local output = envelope.result_output
if output == nil then
    output = envelope
end
flatten("", output)

-- A job that succeeds with no output (e.g. an abort/delete) yields zero rows;
-- emit one status row so the operator sees a clear confirmation.
if #rows == 0 then
    rows[#rows + 1] = { "status", tostring(envelope.result_name or "OK") }
end

exit(rows, COLS)
/

--/
CREATE OR REPLACE LUA SCRIPT PREPROC.ADMIN_VIRTUAL_RESTORE_V1(vr_action, params_json) RETURNS TABLE AS
-- =============================================================================
-- ADMIN_VIRTUAL_RESTORE  (PREPROC.ADMIN_VIRTUAL_RESTORE)  — Lua admin script body
-- =============================================================================
-- Admin script for the CONTROL DATABASE … VIRTUAL RESTORE command family.
-- The CONTROL_DATABASE_V1 EXPAND module rewrites START/STOP VIRTUAL RESTORE
-- statements into:
--   EXECUTE SCRIPT PREPROC.ADMIN_VIRTUAL_RESTORE(vr_action, params_json)
-- where vr_action is 'start' or 'stop' and params_json is a JSON object built by
-- the grammar module. This script:
--   1. validates all DDL identifiers (vdb_name, schema names, connection names)
--      against ^[A-Za-z][A-Za-z0-9_]*$ BEFORE any UDF call or DDL,
--   2. calls PREPROC_RT.VIRTUAL_RESTORE_V1(connection, vr_action, params_json),
--   3. re-raises the UDF's ERR: sentinel as a loud script error,
--   4. for 'start': issues DDL via pquery (CREATE OR REPLACE JAVA ADAPTER SCRIPT
--      and one CREATE VIRTUAL SCHEMA per requested schema),
--   5. for 'stop': queries EXA_DBA_VIRTUAL_SCHEMAS, drops all VR schemas, calls
--      the UDF to tear down the virtual DB/volume, conditionally drops the adapter,
--   6. exits with FIELD/VALUE_TEXT rows — one per orchestrator step plus summary rows.
--
-- Output shape
--   Two columns: field VARCHAR(256), value_text VARCHAR(2000000).
--   Same contract as ADMIN_CONFD_JOB — never RESULT or VALUE (reserved keywords).
--
-- Schema-drop / teardown ordering note (stop)
--   Virtual schema DROP statements run first (best-effort, via pquery), then the
--   UDF calls db_stop/db_delete/st_volume_delete. These are not transactional:
--   if the UDF call fails after schemas are dropped, the schemas are gone but the
--   virtual DB may still be running. The operator can reissue STOP to complete the
--   teardown.
--
-- Parameters (declared in the CREATE OR REPLACE LUA SCRIPT header by build.py)
--   vr_action    'start' or 'stop'
--                (named vr_action, not action — ACTION is a reserved keyword
--                in Exasol and cannot be used as a script parameter)
--   params_json  JSON object of virtual-restore parameters, e.g.
--                '{"vdb_name":"VR1","schemas":["S1"],"jdbc_connection":"JC",
--                  "port":9563,"mem_size":"4 GiB","volume_size":"20 GiB",
--                  "timeout":600,"backup_id":"1 db/vol db"}'
--                NULL is normalised to '{}'. 'stop' only needs vdb_name.
-- =============================================================================

-- luacheck: read globals vr_action params_json

local CONFD_CONNECTION = "CONFD_CONNECTION"
local COLS = "field VARCHAR(256), value_text VARCHAR(2000000)"

-- Normalise a NULL params_json argument.
local pj = params_json
if pj == null or pj == nil then
    pj = "{}"
end

-- ---------------------------------------------------------------------------
-- Identifier validation
-- ---------------------------------------------------------------------------
-- Validate that name matches ^[A-Za-z][A-Za-z0-9_]*$ (Exasol unquoted-identifier
-- rules). Lua patterns do not support anchored character classes the same way as
-- PCRE, but %a/%w/_/^ suffice here.
local function is_valid_identifier(name)
    if type(name) ~= "string" or #name == 0 then
        return false
    end
    -- First character must be a letter.
    local first = string.sub(name, 1, 1)
    if not string.match(first, "^[A-Za-z]$") then
        return false
    end
    -- Remaining characters: letters, digits, underscore only.
    if string.match(name, "[^A-Za-z0-9_]") then
        return false
    end
    return true
end

local function require_identifier(value, label)
    if not is_valid_identifier(value) then
        error(
            "PREPROC.ADMIN_VIRTUAL_RESTORE: invalid " .. label
                .. " '" .. tostring(value)
                .. "': must match ^[A-Za-z][A-Za-z0-9_]*$"
        )
    end
end

-- ---------------------------------------------------------------------------
-- adapter_jar_path safety check
-- ---------------------------------------------------------------------------
-- The adapter_jar_path comes from our own UDF result, but we still reject it if
-- it contains a single quote or ASCII control characters (defensive embedding).
local function require_safe_jar_path(path)
    if type(path) ~= "string" then
        error("PREPROC.ADMIN_VIRTUAL_RESTORE: adapter_jar_path is not a string")
    end
    if string.find(path, "'") then
        error(
            "PREPROC.ADMIN_VIRTUAL_RESTORE: adapter_jar_path contains a single quote "
                .. "— refusing to embed in DDL: " .. path
        )
    end
    -- Reject ASCII control characters (bytes 0x00–0x1F, 0x7F).
    if string.find(path, "[\0-\31\127]") then
        error(
            "PREPROC.ADMIN_VIRTUAL_RESTORE: adapter_jar_path contains control characters "
                .. "— refusing to embed in DDL"
        )
    end
end

-- ---------------------------------------------------------------------------
-- action dispatch
-- ---------------------------------------------------------------------------
local cjson = require("cjson")

if vr_action == "start" then
    -- -----------------------------------------------------------------------
    -- START — validate identifiers, call UDF, issue DDL, return rows
    -- -----------------------------------------------------------------------

    -- Decode params_json so we can validate identifiers before calling the UDF.
    local ok_decode, params = pcall(cjson.decode, pj)
    if not ok_decode or type(params) ~= "table" then
        error("PREPROC.ADMIN_VIRTUAL_RESTORE: could not decode params_json: " .. tostring(pj))
    end

    -- vdb_name
    local vdb_name = params.vdb_name
    if vdb_name == nil or vdb_name == cjson.null then
        vdb_name = "VR1"
    end
    require_identifier(tostring(vdb_name), "vdb_name")

    -- schemas (required for start)
    local schemas = params.schemas
    if schemas == nil or schemas == cjson.null or type(schemas) ~= "table" then
        error("PREPROC.ADMIN_VIRTUAL_RESTORE: params_json must contain a 'schemas' array")
    end
    for i = 1, #schemas do
        require_identifier(tostring(schemas[i]), "schemas[" .. i .. "]")
    end

    -- connection names used in VS properties (embedded as WITH … = '…' values)
    local jdbc_connection = params.jdbc_connection
    if jdbc_connection ~= nil and jdbc_connection ~= cjson.null then
        require_identifier(tostring(jdbc_connection), "jdbc_connection")
    end
    local exa_connection = params.exa_connection
    if exa_connection ~= nil and exa_connection ~= cjson.null then
        require_identifier(tostring(exa_connection), "exa_connection")
    end

    -- Call the orchestrator UDF.
    local ok_udf, udf_res = pquery(
        "SELECT PREPROC_RT.VIRTUAL_RESTORE_V1(:c, :a, :p) AS vr_result",
        { c = CONFD_CONNECTION, a = vr_action, p = pj }
    )
    if not ok_udf then
        error(
            "PREPROC.ADMIN_VIRTUAL_RESTORE: UDF call failed: "
                .. tostring(udf_res.error_message)
        )
    end

    local udf_value = udf_res[1][1]
    if udf_value == null or udf_value == nil then
        error("PREPROC.ADMIN_VIRTUAL_RESTORE: UDF returned no value")
    end

    local udf_str = tostring(udf_value)
    if string.sub(udf_str, 1, 4) == "ERR:" then
        error("PREPROC.ADMIN_VIRTUAL_RESTORE: " .. string.sub(udf_str, 5))
    end

    -- Decode the step-report JSON returned by the UDF.
    local ok_report, report = pcall(cjson.decode, udf_str)
    if not ok_report or type(report) ~= "table" then
        error(
            "PREPROC.ADMIN_VIRTUAL_RESTORE: could not decode UDF result JSON: "
                .. udf_str
        )
    end

    -- Extract fields from report.
    local adapter_jar_path = tostring(report.adapter_jar_path or "")
    local port = report.port
    local connect = tostring(report.connect or "")

    require_safe_jar_path(adapter_jar_path)

    -- DDL: CREATE OR REPLACE JAVA ADAPTER SCRIPT (idempotent).
    local adapter_ddl = "CREATE OR REPLACE JAVA ADAPTER SCRIPT PREPROC.VIRTUAL_RESTORE_ADAPTER AS\n"
        .. "  %scriptclass com.exasol.adapter.RequestDispatcher;\n"
        .. "  %jar " .. adapter_jar_path .. ";"
    local ok_adapter, adapter_err = pquery(adapter_ddl)
    if not ok_adapter then
        error(
            "PREPROC.ADMIN_VIRTUAL_RESTORE: DDL failed (CREATE OR REPLACE JAVA ADAPTER SCRIPT): "
                .. tostring(adapter_err.error_message)
                .. ". The virtual DB/volume remain up — issue STOP VIRTUAL RESTORE to tear down."
        )
    end

    -- DDL: CREATE VIRTUAL SCHEMA per requested schema.
    -- Schema object names are double-quoted to preserve typed case.
    -- vdb_name is pre-validated; schema names are pre-validated.
    -- Connection names are pre-validated; they appear as quoted string VALUES in
    -- WITH clauses, so single-quote escaping would be needed for arbitrary names —
    -- but our identifier validation already prohibits single quotes and non-word
    -- characters, making concatenation safe.
    for i = 1, #schemas do
        local s = tostring(schemas[i])
        local vs_name = vdb_name .. "_" .. s
        local vs_ddl = "CREATE VIRTUAL SCHEMA \"" .. vs_name .. "\""
            .. " USING PREPROC.VIRTUAL_RESTORE_ADAPTER WITH"
            .. " CONNECTION_NAME='" .. tostring(jdbc_connection) .. "'"
            .. " SCHEMA_NAME='" .. s .. "'"
        if exa_connection ~= nil and exa_connection ~= cjson.null and tostring(exa_connection) ~= "" then
            vs_ddl = vs_ddl
                .. " IMPORT_FROM_EXA='true'"
                .. " EXA_CONNECTION='" .. tostring(exa_connection) .. "'"
        end
        local ok_vs, vs_err = pquery(vs_ddl)
        if not ok_vs then
            error(
                "PREPROC.ADMIN_VIRTUAL_RESTORE: DDL failed (CREATE VIRTUAL SCHEMA \""
                    .. vs_name .. "\"): "
                    .. tostring(vs_err.error_message)
                    .. ". The virtual DB/volume remain up — issue STOP VIRTUAL RESTORE to tear down."
            )
        end
    end

    -- Build result rows.
    local rows = {}

    -- Per-step status rows from the orchestrator.
    local steps = report.steps
    if type(steps) == "table" then
        for i = 1, #steps do
            local step = steps[i]
            if type(step) == "table" then
                local field = tostring(step.step or ("step[" .. i .. "]"))
                local detail = step.detail or step.status or ""
                local status = tostring(step.status or "")
                local value = status
                if tostring(detail) ~= "" and tostring(detail) ~= status then
                    value = status .. ": " .. tostring(detail)
                end
                rows[#rows + 1] = { field, value }
            end
        end
    end

    -- One row per created virtual schema.
    for i = 1, #schemas do
        local s = tostring(schemas[i])
        rows[#rows + 1] = { "virtual_schema[" .. i .. "]", vdb_name .. "_" .. s }
    end

    -- Connection / port info.
    rows[#rows + 1] = { "connect", connect }
    rows[#rows + 1] = { "port", tostring(port) }
    rows[#rows + 1] = { "adapter_jar", adapter_jar_path }

    exit(rows, COLS)

elseif vr_action == "stop" then
    -- -----------------------------------------------------------------------
    -- STOP — drop VS schemas, call UDF teardown, conditionally drop adapter
    -- -----------------------------------------------------------------------

    local ok_decode, params = pcall(cjson.decode, pj)
    if not ok_decode or type(params) ~= "table" then
        error("PREPROC.ADMIN_VIRTUAL_RESTORE: could not decode params_json: " .. tostring(pj))
    end

    local vdb_name = params.vdb_name
    if vdb_name == nil or vdb_name == cjson.null then
        vdb_name = "VR1"
    end
    require_identifier(tostring(vdb_name), "vdb_name")

    -- Query EXA_DBA_VIRTUAL_SCHEMAS for all schemas whose name starts with
    -- <vdb_name>_ (the ESCAPE '!' makes '_' literal in the LIKE pattern).
    -- Escape !, _ and % within vdb_name itself so wildcards inside the name
    -- (e.g. VR_PROD) do not match unrelated restores' schemas.
    local escaped_vdb = vdb_name:gsub("[!_%%]", "!%0")
    local ok_ls, ls_res = pquery(
        "SELECT SCHEMA_NAME FROM SYS.EXA_DBA_VIRTUAL_SCHEMAS"
            .. " WHERE SCHEMA_NAME LIKE :pat ESCAPE '!'",
        { pat = escaped_vdb .. "!_%" }
    )
    if not ok_ls then
        error(
            "PREPROC.ADMIN_VIRTUAL_RESTORE: could not query EXA_DBA_VIRTUAL_SCHEMAS: "
                .. tostring(ls_res.error_message)
        )
    end

    -- Collect schema names and drop each one.
    local dropped_schemas = {}
    for i = 1, #ls_res do
        local schema_name = tostring(ls_res[i][1])
        local ok_drop, drop_err = pquery(
            "DROP VIRTUAL SCHEMA \"" .. schema_name .. "\" CASCADE"
        )
        if not ok_drop then
            error(
                "PREPROC.ADMIN_VIRTUAL_RESTORE: DROP VIRTUAL SCHEMA \""
                    .. schema_name .. "\" failed: "
                    .. tostring(drop_err.error_message)
            )
        end
        dropped_schemas[#dropped_schemas + 1] = schema_name
    end

    -- Call the orchestrator UDF for db_stop/db_delete/st_volume_delete.
    local ok_udf, udf_res = pquery(
        "SELECT PREPROC_RT.VIRTUAL_RESTORE_V1(:c, :a, :p) AS vr_result",
        { c = CONFD_CONNECTION, a = vr_action, p = pj }
    )
    if not ok_udf then
        error(
            "PREPROC.ADMIN_VIRTUAL_RESTORE: UDF call failed: "
                .. tostring(udf_res.error_message)
        )
    end

    local udf_value = udf_res[1][1]
    if udf_value == null or udf_value == nil then
        error("PREPROC.ADMIN_VIRTUAL_RESTORE: UDF returned no value")
    end

    local udf_str = tostring(udf_value)
    if string.sub(udf_str, 1, 4) == "ERR:" then
        error("PREPROC.ADMIN_VIRTUAL_RESTORE: " .. string.sub(udf_str, 5))
    end

    -- Decode step report.
    local ok_report, report = pcall(cjson.decode, udf_str)
    if not ok_report or type(report) ~= "table" then
        error(
            "PREPROC.ADMIN_VIRTUAL_RESTORE: could not decode UDF result JSON: "
                .. udf_str
        )
    end

    -- Conditionally drop the adapter script if no other VS still references it.
    -- The adapter reference is split into ADAPTER_SCRIPT_SCHEMA and
    -- ADAPTER_SCRIPT_NAME columns (there is no combined ADAPTER_SCRIPT column).
    local ok_check, check_res = pquery(
        "SELECT COUNT(*) FROM SYS.EXA_DBA_VIRTUAL_SCHEMAS"
            .. " WHERE UPPER(ADAPTER_SCRIPT_SCHEMA) = 'PREPROC'"
            .. " AND UPPER(ADAPTER_SCRIPT_NAME) = 'VIRTUAL_RESTORE_ADAPTER'"
    )
    local adapter_status
    if not ok_check then
        -- If the check query fails, conservatively retain.
        adapter_status = "retained (check failed)"
    else
        local remaining = tonumber(tostring(check_res[1][1])) or 0
        if remaining == 0 then
            local ok_drop_adapter, drop_adapter_err = pquery(
                "DROP ADAPTER SCRIPT PREPROC.VIRTUAL_RESTORE_ADAPTER"
            )
            if ok_drop_adapter then
                adapter_status = "dropped"
            else
                adapter_status = "retained (drop failed: " .. tostring(drop_adapter_err.error_message) .. ")"
            end
        else
            adapter_status = "retained (in use)"
        end
    end

    -- Build result rows.
    local rows = {}

    -- Per-step status rows from the orchestrator.
    local steps = report.steps
    if type(steps) == "table" then
        for i = 1, #steps do
            local step = steps[i]
            if type(step) == "table" then
                local field = tostring(step.step or ("step[" .. i .. "]"))
                local detail = step.detail or step.status or ""
                local status = tostring(step.status or "")
                local value = status
                if tostring(detail) ~= "" and tostring(detail) ~= status then
                    value = status .. ": " .. tostring(detail)
                end
                rows[#rows + 1] = { field, value }
            end
        end
    end

    rows[#rows + 1] = { "adapter_script", adapter_status }
    rows[#rows + 1] = { "status", "OK" }

    exit(rows, COLS)

else
    error(
        "PREPROC.ADMIN_VIRTUAL_RESTORE: unknown action '"
            .. tostring(vr_action)
            .. "' — expected 'start' or 'stop'"
    )
end
/

