CREATE OR REPLACE LUA SCRIPT PREPROC.ADMIN_BUCKETFS_FILE_V1(bf_action, params_json) RETURNS TABLE AS
-- =============================================================================
-- ADMIN_BUCKETFS_FILE  (PREPROC.ADMIN_BUCKETFS_FILE)  — Lua admin script body
-- =============================================================================
-- Admin script for the CONTROL BUCKETFS file-access command family.
-- The CONTROL_BUCKETFS_V1 EXPAND module rewrites UPLOAD/DELETE/LIST/SHOW FILE
-- statements into:
--   EXECUTE SCRIPT PREPROC.ADMIN_BUCKETFS_FILE(bf_action, params_json)
-- This script:
--   1. normalises NULL params,
--   2. calls PREPROC_RT.BUCKETFS_FILE_V1(connection, bf_action, params_json),
--   3. re-raises the UDF's ERR: sentinel as a loud script error,
--   4. shapes the step report into FIELD/VALUE_TEXT rows.
--
-- Output shape
--   Two columns: field VARCHAR(256), value_text VARCHAR(2000000).
--   Same contract as ADMIN_VIRTUAL_RESTORE / ADMIN_CONFD_JOB — never RESULT or
--   VALUE (reserved keywords).
--
-- Row shaping
--   Every step from the UDF report becomes one row using the universal pattern
--   shared with ADMIN_VIRTUAL_RESTORE: field = step.step, value_text = status,
--   or "status: detail" when a distinct detail is present. This is uniform
--   across all four actions:
--     UPLOAD  one 'upload' step row
--     DELETE  one 'delete' step row
--     LIST    one 'file' step row per file (value_text = "ok: <filename>")
--     SHOW    one 'show' step row    (value_text = "ok: <file content>")
--   A final {"status", "OK"} summary row is appended after the step rows.
--
-- Parameters (declared in the CREATE OR REPLACE LUA SCRIPT header by build.py)
--   bf_action    'upload', 'delete', 'list', or 'show'
--                (named bf_action, not action — ACTION is a reserved keyword
--                in Exasol and cannot be used as a script parameter)
--   params_json  JSON object of file-operation parameters; NULL normalised to
--                '{}'.
-- =============================================================================

-- luacheck: read globals bf_action params_json

local CONFD_CONNECTION = "CONFD_CONNECTION"
local COLS = "field VARCHAR(256), value_text VARCHAR(2000000)"

-- Normalise a NULL params_json argument.
local pj = params_json
if pj == null or pj == nil then
    pj = "{}"
end

local cjson = require("cjson")

-- Call the orchestrator UDF.
local ok_udf, udf_res = pquery(
    "SELECT PREPROC_RT.BUCKETFS_FILE_V1(:c, :a, :p) AS bf_result",
    { c = CONFD_CONNECTION, a = bf_action, p = pj }
)
if not ok_udf then
    error(
        "PREPROC.ADMIN_BUCKETFS_FILE: UDF call failed: "
            .. tostring(udf_res.error_message)
    )
end

local udf_value = udf_res[1][1]
if udf_value == null or udf_value == nil then
    error("PREPROC.ADMIN_BUCKETFS_FILE: UDF returned no value")
end

-- Re-raise the UDF's ERR: sentinel as a loud script error (prefix stripped).
local udf_str = tostring(udf_value)
if string.sub(udf_str, 1, 4) == "ERR:" then
    error("PREPROC.ADMIN_BUCKETFS_FILE: " .. string.sub(udf_str, 5))
end

-- Decode the step-report JSON returned by the UDF.
local ok_report, report = pcall(cjson.decode, udf_str)
if not ok_report or type(report) ~= "table" then
    error(
        "PREPROC.ADMIN_BUCKETFS_FILE: could not decode UDF result JSON: "
            .. udf_str
    )
end

-- Build result rows.
local rows = {}

-- Per-step status rows from the orchestrator (one universal pattern for all
-- four actions). LIST emits one 'file' step per file; SHOW carries the file
-- content in the step detail.
local steps = report.steps
if type(steps) == "table" then
    for i = 1, #steps do
        local step = steps[i]
        if type(step) == "table" then
            local field = tostring(step.step or ("step[" .. i .. "]"))
            local detail = step.detail or step.status or ""
            local status = tostring(step.status or "")
            local value = status
            if tostring(detail) ~= "" and tostring(detail) ~= status then
                value = status .. ": " .. tostring(detail)
            end
            rows[#rows + 1] = { field, value }
        end
    end
end

rows[#rows + 1] = { "status", "OK" }

exit(rows, COLS)
/

