CREATE OR REPLACE LUA SCRIPT PREPROC.ADMIN_LICENSE_V1(lic_action, params_json) RETURNS TABLE AS
-- =============================================================================
-- ADMIN_LICENSE  (PREPROC.ADMIN_LICENSE)  — Lua admin script body
-- =============================================================================
-- Admin script for the CONTROL DATABASE INSTALL LICENSE command.
-- The CONTROL_DATABASE_V1 EXPAND module rewrites INSTALL LICENSE statements
-- into:
--   EXECUTE SCRIPT PREPROC.ADMIN_LICENSE(lic_action, params_json)
-- This script:
--   1. normalises NULL params,
--   2. calls PREPROC_RT.LICENSE_INSTALL_V1(connection, lic_action, params_json),
--   3. re-raises the UDF's ERR: sentinel as a loud script error,
--   4. flattens the installed-license fields into FIELD/VALUE_TEXT rows.
--
-- Output shape
--   Two columns: field VARCHAR(256), value_text VARCHAR(2000000).
--   Same contract as ADMIN_VIRTUAL_RESTORE / ADMIN_CONFD_JOB / ADMIN_BUCKETFS_FILE
--   — never RESULT or VALUE (reserved keywords).
--
-- Row shaping
--   The UDF's success payload is a bare JSON object of the installed license
--   fields (no ConfD envelope — LICENSE_INSTALL_V1 already unwraps
--   license_upload's result_output on result_code 0). It is flattened at the
--   root exactly like ADMIN_CONFD_JOB flattens result_output: object keys become
--   dotted paths (sorted for stable output), array elements get a [i] suffix,
--   JSON null becomes the literal "null", and empty containers show as
--   "(empty)". This yields the same row style as SHOW LICENSE, e.g.
--   `Contract.expiration_date | Unlimited`.
--
-- Parameters (declared in the CREATE OR REPLACE LUA SCRIPT header by build.py)
--   lic_action   'install' (named lic_action, not action — ACTION is a reserved
--                keyword in Exasol and cannot be used as a script parameter)
--   params_json  JSON object of install parameters (mode, source_url/license/
--                bucketfs locators); NULL normalised to '{}'.
-- =============================================================================

-- luacheck: read globals lic_action params_json

local CONFD_CONNECTION = "CONFD_CONNECTION"
local COLS = "field VARCHAR(256), value_text VARCHAR(2000000)"

-- Normalise a NULL params_json argument.
local pj = params_json
if pj == null or pj == nil then
    pj = "{}"
end

local cjson = require("cjson")

-- Call the orchestrator UDF.
local ok_udf, udf_res = pquery(
    "SELECT PREPROC_RT.LICENSE_INSTALL_V1(:c, :a, :p) AS lic_result",
    { c = CONFD_CONNECTION, a = lic_action, p = pj }
)
if not ok_udf then
    error(
        "PREPROC.ADMIN_LICENSE: UDF call failed: "
            .. tostring(udf_res.error_message)
    )
end

local udf_value = udf_res[1][1]
if udf_value == null or udf_value == nil then
    error("PREPROC.ADMIN_LICENSE: UDF returned no value")
end

-- Re-raise the UDF's ERR: sentinel as a loud script error (prefix stripped).
local udf_str = tostring(udf_value)
if string.sub(udf_str, 1, 4) == "ERR:" then
    error("PREPROC.ADMIN_LICENSE: " .. string.sub(udf_str, 5))
end

-- Decode the installed-license fields JSON returned by the UDF.
local ok_report, report = pcall(cjson.decode, udf_str)
if not ok_report or type(report) ~= "table" then
    error(
        "PREPROC.ADMIN_LICENSE: could not decode UDF result JSON: "
            .. udf_str
    )
end

-- Flatten an arbitrarily-nested decoded value into FIELD/VALUE_TEXT rows. Object
-- keys are sorted for stable output and joined with '.'; array elements use a
-- [i] suffix; JSON null and empty containers get explicit leaf markers so the
-- operator never sees a blank where a value was expected.
local JNULL = cjson.null
local rows = {}

local function flatten(prefix, value)
    local label = (prefix ~= "" and prefix) or "value"
    if value == JNULL then
        rows[#rows + 1] = { label, "null" }
        return
    end
    if type(value) ~= "table" then
        rows[#rows + 1] = { label, tostring(value) }
        return
    end
    local count = 0
    for _ in pairs(value) do
        count = count + 1
    end
    if count == 0 then
        rows[#rows + 1] = { label, "(empty)" }
    elseif count == #value then
        for i = 1, #value do
            flatten(prefix .. "[" .. i .. "]", value[i])
        end
    else
        local keys = {}
        for k in pairs(value) do
            keys[#keys + 1] = tostring(k)
        end
        table.sort(keys)
        for _, k in ipairs(keys) do
            local child = (prefix == "") and k or (prefix .. "." .. k)
            flatten(child, value[k])
        end
    end
end

flatten("", report)

-- A response that somehow yields no leaves (shouldn't happen for an installed
-- license) still gets a clear confirmation row rather than an empty result set.
if #rows == 0 then
    rows[#rows + 1] = { "status", "OK" }
end

exit(rows, COLS)
/

