CREATE OR REPLACE LUA SCRIPT PREPROC.ADMIN_REMOTE_VOLUME_V1(rv_action, params_json) RETURNS TABLE AS
-- =============================================================================
-- ADMIN_REMOTE_VOLUME  (PREPROC.ADMIN_REMOTE_VOLUME)  — Lua admin script body
-- =============================================================================
-- Admin script for the CONTROL STORAGE remote-volume ADD command.
-- The CONTROL_STORAGE_V1 EXPAND module rewrites
--   ADD REMOTE VOLUME …            -> ADMIN_REMOTE_VOLUME('add', <json>)
-- into:
--   EXECUTE SCRIPT PREPROC.ADMIN_REMOTE_VOLUME(rv_action, params_json)
-- (The family moved from CONTROL DATABASE to CONTROL STORAGE; the rewrite target
-- is unchanged. The detail SHOW no longer comes here at all — it goes straight to
-- the inline REMOTE_VOLUME_QUERY_V1 read UDF.)
-- This script:
--   1. normalises NULL params,
--   2. calls PREPROC_RT.REMOTE_VOLUME_V1(connection, rv_action, params_json),
--   3. re-raises the UDF's ERR: sentinel as a loud script error,
--   4. shapes the UDF's JSON result into FIELD/VALUE_TEXT rows.
--
-- Output shape
--   Two columns: field VARCHAR(256), value_text VARCHAR(2000000).
--   Same contract as ADMIN_BUCKETFS_FILE / ADMIN_VIRTUAL_RESTORE / ADMIN_CONFD_JOB
--   — never RESULT or VALUE (reserved keywords).
--
-- Row shaping
--   'add'   the UDF returns a step report ({"steps":[...]}); shaped with the
--           same universal step pattern as ADMIN_BUCKETFS_FILE: one row per
--           step (field = step.step, value_text = "status" or
--           "status: detail"), plus a trailing {"status","OK"} summary row.
--   Any other rv_action is rejected up front: REMOTE_VOLUME_V1 serves only
--   'add' (the retired 'info' action moved to REMOTE_VOLUME_QUERY_V1), so an
--   unknown action would otherwise reach the UDF and come back as an ERR:
--   sentinel with no useful context.
--
-- Parameters (declared in the CREATE OR REPLACE LUA SCRIPT header by build.py)
--   rv_action    'add' (the only supported action)
--                (named rv_action, not action — ACTION is a reserved keyword
--                in Exasol and cannot be used as a script parameter)
--   params_json  JSON object of remote-volume parameters; NULL normalised to
--                '{}'.
-- =============================================================================

-- luacheck: read globals rv_action params_json

local CONFD_CONNECTION = "CONFD_CONNECTION"
local COLS = "field VARCHAR(256), value_text VARCHAR(2000000)"

-- Normalise a NULL params_json argument.
local pj = params_json
if pj == null or pj == nil then
    pj = "{}"
end

local cjson = require("cjson")

-- 'add' is the only action the orchestrator UDF still serves (the detail SHOW is
-- an inline read UDF now). Reject anything else here rather than letting it come
-- back as a context-free ERR: sentinel from the UDF.
if rv_action ~= "add" then
    error(
        "PREPROC.ADMIN_REMOTE_VOLUME: unsupported action '"
            .. tostring(rv_action)
            .. "' (only 'add' is supported)"
    )
end

-- Call the orchestrator UDF.
local ok_udf, udf_res = pquery(
    "SELECT PREPROC_RT.REMOTE_VOLUME_V1(:c, :a, :p) AS rv_result",
    { c = CONFD_CONNECTION, a = rv_action, p = pj }
)
if not ok_udf then
    error(
        "PREPROC.ADMIN_REMOTE_VOLUME: UDF call failed: "
            .. tostring(udf_res.error_message)
    )
end

local udf_value = udf_res[1][1]
if udf_value == null or udf_value == nil then
    error("PREPROC.ADMIN_REMOTE_VOLUME: UDF returned no value")
end

-- Re-raise the UDF's ERR: sentinel as a loud script error (prefix stripped).
local udf_str = tostring(udf_value)
if string.sub(udf_str, 1, 4) == "ERR:" then
    error("PREPROC.ADMIN_REMOTE_VOLUME: " .. string.sub(udf_str, 5))
end

-- Decode the JSON payload returned by the UDF.
local ok_report, report = pcall(cjson.decode, udf_str)
if not ok_report or type(report) ~= "table" then
    error(
        "PREPROC.ADMIN_REMOTE_VOLUME: could not decode UDF result JSON: "
            .. udf_str
    )
end

-- Build result rows: per-step status rows from the orchestrator, same universal
-- pattern used by ADMIN_BUCKETFS_FILE: field = step.step, value_text = status, or
-- "status: detail" when a distinct detail is present.
local rows = {}

local steps = report.steps
if type(steps) == "table" then
    for i = 1, #steps do
        local step = steps[i]
        if type(step) == "table" then
            local field = tostring(step.step or ("step[" .. i .. "]"))
            local detail = step.detail or step.status or ""
            local status = tostring(step.status or "")
            local value = status
            if tostring(detail) ~= "" and tostring(detail) ~= status then
                value = status .. ": " .. tostring(detail)
            end
            rows[#rows + 1] = { field, value }
        end
    end
end
rows[#rows + 1] = { "status", "OK" }

exit(rows, COLS)
/

